// Generated by tools/site_player.py from the five section shaders. Do not edit.
window.COBO_SET=[{"body":"\n\n\n// ---------------------------------------------------------------- fixed for the v2 review: only Speed and Hit are live\n// Speed 1 is the designed speed, 2.0; the slider is a multiple of it, so the operator never needs the number\nconst float SPEED_DESIGN = 2.0;\n#define motion (speed * SPEED_DESIGN)\nconst float drift = 1.0;\nconst float shapeCount = 6.0;\nconst float feather = 1.0;\nconst float lineWeight = 2.0;\nconst float colourAmt = 1.0;\nconst float tint = 0.0;\nconst float arcFollow = 1.0;\nconst float lift = 1.0;\n\n\n// ---------------------------------------------------------------- helpers\nfloat cv_hash(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.yzx + 33.33);\n  return fract((p.x + p.y) * p.z);\n}\nfloat cv_noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(mix(cv_hash(i + vec3(0,0,0)), cv_hash(i + vec3(1,0,0)), f.x),\n        mix(cv_hash(i + vec3(0,1,0)), cv_hash(i + vec3(1,1,0)), f.x), f.y),\n    mix(mix(cv_hash(i + vec3(0,0,1)), cv_hash(i + vec3(1,0,1)), f.x),\n        mix(cv_hash(i + vec3(0,1,1)), cv_hash(i + vec3(1,1,1)), f.x), f.y), f.z);\n}\nfloat cv_fbm(vec3 p) {\n  return 0.5 * cv_noise(p) + 0.3 * cv_noise(p * 2.03 + 7.1) + 0.2 * cv_noise(p * 4.11 + 13.7);\n}\n// 0 outside [a,d], 1 between b and c\nfloat cv_bump(float x, float a, float b, float c, float d) {\n  return smoothstep(a, b, x) * (1.0 - smoothstep(c, d, x));\n}\nvec3 cv_hsv(float h, float s, float v) {\n  vec3 c = clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);\n  return v * mix(vec3(1.0), c, s);\n}\n// rotate hue around the grey axis; keeps black black and white white\nvec3 cv_hueShift(vec3 c, float h) {\n  vec3 k = vec3(0.57735);\n  float a = h * 6.2832;\n  return c * cos(a) + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - cos(a));\n}\nvec2 cv_rot(vec2 p, float a) {\n  float c = cos(a), s = sin(a);\n  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n// the field the strands are drawn from: loopy warped noise, relaxing into long waves\nfloat cv_strandField(vec2 p, float t, float wave) {\n  float wx = cv_fbm(vec3(p * 1.3, t * 0.0015));\n  float flow = p.y * 0.6 + 0.1 * (wx - 0.5) + 0.06 * sin(p.x * 2.3 + t * 0.002);\n  if (wave >= 1.0) return flow;                                         // all waves: the blob is mixed away\n  vec2 w = vec2(wx, cv_fbm(vec3(p * 1.3 + 5.2, t * 0.0015)));\n  float blob = cv_fbm(vec3(p * vec2(0.4, 0.95) + (w - 0.5) * 0.9, 3.1 + t * 0.001));\n  return mix(blob, flow, wave);\n}\n// the galaxy: x filament ridges, y soft cloud. The lines of track 1 are drawn out of it.\nvec2 cv_galaxy(vec2 p, float t) {\n  vec2 dp = p * 1.6 + vec2(t * 0.0012, t * 0.0004);\n  float cloud = smoothstep(0.42, 0.78, cv_fbm(vec3(dp * 0.9 + 3.0, t * 0.002)));\n  float fil = 1.0 - abs(cv_fbm(vec3(dp * 2.2, t * 0.003)) - 0.5) * 2.0;\n  fil = fil * fil * fil * fil * fil * fil * fil * fil;\n  return vec2(fil, cloud);\n}\n// the closing waves: row j drifting sideways. grow takes it from flat to full height;\n// und makes the height rise and fall along the wave and over time\nfloat cv_waveY(float x, float fj, float t, float grow, float und) {\n  float y0 = (fj - 1.0) * 0.3 + 0.03 * sin(t * 0.001 + fj);\n  float k = 4.0 + fj * 0.9;\n  float ph = t * 0.0035 * (1.0 + 0.3 * fj) + fj * 2.0;\n  float height = mix(1.0, 0.45 + 0.75 * (0.5 + 0.5 * sin(x * 1.1 + t * 0.03 * (1.0 + 0.2 * fj) + fj * 1.7)), und);\n  return y0 + (0.09 + 0.03 * fj) * height * grow * sin(k * x + ph);\n}\n// each wave row's colour once colour has arrived: warm, teal, violet, drifting slowly round\nvec3 cv_rowCol(float fj, float t) {\n  float h = (fj < 0.5 ? 0.07 : (fj < 1.5 ? 0.5 : 0.8)) + 0.04 * sin(t * 0.002 + fj * 2.0);\n  return cv_hsv(fract(h), 0.72, 1.0);\n}\n\n// ---------------------------------------------------------------- arc\n// Arc minutes run on real time; Speed only changes how fast things move. Three tracks of seven minutes.\n// Clamped past 21: holds the coloured waves.\nfloat ARC_dust(float m)     { return smoothstep(0.0, 0.17, m) * (1.0 - smoothstep(7.2, 8.6, m)); } // 1. galaxy up in ~10 s\nfloat ARC_fly(float m)      { return smoothstep(1.5, 3.2, m); }          //    we start drifting into it\nfloat ARC_knots(float m)    { return smoothstep(4.3, 6.3, m); }          //    its gas gathers into glowing knots\nfloat ARC_thin(float m)     { return smoothstep(4.6, 6.2, m); }          //    and its filaments fade, leaving dust and stars\nfloat ARC_ground(float m)   { return cv_bump(m, 8.0, 10.0, 14.2, 15.2); } // 2. the ground takes on colour under the feathers\nfloat ARC_more(float m)     { return smoothstep(8.5, 11.5, m); }         //    more feathers come\nfloat ARC_cycle(float m)    { return smoothstep(10.5, 12.0, m); }        //    and they start fading in and out\nfloat ARC_strands(float m)  { return smoothstep(14.0, 14.6, m); }        // 3. the feathers melt into strands\nfloat ARC_melt(float m)     { return smoothstep(14.1, 14.9, m); }        //    fill blurs out as strands come in\nfloat ARC_sharpen(float m)  { return smoothstep(14.3, 14.9, m); }        //    strands start blurred, then focus\nfloat ARC_spread(float m)   { return smoothstep(14.3, 15.0, m); }        //    and spread past the pieces\nfloat ARC_expand(float m)   { return smoothstep(14.3, 15.4, m); }        //    the thin lines grow outward\nfloat ARC_desat(float m)    { return smoothstep(14.9, 15.7, m); }        //    colour drains to white until 17:01\nfloat ARC_wave(float m)     { return smoothstep(15.1, 15.9, m); }        //    strands relax into long waves\nfloat ARC_ref(float m)      { return smoothstep(15.3, 16.0, m); }        //    the closing waves appear, flat and loose\nfloat ARC_gather(float m)   { return smoothstep(15.5, 16.4, m); }        //    gather into waves\nfloat ARC_undulate(float m) { return smoothstep(16.2, 17.0, m); }        //    their heights start to undulate\n// The Hit is a pluck: a crest runs out from the middle along the waves, both ways, like a plucked string, and reaches\n// the edges in about three seconds. The first press after 16:30 (17:01 in the set) brings the colour, riding out behind\n// the crest; if nobody presses, an unplucked crest brings it at 17:30.\nfloat cv_crestX(float age) { return age * 0.32; }\n// how far the crest lifts wave row j at x, age seconds after the press; the rows follow each other closely\nfloat cv_pluck(float x, float age, float fj) {\n  float a = age - fj * 0.12;\n  if (a < 0.0 || a > 6.0) return 0.0;\n  float d = (abs(x) - cv_crestX(a)) / 0.07;\n  return 0.06 * exp(-a / 2.5) * exp(-d * d);\n}\n// where the crest is passing over the picture before there are waves: a soft vertical band either side of the middle\nfloat cv_band(float x, float age) {\n  if (age < 0.0 || age > 6.0) return 0.0;\n  float d = (abs(x) - cv_crestX(age)) / 0.12;\n  return exp(-age / 2.5) * exp(-d * d);\n}\n// ---------------------------------------------------------------- 1. drifting into the galaxy\n// Three layers of the galaxy at growing scale, each fading in small and far and out large and near, so it reads as\n// moving slowly through it. Returns light.\nfloat cv_flight(vec2 p, float t, float travel, float thin) {\n  float lum = 0.0;\n  for (int i = 0; i < 3; i++) {\n    float fi = float(i);\n    float ph = fract(travel + fi / 3.0);\n    float sc = pow(3.0, ph);\n    vec2 q = p / sc + vec2(fi * 3.7, fi * 1.9);\n    vec2 g = cv_galaxy(q, t + fi * 40.0);\n    vec2 sg = q * 60.0;\n    vec2 si = floor(sg);\n    float star = step(0.972, cv_hash(vec3(si, 3.0 + fi)))\n               * (1.0 - smoothstep(0.0, 0.3, length(fract(sg) - 0.5)))\n               * (0.3 + 0.7 * cv_hash(vec3(si, 9.0 + fi)));\n    float a = sin(3.1416 * ph);\n    lum += ((g.x * 0.45 * (1.0 - thin) + 0.07 * (1.0 - 0.6 * thin)) * g.y + star * (0.2 + 0.8 * g.y) * (1.0 + 0.8 * thin)) * a * 1.05;\n  }\n  return lum;\n}\n// where feather j lives: its own spot in the open frame, wandering there. The knot it blooms from is here too\nvec2 cv_home(float fj, float t) {\n  float h1 = cv_hash(vec3(fj, 21.0, 5.0));\n  float h2 = cv_hash(vec3(fj, 22.0, 6.0));\n  float h3 = cv_hash(vec3(fj, 23.0, 7.0));\n  return vec2((h2 - 0.5) * 1.5, (h3 - 0.5) * 0.7)\n       + vec2(sin(t * 0.0035 * (1.0 + h3) + fj * 2.1), cos(t * 0.0029 * (1.0 + h1) + fj * 1.3)) * vec2(0.22, 0.1);\n}\n// when feather j lifts off its knot, in arc minutes\nfloat cv_birth(float fj) { return 6.3 + fj * 0.3 + cv_hash(vec3(fj, 21.0, 5.0)) * 0.2; }\n\n// ---------------------------------------------------------------- main\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  float aspect = RENDERSIZE.x / RENDERSIZE.y;\n  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);\n  float px = 1.0 / RENDERSIZE.y;\n\n  float tA = TIME * timeScale;                                          // real time: where the arc is\n  float t = tA * motion;                                                // motion time: how fast it moves\n  // Arc Follow 0 holds the section among the feathers (minute 10); sliders only\n  float mA = mix(10.0, min(tA / 60.0, 21.5), arcFollow);\n\n  // ------------------------------------------------ the Hit button\n  // hitAge: seconds since the last press (1e5: never). Every press plucks: a crest runs out along the waves, or a\n  // shimmer runs through the stars and feathers before there are waves. The first press after 16:30 also brings the colour.\n  float pressArc = mA - hitAge / 60.0, prevArc = mA - hitPrevAge / 60.0;\n  float sweepAge = prevArc >= 16.5 ? 1e4 : (pressArc >= 16.5 ? hitAge : -1.0);\n  float autoAge = (mA - 17.5) * 60.0;\n  float autoOn = (pressArc >= 16.5 && pressArc <= 17.5) ? 0.0 : 1.0;  // no unplucked crest when it was pressed\n  float sweep = max(sweepAge, autoAge);                                 // seconds since the colour set off; <0 not yet\n  float colourHere = sweep >= 0.0 ? colourAmt * (1.0 - smoothstep(cv_crestX(sweep) - 0.12, cv_crestX(sweep) + 0.02, abs(p.x))) : 0.0;\n  float band = cv_band(p.x, hitAge) + autoOn * cv_band(p.x, autoAge);\n\n  vec3 col = mix(vec3(0.004, 0.004, 0.008), cv_hsv(fract(0.55 + t * 0.0007), 0.5, 0.11), ARC_ground(mA));\n\n  // ------------------------------------------------ 1. galaxy dust; we drift into it and its gas gathers into knots\n  float dust = ARC_dust(mA);\n  float knots = ARC_knots(mA);\n  if (dust > 0.001) {\n    vec2 gal = cv_galaxy(p, t);\n    vec2 g = (p * 1.6 + vec2(t * 0.0012, t * 0.0004)) * 60.0;\n    vec2 gi = floor(g);\n    float star = step(0.975, cv_hash(vec3(gi, 3.0)))\n               * (1.0 - smoothstep(0.0, 0.3, length(fract(g) - 0.5)))\n               * (0.3 + 0.7 * cv_hash(vec3(gi, 9.0)));\n    float open = smoothstep(1.0 - dust, 1.0, gal.y + 0.25 * dust);\n    float still = (gal.x * 0.45 + 0.07) * gal.y * open + star * (0.2 + 0.8 * gal.y) * dust;\n    float fly = ARC_fly(mA);\n    float lum = mix(still, cv_flight(p, t, t * 0.0005 * drift, ARC_thin(mA)), fly);\n    // the gas thickens toward the knots as they gather, and thins between them\n    float near = 0.0;\n    for (int j = 0; j < 8; j++) {\n      float fj = float(j);\n      if (fj >= shapeCount) break;\n      near += exp(-length(p - cv_home(fj, t)) / 0.22);\n    }\n    lum *= mix(1.0, 0.45 + 0.9 * min(near, 1.4), knots);\n    vec3 gas = mix(vec3(0.72, 0.88, 1.0), vec3(0.82, 0.78, 1.0), knots * 0.6);\n    col += gas * lum * dust * (1.25 + 1.1 * ARC_thin(mA)) * (1.0 + 2.2 * band);\n  }\n\n  // ------------------------------------------------ 2. feathers: each knot ignites and blooms into a colour piece\n  float strands = ARC_strands(mA);\n  bool allWaves = ARC_wave(mA) >= 1.0 && ARC_melt(mA) >= 1.0;           // from 15:54 the feathers draw nothing\n  float cycle = ARC_cycle(mA);\n  float count = mix(3.0, shapeCount, ARC_more(mA));\n  float maskSum = 0.0;\n  vec2 cenSum = vec2(0.0);\n  float cenW = 0.0;\n  vec3 colSum = vec3(0.0);\n  vec3 spark = vec3(0.85, 0.9, 1.0);                                   // the colour of the galaxy's light\n  for (int j = 0; j < 8; j++) {\n    float fj = float(j);\n    if (fj >= shapeCount) break;\n    float h1 = cv_hash(vec3(fj, 21.0, 5.0));\n    float h2 = cv_hash(vec3(fj, 22.0, 6.0));\n    float h3 = cv_hash(vec3(fj, 23.0, 7.0));\n    vec2 pos = cv_home(fj, t);\n    float age = mA - cv_birth(fj);                                       // minutes since it bloomed\n    // before that, a knot of light gathering in the gas where it will bloom\n    float kn = knots * (1.0 - smoothstep(0.0, 0.8, age)) * dust;\n    if (kn > 0.001) {\n      float dk = length(p - pos);\n      float pulse = 0.8 + 0.2 * sin(t * 0.05 + fj * 2.0);\n      col += spark * (exp(-dk / 0.045) * 0.22 + exp(-dk / 0.008) * 0.7) * kn * pulse * (1.0 + 1.5 * band);\n    }\n    float appear = clamp(count - fj, 0.0, 1.0);\n    if (age <= 0.0 || appear <= 0.0) continue;\n\n    float grow = smoothstep(0.1, 1.1, age);\n    float size = mix(0.01, 0.13 + 0.09 * h3, grow);\n    float vis = appear * mix(1.0, smoothstep(-0.3, 0.5, sin(t * 0.0021 * (1.0 + h2) + fj * 1.9)), cycle);\n    vec3 pc = mix(spark, cv_hsv(fract(h1 + t * 0.0011 * (0.6 + 0.8 * h3)), 0.72, 0.95), smoothstep(0.1, 1.2, age));\n\n    cenSum += pos * vis * grow;\n    cenW += vis * grow;\n    if (allWaves) continue;                                             // melted, and mixed out of the strands\n    if (length(p - pos) > size * 3.2) continue;\n\n    // a curved petal, bending slowly, with a ragged powdery edge\n    vec2 l = cv_rot(p - pos, fj * 1.3 + 0.4 * sin(t * 0.0025 + fj)) / size;\n    l.y += 0.18 * band * sin(l.x * 6.0 - hitAge * 9.0);                 // the pluck ripples through it\n    float bend = 0.5 * sin(t * 0.003 + fj * 2.0) + (h2 - 0.5);\n    float hook = 0.35 * (h3 - 0.5) + 0.2 * sin(t * 0.0023 + fj);\n    float y = l.y - bend * (l.x * l.x - 0.3) - hook * l.x * l.x * l.x;\n    float width = 0.45 * max(1.0 - l.x * l.x, 0.0) * (1.0 + 0.45 * l.x * (h1 * 2.0 - 1.0));\n    float sd = max(abs(y) - width, abs(l.x) - 1.0);\n    sd += (cv_fbm(vec3(l * 2.2 + fj * 3.0, t * 0.003)) - 0.5) * 0.35 * feather;\n    sd += (cv_noise(vec3(l * 9.0 + fj, t * 0.004)) - 0.5) * 0.12 * feather;\n    float melt = ARC_melt(mA);\n    float fill = 1.0 - smoothstep(-0.08 - 0.25 * feather - 0.6 * melt, 0.04 + 0.12 * feather + 0.8 * melt, sd);\n    float wide = 1.0 - smoothstep(-0.2, 0.9, sd);\n\n    col = mix(col, pc * (0.88 + 0.2 * cv_noise(vec3(l * 3.0, fj))) * (1.0 + 0.5 * band), fill * vis * (1.0 - melt) * 0.95);\n    maskSum += wide * vis;\n    colSum += pc * wide * vis;\n  }\n\n  // ------------------------------------------------ 3. soft flowing strands, draining to white, relaxing into waves\n  if (strands > 0.001) {\n    float wave = ARC_wave(mA);\n    float sharpen = ARC_sharpen(mA);\n    float pieceMask = clamp(maskSum, 0.0, 1.0);\n    float broad = smoothstep(0.3, 0.62, cv_fbm(vec3(p * 0.7, 9.0 + t * 0.0012)));\n    vec2 cen = cenW > 0.001 ? cenSum / cenW : vec2(0.0);\n    float expand = ARC_expand(mA);\n    float frontL = mix(0.12, 1.3, expand);\n    float by = (p.y - 0.12 * sin(p.x * 1.7 + t * 0.0015)) / 0.3;\n    float mask = max(exp(-by * by), broad * 0.35);\n    if (wave < 1.0) {                                                   // all waves: the flare mask is mixed away\n      float rdist = length((p - cen) * vec2(0.8, 1.0)) + (cv_fbm(vec3(p * 2.5, t * 0.003)) - 0.5) * 0.35 * frontL;\n      float flare = (1.0 - smoothstep(frontL * 0.35, frontL, rdist)) * smoothstep(0.0, 0.25, expand);\n      mask = mix(max(pieceMask, max(broad * ARC_spread(mA), flare)), mask, wave);\n    }\n    vec3 roam = cv_hsv(fract(0.38 + t * 0.0007), 0.6, 0.9);\n    vec3 sc = mix(roam, colSum / max(maskSum, 1e-3), pieceMask);\n    sc = mix(sc, vec3(1.0), max(ARC_desat(mA), wave));\n    sc = mix(sc, cv_rowCol(1.0 + sign(p.y) * 0.9, t), colourHere * 0.6);\n\n    float e = 2.0 * px;\n    float grow = 1.0 + 0.9 * expand;\n    float f0 = cv_strandField(cen + (p - cen) / grow, t, wave);\n    float gx = cv_strandField(cen + (p + vec2(e, 0.0) - cen) / grow, t, wave) - f0;\n    float gy = cv_strandField(cen + (p + vec2(0.0, e) - cen) / grow, t, wave) - f0;\n    float N = 9.0, sub = 5.0;\n    float g = max(length(vec2(gx, gy)) / e, 1e-3);\n    float grp = fract(f0 * N);\n    float bundle = 1.0 - smoothstep(0.0, mix(0.45, 0.3, sharpen), min(grp, 1.0 - grp));\n    float v = fract(f0 * N * sub);\n    float dd = min(v, 1.0 - v) / (N * sub * g);\n    float w = lineWeight * px;\n    float soft = mix(12.0, 0.0, sharpen) * px;\n    float ink = 1.0 - smoothstep(0.5 * w - 0.5 * px, 0.5 * w + px + soft, dd);\n    ink = (ink * mix(0.45, 0.75, sharpen) + 0.2 * exp(-dd / (5.0 * px + soft))) * bundle;\n    ink += 0.12 * bundle * bundle * (1.0 - sharpen);\n    float gate = smoothstep(0.22, 0.65, cv_fbm(vec3(p * vec2(1.2, 3.0), t * 0.002 + f0 * 4.0)));\n    col += sc * ink * gate * mask * strands * (3.2 + 1.2 * band) * (1.0 - 0.7 * ARC_ref(mA));\n  }\n\n  // ------------------------------------------------ 3. the waves: nodes, glints and rays; colour from the big moment\n  float refl = ARC_ref(mA);\n  if (refl > 0.001) {\n    float gather = ARC_gather(mA);\n    float und = ARC_undulate(mA);\n    float w = lineWeight * px;\n    vec3 acc = vec3(0.0);\n    for (int j = 0; j < 3; j++) {\n      float fj = float(j);\n      vec3 rc = mix(vec3(1.0), cv_rowCol(fj, t), colourHere);\n      float k = 4.0 + fj * 0.9;\n      float ph = t * 0.0035 * (1.0 + 0.3 * fj) + fj * 2.0;\n      float yc = cv_waveY(p.x, fj, t, gather, und) + cv_pluck(p.x, hitAge, fj) + autoOn * cv_pluck(p.x, autoAge, fj);\n      float ycR = cv_waveY(p.x + 0.01, fj, t, gather, und) + cv_pluck(p.x + 0.01, hitAge, fj) + autoOn * cv_pluck(p.x + 0.01, autoAge, fj);\n      float ycL = cv_waveY(p.x - 0.01, fj, t, gather, und) + cv_pluck(p.x - 0.01, hitAge, fj) + autoOn * cv_pluck(p.x - 0.01, autoAge, fj);\n      float slope = (ycR - ycL) / 0.02;\n      float norm = 1.0 / sqrt(1.0 + slope * slope);\n      float ink = 0.0;\n      for (int b = 0; b < 5; b++) {\n        float fb = float(b) - 2.0;\n        float off = fb * mix(0.06, 0.005, gather) + 0.02 * (1.0 - gather) * sin(p.x * 3.0 + fb * 2.0 + t * 0.01);\n        float d = abs(p.y - yc - off) * norm;\n        float wt = b == 2 ? mix(0.5, 1.0, gather) : mix(0.4, 0.25, gather);\n        ink += (1.0 - smoothstep(0.5 * w - 0.5 * px, 0.5 * w + px + abs(fb) * px, d)) * wt;\n      }\n      // once coloured, a soft glow of the row's colour under the line, so it carries on a projector\n      float dMain = abs(p.y - yc) * norm;\n      acc += rc * exp(-dMain / 0.025) * 0.22 * colourHere;\n      // nodes at peaks and troughs, some glinting with light-flare rays; bigger than v1, for the projector\n      float nodesOn = smoothstep(0.6, 1.0, gather);\n      float x0 = mod((1.5708 - ph) / k + 1.0, 3.1416 / k) - 1.0;\n      for (int n = 0; n < 7; n++) {\n        float fn = float(n);\n        float xn = x0 + fn * 3.1416 / k;\n        vec2 node = vec2(xn, cv_waveY(xn, fj, t, gather, und) + cv_pluck(xn, hitAge, fj) + autoOn * cv_pluck(xn, autoAge, fj));\n        vec2 dn = p - node;\n        float twinkle = max(step(0.6, cv_hash(vec3(fj, fn, 41.0))), step(0.2, cv_band(xn, hitAge) + autoOn * cv_band(xn, autoAge)));\n        float flareN = 1.0 + 2.5 * (cv_band(xn, hitAge) + autoOn * cv_band(xn, autoAge));   // flaring as the crest passes\n        ink += (exp(-length(dn) / (3.2 * px)) * 1.2 + 0.2 * exp(-length(dn) / (22.0 * px))\n              + twinkle * 0.35 * exp(-abs(dn.x) / (2.0 * px)) * exp(-abs(dn.y) / 0.05)\n              + twinkle * 0.35 * exp(-abs(dn.y) / (2.0 * px)) * exp(-abs(dn.x) / 0.05)) * nodesOn * flareN;\n        if (twinkle > 0.5) {\n          float breathe = 0.6 + 0.4 * sin(t * 0.05 + fj * 3.0 + fn * 1.7);\n          for (int r = 0; r < 3; r++) {\n            float fr = float(r);\n            float ang = (r == 0 ? 1.5708 : (r == 1 ? 0.5 : -0.5)) + 0.08 * sin(t * 0.003 + fn + fr);\n            vec2 ld = vec2(cos(ang), sin(ang));\n            float dl = abs(dn.x * ld.y - dn.y * ld.x);\n            if (dl >= 0.5 * w + px) continue;                           // off the ray: it adds exactly nothing\n            float L = 0.2 + 0.5 * cv_hash(vec3(fj, fn, 43.0 + fr));\n            ink += (1.0 - smoothstep(0.5 * w, 0.5 * w + px, dl)) * exp(-abs(dot(dn, ld)) / L) * 0.6 * breathe * nodesOn;\n          }\n        }\n      }\n      acc += rc * ink;\n    }\n    col += acc * refl * (1.0 + 0.6 * band);\n  }\n\n  col = cv_hueShift(col, tint);\n  col = clamp(col, 0.0, 1.0);\n  col = pow(col, vec3(1.0 / lift));                                   // Lift: raise faint material for a weak projector\n  col += (cv_hash(vec3(uv * RENDERSIZE, 1.0)) - 0.5) / 255.0;          // dither\n  gl_FragColor = vec4(col, 1.0);\n}\n","decl":"uniform float timeScale;uniform float speed;uniform float hitAge;uniform float hitPrevAge;","def":{"timeScale":1.0,"speed":1.0,"hitAge":100000.0,"hitPrevAge":100000.0},"len":1260},{"body":"\n#define CV_TAB_src(i, r) cv_srcRow(float(i), r)\n\n\n// ---------------------------------------------------------------- fixed for the v2 review: only Speed and Hit are live\n// Speed 1 is the designed speed, 4.0; the slider is a multiple of it, so the operator never needs the number\nconst float SPEED_DESIGN = 4.0;\n#define motion (speed * SPEED_DESIGN)\nconst float blobCount = 7.0;\nconst float edgeWobble = 1.0;\nconst float tint = 0.0;\nconst float arcFollow = 1.0;\nconst float lift = 1.0;\n\n// ---------------------------------------------------------------- helpers\nfloat cv_hash(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.yzx + 33.33);\n  return fract((p.x + p.y) * p.z);\n}\nfloat cv_noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(mix(cv_hash(i + vec3(0,0,0)), cv_hash(i + vec3(1,0,0)), f.x),\n        mix(cv_hash(i + vec3(0,1,0)), cv_hash(i + vec3(1,1,0)), f.x), f.y),\n    mix(mix(cv_hash(i + vec3(0,0,1)), cv_hash(i + vec3(1,0,1)), f.x),\n        mix(cv_hash(i + vec3(0,1,1)), cv_hash(i + vec3(1,1,1)), f.x), f.y), f.z);\n}\nfloat cv_fbm(vec3 p) {\n  return 0.5 * cv_noise(p) + 0.3 * cv_noise(p * 2.03 + 7.1) + 0.2 * cv_noise(p * 4.11 + 13.7);\n}\n// 0 outside [a,d], 1 between b and c\nfloat cv_bump(float x, float a, float b, float c, float d) {\n  return smoothstep(a, b, x) * (1.0 - smoothstep(c, d, x));\n}\nvec3 cv_hsv(float h, float s, float v) {\n  vec3 c = clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);\n  return v * mix(vec3(1.0), c, s);\n}\n// rotate hue around the grey axis; keeps black black and white white\nvec3 cv_hueShift(vec3 c, float h) {\n  vec3 k = vec3(0.57735);\n  float a = h * 6.2832;\n  return c * cos(a) + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - cos(a));\n}\nvec3 cv_screen(vec3 a, vec3 b) {\n  return vec3(1.0) - (vec3(1.0) - a) * (vec3(1.0) - b);\n}\nvec2 cv_rot(vec2 p, float a) {\n  float c = cos(a), s = sin(a);\n  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\n// ---------------------------------------------------------------- section 1's end, on section 1's clock\n// Section 1 (v13) as it stands at 21:00: its coloured waves with their glow, nodes and rays, and the faint strands\n// behind them, drawn with section 1's own code. t1 is section 1's motion clock: its real time (this section's plus\n// 1260 s) times its Speed of 2. So this section's 0:00 is section 1's 21:00 exactly.\nconst float S1_SPEED = 2.0;\nfloat cv_s1Field(vec2 p, float t) {                                     // section 1's strand field with its waves in\n  float wx = cv_fbm(vec3(p * 1.3, t * 0.0015));\n  return p.y * 0.6 + 0.1 * (wx - 0.5) + 0.06 * sin(p.x * 2.3 + t * 0.002);\n}\nfloat cv_s1WaveY(float x, float fj, float t) {\n  float y0 = (fj - 1.0) * 0.3 + 0.03 * sin(t * 0.001 + fj);\n  float k = 4.0 + fj * 0.9;\n  float ph = t * 0.0035 * (1.0 + 0.3 * fj) + fj * 2.0;\n  float height = mix(1.0, 0.45 + 0.75 * (0.5 + 0.5 * sin(x * 1.1 + t * 0.03 * (1.0 + 0.2 * fj) + fj * 1.7)), 1.0);\n  return y0 + (0.09 + 0.03 * fj) * height * 1.0 * sin(k * x + ph);\n}\nvec3 cv_s1RowCol(float fj, float t) {\n  float h = (fj < 0.5 ? 0.07 : (fj < 1.5 ? 0.5 : 0.8)) + 0.04 * sin(t * 0.002 + fj * 2.0);\n  return cv_hsv(fract(h), 0.72, 1.0);\n}\nvec2 cv_s1Home(float fj, float t) {\n  float h1 = cv_hash(vec3(fj, 21.0, 5.0));\n  float h2 = cv_hash(vec3(fj, 22.0, 6.0));\n  float h3 = cv_hash(vec3(fj, 23.0, 7.0));\n  return vec2((h2 - 0.5) * 1.5, (h3 - 0.5) * 0.7)\n       + vec2(sin(t * 0.0035 * (1.0 + h3) + fj * 2.1), cos(t * 0.0029 * (1.0 + h1) + fj * 1.3)) * vec2(0.22, 0.1);\n}\nvec3 cv_s1end(vec2 p, float t, float px) {\n  vec3 col = mix(vec3(0.004, 0.004, 0.008), cv_hsv(fract(0.55 + t * 0.0007), 0.5, 0.11), 0.0);\n  // the strands grow out from where section 1's pieces are\n  vec2 cenSum = vec2(0.0);\n  float cenW = 0.0;\n  for (int j = 0; j < 6; j++) {\n    float fj = float(j);\n    float h2 = cv_hash(vec3(fj, 22.0, 6.0));\n    float vis = 1.0 * mix(1.0, smoothstep(-0.3, 0.5, sin(t * 0.0021 * (1.0 + h2) + fj * 1.9)), 1.0);\n    cenSum += cv_s1Home(fj, t) * vis * 1.0;\n    cenW += vis * 1.0;\n  }\n  vec2 cen = cenW > 0.001 ? cenSum / cenW : vec2(0.0);\n  float broad = smoothstep(0.3, 0.62, cv_fbm(vec3(p * 0.7, 9.0 + t * 0.0012)));\n  float by = (p.y - 0.12 * sin(p.x * 1.7 + t * 0.0015)) / 0.3;\n  float mask = max(exp(-by * by), broad * 0.35);\n  vec3 sc = mix(vec3(1.0), cv_s1RowCol(1.0 + sign(p.y) * 0.9, t), 0.6);\n  float e = 2.0 * px;\n  float f0 = cv_s1Field(cen + (p - cen) / 1.9, t);\n  float gx = cv_s1Field(cen + (p + vec2(e, 0.0) - cen) / 1.9, t) - f0;\n  float gy = cv_s1Field(cen + (p + vec2(0.0, e) - cen) / 1.9, t) - f0;\n  float N = 9.0, sub = 5.0;\n  float g = max(length(vec2(gx, gy)) / e, 1e-3);\n  float grp = fract(f0 * N);\n  float bundle = 1.0 - smoothstep(0.0, mix(0.45, 0.3, 1.0), min(grp, 1.0 - grp));\n  float v = fract(f0 * N * sub);\n  float dd = min(v, 1.0 - v) / (N * sub * g);\n  float w = 2.0 * px;\n  float ink = 1.0 - smoothstep(0.5 * w - 0.5 * px, 0.5 * w + px, dd);\n  ink = (ink * 0.75 + 0.2 * exp(-dd / (5.0 * px))) * bundle;\n  float gate = smoothstep(0.22, 0.65, cv_fbm(vec3(p * vec2(1.2, 3.0), t * 0.002 + f0 * 4.0)));\n  col += sc * ink * gate * mask * 3.2 * 0.3;\n  // the waves, their glow, glinting nodes and rays\n  vec3 acc = vec3(0.0);\n  for (int j = 0; j < 3; j++) {\n    float fj = float(j);\n    vec3 rc = cv_s1RowCol(fj, t);\n    float k = 4.0 + fj * 0.9;\n    float ph = t * 0.0035 * (1.0 + 0.3 * fj) + fj * 2.0;\n    float yc = cv_s1WaveY(p.x, fj, t);\n    float slope = (cv_s1WaveY(p.x + 0.01, fj, t) - cv_s1WaveY(p.x - 0.01, fj, t)) / 0.02;\n    float norm = 1.0 / sqrt(1.0 + slope * slope);\n    float wink = 0.0;\n    for (int b = 0; b < 5; b++) {\n      float fb = float(b) - 2.0;\n      float d = abs(p.y - yc - fb * 0.005) * norm;\n      float wt = b == 2 ? 1.0 : 0.25;\n      wink += (1.0 - smoothstep(0.5 * w - 0.5 * px, 0.5 * w + px + abs(fb) * px, d)) * wt;\n    }\n    acc += rc * exp(-abs(p.y - yc) * norm / 0.025) * 0.22;\n    float x0 = mod((1.5708 - ph) / k + 1.0, 3.1416 / k) - 1.0;\n    for (int n = 0; n < 7; n++) {\n      float fn = float(n);\n      float xn = x0 + fn * 3.1416 / k;\n      vec2 dn = p - vec2(xn, cv_s1WaveY(xn, fj, t));\n      float twinkle = step(0.6, cv_hash(vec3(fj, fn, 41.0)));\n      wink += (exp(-length(dn) / (3.2 * px)) * 1.2 + 0.2 * exp(-length(dn) / (22.0 * px))\n             + twinkle * 0.35 * exp(-abs(dn.x) / (2.0 * px)) * exp(-abs(dn.y) / 0.05)\n             + twinkle * 0.35 * exp(-abs(dn.y) / (2.0 * px)) * exp(-abs(dn.x) / 0.05));\n      if (twinkle > 0.5) {\n        float breathe = 0.6 + 0.4 * sin(t * 0.05 + fj * 3.0 + fn * 1.7);\n        for (int r = 0; r < 3; r++) {\n          float fr = float(r);\n          float ang = (r == 0 ? 1.5708 : (r == 1 ? 0.5 : -0.5)) + 0.08 * sin(t * 0.003 + fn + fr);\n          vec2 ld = vec2(cos(ang), sin(ang));\n          float dl = abs(dn.x * ld.y - dn.y * ld.x);\n          if (dl >= 0.5 * w + px) continue;                             // off the ray: it adds exactly nothing\n          float L = 0.2 + 0.5 * cv_hash(vec3(fj, fn, 43.0 + fr));\n          wink += (1.0 - smoothstep(0.5 * w, 0.5 * w + px, dl)) * exp(-abs(dot(dn, ld)) / L) * 0.6 * breathe;\n        }\n      }\n    }\n    acc += rc * wink;\n  }\n  return col + acc;\n}\n\n// ---------------------------------------------------------------- palettes\n// four palettes, in arc order: green-blue, orange-red on green, pink-green, blue-violet. h picks one of three colours\nvec3 cv_pal(float i, float h) {\n  vec3 a, b, c;\n  if (i < 0.5)      { a = vec3(0.35, 0.85, 0.35); b = vec3(0.10, 0.62, 0.70); c = vec3(0.85, 0.80, 0.25); }\n  else if (i < 1.5) { a = vec3(1.00, 0.42, 0.10); b = vec3(0.72, 0.55, 1.00); c = vec3(0.70, 0.95, 0.30); }\n  else if (i < 2.5) { a = vec3(1.00, 0.45, 0.70); b = vec3(0.50, 0.95, 0.62); c = vec3(0.55, 0.75, 1.00); }\n  else              { a = vec3(0.45, 0.33, 0.95); b = vec3(0.20, 0.48, 1.00); c = vec3(0.95, 0.55, 0.22); }\n  return h < 0.4 ? a : (h < 0.72 ? b : c);\n}\nvec3 cv_ground(float i) {\n  if (i < 0.5) return vec3(0.010, 0.050, 0.030);\n  if (i < 1.5) return vec3(0.020, 0.070, 0.020);\n  if (i < 2.5) return vec3(0.060, 0.030, 0.050);\n  return vec3(0.090, 0.060, 0.220);\n}\nvec3 cv_palette(float idx, float h) {\n  float i0 = min(floor(idx), 3.0);\n  float f = smoothstep(0.0, 1.0, idx - i0);\n  return mix(cv_pal(i0, h), cv_pal(min(i0 + 1.0, 3.0), h), f);\n}\n// the palette's three colours in a loop, blended smoothly: nothing that drifts through it ever shows an edge\nvec3 cv_paletteSmooth(float idx, float h) {\n  float x = fract(h) * 3.0;\n  float k = floor(x), f = smoothstep(0.0, 1.0, fract(x));\n  float h0 = k < 0.5 ? 0.2 : (k < 1.5 ? 0.56 : 0.86);\n  float h1 = k < 0.5 ? 0.56 : (k < 1.5 ? 0.86 : 0.2);\n  return mix(cv_palette(idx, h0), cv_palette(idx, h1), f);\n}\nvec3 cv_groundMix(float idx) {\n  float i0 = min(floor(idx), 3.0);\n  return mix(cv_ground(i0), cv_ground(min(i0 + 1.0, 3.0)), smoothstep(0.0, 1.0, idx - i0));\n}\n\n// where shape j lives: its own spot in the frame, wandering slowly\nvec2 cv_home(float fj, float t) {\n  float h1 = cv_hash(vec3(fj, 21.0, 5.0));\n  float h2 = cv_hash(vec3(fj, 22.0, 6.0));\n  float h3 = cv_hash(vec3(fj, 23.0, 7.0));\n  return vec2((h2 - 0.5) * 1.45, (h3 - 0.5) * 0.7)\n       + vec2(sin(t * 0.0031 * (1.0 + h3) + fj * 2.1), cos(t * 0.0026 * (1.0 + h1) + fj * 1.3)) * vec2(0.22, 0.14);\n}\n\n// the pastel wash, as v1 drew it (mint, pink and sky in soft flowing regions), with a faint settling of pigment\nvec3 cv_wash(vec2 p, float t) {\n  vec2 w = vec2(cv_fbm(vec3(p * 0.9, t * 0.002)), cv_fbm(vec3(p * 0.9 + 5.2, t * 0.002))) - 0.5;\n  float f = cv_fbm(vec3((p + w * 1.3) * 0.7, t * 0.0025));\n  float g = cv_fbm(vec3((p - w * 0.9) * 0.6 + 4.0, t * 0.002));\n  vec3 c = mix(vec3(0.55, 0.72, 1.0), vec3(1.0, 0.52, 0.86), smoothstep(0.35, 0.68, g));\n  c = mix(c, vec3(0.72, 0.98, 0.55), smoothstep(0.5, 0.68, f) * 0.9);\n  c = mix(c, vec3(0.88, 0.86, 0.95), 0.15);\n  return c * (0.97 + 0.08 * (cv_fbm(vec3(p * 4.0, t * 0.001)) - 0.5));\n}\n// the deep wash, as v1 drew it: broad bands of violet, coral, gold and teal\nvec3 cv_washDeep(vec2 p, float t) {\n  vec2 w = vec2(cv_fbm(vec3(p * 0.9, t * 0.002)), cv_fbm(vec3(p * 0.9 + 5.2, t * 0.002))) - 0.5;\n  float f = cv_fbm(vec3((p + w * 1.1) * 0.55, t * 0.002));\n  float g = cv_fbm(vec3((p - w * 0.8) * 0.5 + 7.0, t * 0.0018));\n  vec3 c = mix(vec3(0.36, 0.2, 0.62), vec3(0.98, 0.46, 0.42), smoothstep(0.32, 0.6, f));\n  c = mix(c, vec3(1.0, 0.78, 0.32), smoothstep(0.55, 0.75, g) * 0.85);\n  c = mix(c, vec3(0.16, 0.6, 0.62), smoothstep(0.62, 0.8, f + (0.5 - g) * 0.5) * 0.8);\n  return c * (0.97 + 0.08 * (cv_fbm(vec3(p * 4.0 + 3.0, t * 0.001)) - 0.5));\n}\n\n// ---------------------------------------------------------------- arc\n// Arc minutes run on real time; Speed only changes how fast things move. Three tracks of about 6:20.\nfloat ARC_s1(float m)      { return 1.0 - smoothstep(0.02, 0.45, m); }      // 1. section 1's waves, giving way to its front one\nfloat ARC_outline(float m) { return 1.0 - smoothstep(1.1, 2.3, m); }        //    the line, gone once the colour is in\nfloat ARC_thicken(float m) { return smoothstep(0.05, 0.75, m); }            //    the line thickens into a band\nfloat ARC_seep(float m)    { return smoothstep(0.9, 2.1, m); }              //    colour seeps in from the middle of each outline\nfloat ARC_settle(float m)  { return smoothstep(1.5, 5.0, m); }              //    shapes leave the line for their own spots\nfloat ARC_close(float m, float fj) { return smoothstep(0.45 + 0.07 * fj, 1.6 + 0.07 * fj, m); }\nfloat ARC_field(float m)   { return smoothstep(2.0, 3.2, m); }              //    the shapes hand over to the glowing field\nfloat ARC_swell(float m)   { return cv_bump(m, 2.3, 4.8, 5.8, 7.2); }       //    which swells and flows together\nfloat ARC_flow(float m)    { return cv_bump(m, 2.6, 4.6, 6.4, 7.6); }       //    the colours running through one another\nfloat ARC_glide(float m)   { return smoothstep(6.2, 7.8, m) * (1.0 - smoothstep(12.4, 13.9, m)); } // 2. condensing, gliding\nfloat ARC_line(float m)    { return smoothstep(12.4, 14.0, m); }            // 3. onto the middle line, as lobes\nfloat ARC_dark(float m)    { return smoothstep(6.0, 7.8, m); }              //    the ground darkens from track 2\n// palette: green-blue, then warm orange-red, cooling through pink-green to blue-violet\nfloat ARC_palette(float m) { return smoothstep(4.8, 6.8, m) + smoothstep(8.8, 10.5, m) + smoothstep(11.0, 12.8, m); }\n\n// ---------------------------------------------------------------- the colour sources\n// Source j: where it is and how big (rx, ry), blending the layouts by track weight, so the sources travel between them.\n// Track 2 breathes: a soft drifting cloud that every ~100 s (at Speed 4) gathers into a stepped echo sweeping across,\n// then dissolves back. gesture(t) is how gathered it is; each sweep has its own direction, height and tilt.\nfloat cv_gesture(float t) {\n  float ph = fract(t / 400.0);\n  return cv_bump(ph, 0.12, 0.38, 0.62, 0.88);\n}\nvec4 cv_source(float fj, float t, float swell, float glide, float line, float fill) {\n  float h1 = cv_hash(vec3(fj, 31.0, 1.0));\n  float h2 = cv_hash(vec3(fj, 32.0, 2.0));\n  float h3 = cv_hash(vec3(fj, 33.0, 3.0));\n  // track 1: its own spot, wandering; big and round, swelling\n  vec2 p1 = cv_home(fj, t);\n  float r1 = (0.13 + 0.15 * h2) * (0.8 + 0.3 * sin(h3 * 6.2832 + t * 0.0012)) * (1.0 + 1.6 * swell);\n  // track 2, the cloud: one loose group drifting and turning, big and overlapping\n  vec2 g2 = vec2(0.3 * sin(t * 0.0011), 0.08 * sin(t * 0.0009 + 1.0));\n  float a2 = fj * 1.7 + 0.6 + t * 0.0016 + 0.4 * sin(t * 0.0013 + fj);\n  vec2 pc = g2 + vec2(cos(a2), sin(a2)) * vec2(0.38, 0.22) * (0.6 + 0.4 * h1);\n  vec2 rc = vec2(0.2 + 0.08 * h3);\n  // track 2, the gesture: a stepped echo (05, 27) sweeping across, its lead further along each time\n  float n = floor(t / 400.0);\n  float dir = mod(n, 2.0) < 0.5 ? 1.0 : -1.0;\n  float ph = fract(t / 400.0);\n  float r0 = 0.1;\n  vec2 lead = vec2(dir * (-0.7 + 1.1 * ph), (cv_hash(vec3(n, 5.0, 1.0)) - 0.5) * 0.35);\n  float tilt = (cv_hash(vec3(n, 6.0, 1.0)) - 0.5) * 0.5;\n  vec2 back = vec2(-dir, tilt) * r0 * (0.9 * fj + 0.1 * fj * fj);\n  vec2 pe = lead + back + vec2(0.0, 0.05 * sin(fj * 0.55 + t * 0.0021) * fj / 6.0);\n  vec2 re = r0 * vec2(0.6 + 0.1 * fj, 1.0 + 0.38 * fj);\n  float gs = cv_gesture(t);\n  vec2 p2 = mix(pc, pe, gs), rr2 = mix(rc, re, gs);\n  // track 3: lobes on the middle line; their heights ride one smooth wave travelling along the row, so neighbours are\n  // related without mirroring each other\n  float k = fj - 3.0;\n  float wv = cv_noise(vec3(fj * 0.33 - t * 0.0016, t * 0.0021, 5.0));\n  float hgt = 0.05 + 0.4 * pow(wv, 1.6);\n  vec2 p3 = vec2(k * 0.22 + 0.03 * sin(t * 0.002 + fj * 1.3), 0.0);\n  // wide enough that neighbours touch and run into one band (26); at the big moment they swell to fill the frame\n  vec2 rr3 = vec2(0.12 + 0.06 * cv_noise(vec3(fj * 0.5, t * 0.0013, 9.0)), hgt) * vec2(1.0 + 1.8 * fill, 1.0 + 3.0 * fill)\n           + vec2(0.0, 0.25 * fill);\n  vec2 rr = mix(mix(vec2(r1), rr2, glide), rr3, line);\n  vec2 pos = mix(mix(p1, p2, glide), p3, line);\n  return vec4(pos, rr);\n}\n// three colours for source j: its heart, its body and its glowing edge. The palette's own variety throughout; while an\n// echo gathers, graduated along the chain from the palette's warm colour to its cool one\nvoid cv_ramp(float fj, float idx, float t, float glide, float line, out vec3 a, out vec3 b, out vec3 c) {\n  float h3 = cv_hash(vec3(fj, 33.0, 3.0));\n  a = cv_palette(idx, fract(h3 + fj * 0.37));\n  b = cv_palette(idx + 0.5, fract(h3 + fj * 0.37 + 0.34));\n  c = cv_palette(idx + 0.9, fract(h3 + fj * 0.37 + 0.68));\n  float u = fj / 6.0, g = glide * cv_gesture(t) * 0.7;\n  a = mix(a, mix(cv_paletteSmooth(idx, 0.2), cv_paletteSmooth(idx, 0.56), u), g);\n  b = mix(b, mix(cv_paletteSmooth(idx, 0.3), cv_paletteSmooth(idx, 0.86), u), g);\n  // as lobes: 26's warm hearts and cool glow, each lobe its own mix\n  float e = cv_noise(vec3(fj * 0.6, t * 0.001, 2.0));\n  a = mix(a, mix(vec3(1.0, 0.62, 0.25), vec3(1.0, 0.42, 0.62), e), line * 0.85);\n  b = mix(b, mix(vec3(1.0, 0.4, 0.55), vec3(0.75, 0.38, 0.95), e), line * 0.85);\n  c = mix(c, vec3(0.3, 0.42, 1.0), line * 0.85);\n}\n\n// ---------------------------------------------------------------- where the section is\n// Shared by main() and the table below, so the two never disagree about the clock or the big moment.\nfloat cv_tA() { return TIME * timeScale; }                              // real time: where the arc is\nfloat cv_t() { return cv_tA() * motion; }                               // motion time: how fast it moves\nfloat cv_mA() { return mix(9.0, min(cv_tA() / 60.0, 19.5), arcFollow); }\n// when the big wash set off, in minutes: the first press between 16:00 and 17:00, or 17:00 if nobody presses\nfloat cv_W(float mA) {\n  float pressArc = mA - hitAge / 60.0, prevArc = mA - hitPrevAge / 60.0;\n  if (prevArc >= 16.0 && prevArc <= 17.0) return prevArc;\n  if (pressArc >= 16.0 && pressArc <= 17.0) return pressArc;\n  return 17.0;\n}\nfloat cv_fillT(float wsec) { return 0.55 * smoothstep(0.0, 8.0, wsec) * (1.0 - smoothstep(12.0, 35.0, wsec)); }\n\n// Where each colour source is this frame, how big, and its three colours. None of it depends on the pixel, so it is\n// drawn once into a small texture instead of being recomputed seven times for every pixel. Without the @table line\n// the same function is called inline and the picture is identical, only slower. See conventions.md.\n// Row 0: position and size. Rows 1-3: heart, body and edge colours.\n\n// @table src 7 4\nvec4 cv_srcRow(float fj, int row) {\n  float t = cv_t(), mA = cv_mA();\n  float glide = ARC_glide(mA), lineT = ARC_line(mA);\n  if (row == 0) return cv_source(fj, t, ARC_swell(mA), glide, lineT, cv_fillT((mA - cv_W(mA)) * 60.0));\n  vec3 ca, cb, cc;\n  cv_ramp(fj, ARC_palette(mA), t, glide, lineT, ca, cb, cc);\n  return vec4(row == 1 ? ca : (row == 2 ? cb : cc), 0.0);\n}\n\n// ---------------------------------------------------------------- the watercolour pieces\n// One soft shape of pigment. sd is its signed distance in its own units (negative inside), r its size. pool 0 is the\n// soft glowing shape of track 1; pool 1 is watercolour: a wet edge where the pigment gathers, granulation, a lighter\n// middle. Returns colour and coverage.\nvec4 cv_pigment(float sd, float r, vec3 base, vec2 p, float fj, float t, float pool, float px) {\n  float blurW = r * mix(0.3, 0.05, pool) + 0.003;\n  float inside = 1.0 - smoothstep(-blurW, blurW + 1.5 * px, sd);\n  float depth = clamp(-sd / max(r, 0.02), 0.0, 1.0);\n  float wet = exp(-max(-sd, 0.0) / (0.045 * r + 0.003)) * inside;      // the pigment gathered at the edge\n  // pigment settling: a faint fine grain and slow blotches, never noise\n  vec3 soft = mix(base, mix(base, vec3(1.0), 0.5), smoothstep(0.2, 1.0, depth));\n  if (pool <= 0.0) return vec4(soft, inside * 0.72);                   // the soft shape: no watercolour to settle\n  float gran = 0.95 + 0.06 * cv_noise(vec3(p * 140.0 + fj, 1.0)) + 0.14 * (cv_fbm(vec3(p * 5.0 + fj, t * 0.0008)) - 0.5);\n  vec3 water = base * mix(0.8, 0.62, smoothstep(0.15, 0.9, depth)) * gran;   // paler in the middle, where the water was\n  water = mix(water, base * 1.1 + (base - vec3(dot(base, vec3(0.33)))) * 0.45, wet * 0.85);\n  vec3 c = mix(soft, water, pool);\n  float a = inside * mix(0.72, 0.58 + 0.4 * wet, pool);\n  return vec4(c, a);\n}\n\n// ---------------------------------------------------------------- main\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  float aspect = RENDERSIZE.x / RENDERSIZE.y;\n  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);\n  float px = 1.0 / RENDERSIZE.y;\n\n  float tA = cv_tA();                                                   // real time: where the arc is\n  float t = cv_t();                                                     // motion time: how fast it moves\n  float t1 = (tA + 1260.0) * S1_SPEED;                                  // section 1's motion clock\n  float mA = cv_mA();\n\n  // ------------------------------------------------ the Hit button\n  // hitAge: seconds since the last press (1e5: never). Every press brings a wash. The first press between 16:00 and\n  // 17:00 is the big one (at 17:00 if nobody presses); as it draws back, the stripes that end the section come in.\n  float W = cv_W(mA);                                                   // when the big wash set off, in minutes\n  float wsec = (mA - W) * 60.0;                                         // seconds since; negative before\n\n  float idx = ARC_palette(mA);\n  float groundOn = smoothstep(1.8, 3.6, mA) * (1.0 - 0.8 * ARC_dark(mA)) * (1.0 - smoothstep(20.0, 50.0, wsec));\n  vec3 col = cv_groundMix(idx) * groundOn;\n\n  float outline = ARC_outline(mA);\n  float thicken = ARC_thicken(mA);\n  float seep = ARC_seep(mA);\n  float settle = ARC_settle(mA);\n  float infl = 0.0;                                                     // how near the colour this pixel is, for the washes\n\n  // one shared warp so every edge moves like the same hand drew it\n  vec2 warp = vec2(cv_fbm(vec3(p * 1.7, t * 0.004)), cv_fbm(vec3(p * 1.7 + 5.2, t * 0.004))) - 0.5;\n  float played = t * 0.006 + 1.5 * sin(t * 0.0021) + 0.8 * sin(t * 0.0053 + 1.0);\n  // the grain that feathers every soft edge: fine, and moving, like film\n  float grain = cv_hash(vec3(uv * RENDERSIZE, floor(tA * 12.0)));\n\n  // ------------------------------------------------ 1. section 1's waves, giving way to their front one\n  float s1 = ARC_s1(mA);\n  if (s1 > 0.001) col = mix(col, col + cv_s1end(p, t1, px), s1);\n\n  // ------------------------------------------------ 1. the shapes: out of the line, glowing (as v1 drew them)\n  float fieldOn = ARC_field(mA);\n  float shapesOn = 1.0 - fieldOn;\n  float wave0 = cv_s1WaveY(p.x, 0.0, t1);\n  float slope = (cv_s1WaveY(p.x + 0.01, 0.0, t1) - cv_s1WaveY(p.x - 0.01, 0.0, t1)) / 0.02;\n  float dBand = abs(p.y - wave0) / sqrt(1.0 + slope * slope) - 0.07 * thicken;\n  vec3 lineCol = cv_s1RowCol(0.0, t1);\n  if (shapesOn > 0.001) {\n    for (int j = 0; j < 7; j++) {\n      float fj = float(j);\n      float h1 = cv_hash(vec3(fj, 31.0, 1.0));\n      float h2 = cv_hash(vec3(fj, 32.0, 2.0));\n      float h3 = cv_hash(vec3(fj, 33.0, 3.0));\n      float close = ARC_close(mA, fj);\n      float xOn = (fract(h1 + fj * 0.618) - 0.5) * 1.5;\n      vec2 cen = mix(vec2(xOn, cv_s1WaveY(xOn, 0.0, t1)), cv_home(fj, t), settle);\n      float r = (0.13 + 0.15 * h2) * (0.8 + 0.3 * sin(h3 * 6.2832 + t * 0.0012)) * mix(0.35, 1.0, smoothstep(1.0, 4.0, mA));\n      vec2 d = p - cen;\n      float dCirc = length(d * vec2(1.0 + 0.25 * sin(h1 * 6.0 + t * 0.002), 1.0)) - r;\n      if (close > 0.999 && dCirc > r * 0.9 + 0.2) continue;\n      float reachFade = 1.0 - smoothstep(r * 0.4 + 0.08, r * 0.9 + 0.2, dCirc);\n      float sd = dBand;\n      if (close > 0.0) {                                                // still the line: the edge noise is mixed away\n        float lobes = (cv_fbm(vec3((d + warp * 0.3) * 1.6 / max(r, 0.05) * 0.5 + fj * 7.3, played * 0.6 + fj)) - 0.5) * 1.3 * r;\n        float wob = (cv_noise(vec3(d * 9.0 + fj * 3.1, played * 1.5)) - 0.5) * 0.15 * r;\n        float fuzz = (cv_noise(vec3(p * 38.0 + fj, t * 0.01)) - 0.5) * 0.05 * r;\n        sd = mix(dBand, dCirc + (lobes + wob) * edgeWobble + fuzz * close, close);\n      }\n      vec3 base = cv_palette(idx, fract(h3 + fj * 0.37));\n      if (outline > 0.001) {\n        float lw = mix(2.0, 3.0, thicken) * px;\n        float ink = 1.0 - smoothstep(0.5 * lw - 0.5 * px, 0.5 * lw + px, abs(sd));\n        ink += 0.25 * exp(-abs(sd) / (6.0 * px));\n        col = cv_screen(col, lineCol * ink * outline * (1.0 - 0.7 * seep) * (1.0 - s1));\n      }\n      float depth = clamp(-sd / max(r, 0.02), 0.0, 1.0);\n      float seepFront = smoothstep(1.0 - seep * 1.2, 1.0 - seep * 1.2 + 0.5, depth);\n      vec4 pg = cv_pigment(sd, r, base, p, fj, t, 0.0, px);\n      col = cv_screen(col, pg.rgb * pg.a * seepFront * close * shapesOn);\n      col = cv_screen(col, base * exp(-max(sd, 0.0) / (0.35 * r + 0.02)) * 0.08 * close * seep * shapesOn * reachFade);\n      infl += exp(-max(sd, 0.0) / (0.6 * r + 0.05)) * (0.5 + 0.5 * depth) * close * reachFade * shapesOn;\n    }\n  }\n\n  // ------------------------------------------------ 1-3. the glowing field: the same sources, swelling, gliding, becoming lobes\n  float lineT = ARC_line(mA);\n  // every press punches on the beat: the colour swells and brightens at once, easing back over a couple of seconds\n  float punch = hitAge < 6.0 ? (1.0 - exp(-hitAge / 0.06)) * exp(-hitAge / 1.8) : 0.0;\n  // the lobes sit in a deep blue haze rather than on black\n  col = mix(col, vec3(0.025, 0.035, 0.1), lineT * 0.85);\n  // the big moment: the lobes swell, and the swell sets them moving. They drift sideways faster and faster, smearing\n  // into streaks, each height at its own speed, and the streaks split into the fine broken lines for section 3\n  float fillT = cv_fillT(wsec);\n  float smT = smoothstep(18.0, 70.0, wsec);\n  // lines grow out of the smear: first soft uneven bands, sharpening, and only at the end evening out\n  float strT = smoothstep(55.0, 95.0, wsec);                            // how far the lines have formed\n  float thinT = smoothstep(65.0, 115.0, wsec);                          // how fine they are\n  float regT = smoothstep(75.0, 115.0, wsec);                           // how evenly spaced and alike\n  if (fieldOn > 0.001) {\n    float swell = ARC_swell(mA), flow = ARC_flow(mA), glide = ARC_glide(mA);\n    float rows = 30.0;\n    float fy = (p.y + 0.5) * rows;\n    vec2 pq = p;\n    if (smT > 0.001) {\n      // stretched out sideways, and slid along at a speed that varies smoothly with height; the slide builds as it\n      // sets off, which is the acceleration, then keeps drifting. The band repeats, so nothing runs out\n      float v = (cv_noise(vec3(pq.y * 5.0, 3.0, 11.0)) - 0.5) * 0.0011 + 0.00025;\n      float x = pq.x * mix(1.0, 0.25, smT) + v * t * smT;\n      pq.x = mod(x + 0.95, 1.9) - 0.95;\n    }\n    // flowing warp: strongest while the colours run together in track 1, gentle after\n    vec2 q = pq + warp * (0.12 + 0.55 * flow + 0.25 * glide) * (1.0 - 0.7 * lineT);\n    float F = 0.0, wsum = 0.0;\n    vec3 cs = vec3(0.0);\n    for (int j = 0; j < 7; j++) {\n      float fj = float(j);\n      vec3 ca = CV_TAB_src(j, 1).rgb, cb = CV_TAB_src(j, 2).rgb, cc = CV_TAB_src(j, 3).rgb;\n      vec4 S = CV_TAB_src(j, 0);\n      S.zw *= 1.0 + 0.3 * punch;                                        // a Hit swells everything on the beat\n      vec2 d = (q - S.xy) / S.zw;\n      float gs = glide * cv_gesture(t) * (1.0 - lineT);\n      // softer falloff in the cloud, so the sources merge rather than sit as globs; along an echo each step fainter\n      float g = exp(-dot(d, d) * mix(1.6, 0.85, glide * (1.0 - gs) * (1.0 - lineT))) * (1.0 - 0.09 * fj * gs);\n      float calm = glide * (1.0 - gs) * (1.0 - lineT);\n      // heart to glowing edge; in the cloud the hot heart is skipped, so no small bright spots stand out\n      float u = clamp(length(d) * mix(0.8, 0.5, calm) + 0.3 * calm, 0.0, 1.0);\n      vec3 c = mix(mix(ca, cb, smoothstep(0.0, 0.55, u)), cc, smoothstep(0.45, 1.0, u));\n      F += g;\n      // colour follows the nearest source more closely than the light does, so overlaps keep their own hues\n      // instead of averaging to grey, while the light itself stays one soft glow\n      float wc = pow(g, 1.7);\n      cs += c * wc;\n      wsum += wc;\n    }\n    vec3 fc = cs / max(wsum, 1e-7);\n    // while it flows, the hue drifts through the field in soft bands, like colour running (02, 03)\n    if (flow > 0.0) {\n      float drift = (cv_fbm(vec3(q * 1.3, t * 0.003)) - 0.5) * 2.0 * flow;\n      fc = mix(fc, cv_paletteSmooth(idx + 0.5, 0.5 + drift + F * 0.3), 0.35 * flow);\n    }\n    float A = 1.0 - exp(-F * mix(1.4, 2.2, lineT));\n    // feather the edges with grain, so they dissolve rather than end\n    A = clamp(A + (grain - 0.5) * 0.14 * (1.0 - abs(2.0 * A - 1.0)), 0.0, 1.0);\n    vec3 lit = fc * (0.55 + 0.6 * A) + fc * fc * 0.25 * A;             // brighter and a touch hotter in the thick of it\n    // lines forming in the smear: at first irregularly spaced, uneven in width and strength, soft; sharpening and\n    // thinning, and only at the end settling into even rows\n    float stripe = 1.0;\n    if (strT > 0.001) {\n      float rowsN = mix(16.0, 30.0, regT);\n      float u = (p.y + 0.5) * rowsN + (cv_noise(vec3(p.y * 2.5 + 7.0, t * 0.0004, 13.0)) - 0.5) * 2.4 * (1.0 - regT);\n      // each line and its two neighbours, so where one line's glow meets the next there is never an edge\n      float prof = 0.0;\n      for (int nb = -1; nb <= 1; nb++) {\n        float ln = floor(u) + float(nb), f = u - ln - 0.5;\n        float hl = cv_hash(vec3(ln, 87.0, 1.0));\n        float w = mix(0.55, 0.075, thinT) * mix(0.5 + hl, 1.0, regT);\n        float pres = mix(mix(0.3, 1.0, step(0.3, hl)), 1.0, regT);\n        prof = max(prof, exp(-(f * f) / (w * w)) * pres);\n      }\n      stripe = mix(1.0, clamp(prof + (grain - 0.5) * 0.25 * thinT, 0.0, 1.0), strT);\n    }\n    lit *= (1.0 + 1.1 * thinT) * (1.0 + 0.7 * punch);                   // thin lines carry less light: lift them\n    float a = clamp(A * (1.0 + 0.8 * thinT), 0.0, 1.0) * fieldOn * stripe;\n    col = mix(col, lit, a);\n    col += lit * 0.12 * A * fieldOn * (1.0 - strT);                     // a glow beyond the edge\n    infl = max(infl, A * fieldOn);\n  }\n\n  // ------------------------------------------------ washes: every Hit brings one, seeping out of the colour on screen\n  float field = -1.0;                                                   // worked out only if a wash is on screen\n  float pulse = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float age = k == 0 ? hitAge : (k == 1 ? hitPrevAge : wsec);\n    if (k == 2 && (W < 17.0 || wsec < 0.0)) continue;\n    float at = mA - age / 60.0;\n    bool big = k == 2 || abs(at - W) < 0.001;\n    if (big) continue;                                                  // the big moment is the lobes filling the frame\n    if (at > W && age < 1e4) { if (k == 0) pulse = exp(-age / 1.5); continue; }\n    float hold = big ? 30.0 : 22.0, out_ = big ? 60.0 : 70.0;\n    if (age < 0.0 || age > out_) continue;\n    float env = (1.0 - exp(-age / 8.0)) * (1.0 - smoothstep(hold, out_, age));\n    if (env < 0.001) continue;\n    float id = floor((tA - age) * 10.0);\n    vec3 wcol = (big || mod(id, 2.0) < 0.5) ? cv_wash(p, t) : cv_washDeep(p, t);\n    // on the beat the colour rises out of the shapes and keeps rising into the wash: one swell, not a flash then a wash\n    float rise = smoothstep(0.0, 1.0, 1.0 - exp(-age / 1.2)) * (1.0 - smoothstep(hold, out_, age));\n    col = mix(col, max(col, wcol * 0.9), clamp(infl, 0.0, 1.0) * rise * 0.6);\n    col = mix(col, max(col, wcol * 0.45), env * 0.15);\n    if (field < 0.0) field = 0.45 * clamp(infl, 0.0, 1.0) + 0.55 * cv_fbm(vec3(p * 0.6 + warp * 0.6, 20.0 + t * 0.0015));\n    float thr = mix(1.3, -0.45, env);\n    float wm = smoothstep(thr - 0.5, thr + 0.5, field + (grain - 0.5) * 0.06);\n    wm = wm * wm * (3.0 - 2.0 * wm);\n    float tide = exp(-abs(field - thr) / 0.04) * smoothstep(0.02, 0.2, env) * (1.0 - smoothstep(0.85, 1.0, env));\n    col = mix(col, wcol, wm);\n    col = mix(col, wcol * 0.72 + (wcol - vec3(dot(wcol, vec3(0.33)))) * 0.5, tide * 0.5);\n  }\n  col *= 1.0 + 1.2 * pulse * strT;\n\n  // a fine film grain over everything, the texture that keeps the gradients soft\n  col += (grain - 0.5) * 0.012 * (0.3 + dot(col, vec3(0.33))) * (1.0 - s1);   // none on section 1's frame\n\n  col = cv_hueShift(col, tint);\n  col = clamp(col, 0.0, 1.0);\n  col = pow(col, vec3(1.0 / lift));\n  col += (cv_hash(vec3(uv * RENDERSIZE, 1.0)) - 0.5) / 255.0;          // dither\n  gl_FragColor = vec4(col, 1.0);\n}\n","decl":"uniform float timeScale;uniform float speed;uniform float hitAge;uniform float hitPrevAge;","def":{"timeScale":1.0,"speed":1.0,"hitAge":100000.0,"hitPrevAge":100000.0},"len":1140},{"body":"\n\n\n// ---------------------------------------------------------------- fixed for the v2 review: only Speed and Hit are live\n// Speed 1 is the designed speed, 2.0; the slider is a multiple of it, so the operator never needs the number\nconst float SPEED_DESIGN = 2.0;\n#define motion (speed * SPEED_DESIGN)\nconst float glitch = 1.0;\nconst float ringSize = 0.28;\nconst float undulate = 1.0;\nconst float redAmount = 1.0;\nconst float tint = 0.0;\nconst float arcFollow = 1.0;\nconst float lift = 1.0;\n\n// ---------------------------------------------------------------- helpers\nfloat cv_hash(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.yzx + 33.33);\n  return fract((p.x + p.y) * p.z);\n}\nfloat cv_noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(mix(cv_hash(i + vec3(0,0,0)), cv_hash(i + vec3(1,0,0)), f.x),\n        mix(cv_hash(i + vec3(0,1,0)), cv_hash(i + vec3(1,1,0)), f.x), f.y),\n    mix(mix(cv_hash(i + vec3(0,0,1)), cv_hash(i + vec3(1,0,1)), f.x),\n        mix(cv_hash(i + vec3(0,1,1)), cv_hash(i + vec3(1,1,1)), f.x), f.y), f.z);\n}\nfloat cv_fbm(vec3 p) {\n  return 0.5 * cv_noise(p) + 0.3 * cv_noise(p * 2.03 + 7.1) + 0.2 * cv_noise(p * 4.11 + 13.7);\n}\n// 0 outside [a,d], 1 between b and c\nfloat cv_bump(float x, float a, float b, float c, float d) {\n  return smoothstep(a, b, x) * (1.0 - smoothstep(c, d, x));\n}\n// rotate hue around the grey axis; keeps black black and white white\nvec3 cv_hueShift(vec3 c, float h) {\n  vec3 k = vec3(0.57735);\n  float a = h * 6.2832;\n  return c * cos(a) + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - cos(a));\n}\nvec3 cv_screen(vec3 a, vec3 b) {\n  return vec3(1.0) - (vec3(1.0) - a) * (vec3(1.0) - b);\n}\n// the integral of smoothstep(a, b, s) from a to x: a speed that eases up from a to b, as a distance travelled\nfloat cv_intSS(float x, float a, float b) {\n  float u = clamp((x - a) / (b - a), 0.0, 1.0);\n  return (b - a) * (u * u * u - 0.5 * u * u * u * u) + max(x - b, 0.0);\n}\nvec2 cv_rot(vec2 p, float a) {\n  float c = cos(a), s = sin(a);\n  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\n// ---------------------------------------------------------------- arc\n// Minutes. Sliders multiply on top of these. P is the colour moment, C its end (P + hold), e minutes since C.\n// Everything moves fast; the slow part is only which state is on screen.\nfloat ARC_s2(float m)      { return 1.0 - step(0.7, m); }                   // A. section 2's end: its lines, until they are dash rows\nfloat ARC_mono(float m)    { return smoothstep(0.05, 0.3, m); }             //    their colour drains to black, white and red, fast\nfloat ARC_narrow(float m)  { return smoothstep(0.2, 0.45, m); }             //    each line sharpens to a row, lit evenly along it\nfloat ARC_break(float m)   { return smoothstep(0.3, 0.7, m); }              //    gaps open and the pieces shorten to dashes, running\nfloat ARC_across(float m)  { return smoothstep(0.45, 1.1, m); }             // B. more rows of the same lines appear among them\nfloat ARC_dashes(float m)  { return step(0.42, m) * (1.0 - smoothstep(1.8, 2.2, m)); } // frantic lines, covered by the grey\nfloat ARC_thickBars(float m) { return smoothstep(0.95, 1.5, m); }           //    thicker grey bars streaming in\nfloat ARC_greyGrow(float m) { return smoothstep(1.35, 2.3, m); }           //    each grey bar longer and thicker than the last, to solid grey\nfloat ARC_opCircle(float m) { return cv_bump(m, 0.7, 0.85, 1.2, 1.4); }     //    a circle shows in the lines: they shift inside it (03, 04)\nfloat ARC_cut(float m)     { return smoothstep(2.2, 2.3, m); }               //    the grey cuts into offset blocks (24)\nfloat ARC_align(float m)   { return smoothstep(2.3, 2.38, m); }              //    the rows slide into line: black and grey stripes\nfloat ARC_split(float m)   { return smoothstep(2.38, 2.55, m); }             //    the grey stripes split into columns\nfloat ARC_grow(float m)    { return smoothstep(2.42, 2.8, m); }              //    columns grow up out of the black stripes\nfloat ARC_fall(float m)    { return smoothstep(2.45, 3.05, m); }              //    which drop into a sort chart, white and red\nfloat ARC_sparse(float m)  { return smoothstep(2.75, 3.2, m); }             //    the chart thins, shuffles fast, dips in the middle\nfloat ARC_toWave(float m)  { return smoothstep(3.2, 4.0, m); }              //    and gathers onto the centre line as a waveform\nfloat ARC_cols(float m)    { return step(2.2, m) * (1.0 - smoothstep(3.7, 4.2, m)); }\nfloat ARC_ringIn(float m)  { return smoothstep(3.6, 4.1, m); }              // C. thin ring, its echo, and a spark\nfloat ARC_thicken(float m) { return smoothstep(4.2, 5.0, m); }              //    the ring thickens and warps\nfloat ARC_wave(float m)    { return smoothstep(3.6, 4.1, m); }              //    the waveform proper\n// C. the ring's echo spreads into thin arcs (15), all monochrome. Red and glitch creep into the ring, it tears at\n// T_TEAR, the arcs run out past the edges, the ring goes quickly, and the waveform tilts into the streaks\nconst float T_TEAR = 7.2;\nfloat ARC_arcs(float m)    { return smoothstep(5.2, 5.8, m); }\nfloat ARC_arcOut(float m)  { return smoothstep(T_TEAR + 0.3, T_TEAR + 1.2, m); }\nfloat ARC_build(float m)   { return smoothstep(T_TEAR - 0.7, T_TEAR, m); }\nfloat ARC_tornK(float m)   { return smoothstep(T_TEAR + 0.2, T_TEAR + 1.0, m); }\nfloat ARC_ringOut(float m) { return 1.0 - smoothstep(T_TEAR + 0.9, T_TEAR + 1.25, m); }\nfloat ARC_jog(float m)     { return smoothstep(T_TEAR + 1.0, T_TEAR + 1.35, m); }\nfloat ARC_tilt(float m)    { return smoothstep(T_TEAR + 1.3, T_TEAR + 1.9, m); }\n// G. white streaks from 9:00. The vanishing point sinks away so they straighten into columns, which fill with stepped\n// grey-to-white gradients (23); the gradients re-form round a chevron (25) and from 12:00 the colours arrive one at a\n// time as accents. The big moment W (first Hit 13:00-13:45, or 13:45) is the riot, the edges splitting (06). Then\n// back to accents, the columns tip over into scan lines, a circle shows in them by the lines' offsets (03, 04), grows,\n// and the lines go all red\nfloat ARC_streaks(float m) { return 0.5 * clamp((m - (T_TEAR + 1.8)) / 0.7, 0.0, 1.0); }\nfloat ARC_recede(float m)  { return smoothstep(10.25, 10.75, m); }\nfloat ARC_colK(float m)    { return smoothstep(10.4, 10.72, m); }        //    every column in by 10:43, then the red at 10:45\nfloat ARC_chev(float m)    { return smoothstep(11.75, 12.25, m); }\nfloat ARC_glitch(float m) {\n  float e = m - T_TEAR;\n  return 0.35 * cv_bump(m, 0.3, 0.42, 0.6, 0.8)\n       + 0.45 * cv_bump(m, 0.6, 0.8, 0.9, 1.1)                         // none from 1:06: the grey and columns stay smooth\n       + (0.3 * smoothstep(-0.8, -0.2, e) + ARC_build(m)) * (1.0 - step(0.0, e))\n       + step(0.0, e) * (0.3 + (1.0 - smoothstep(0.0, 0.6, e))) * (1.0 - smoothstep(T_TEAR + 2.0, T_TEAR + 2.4, m));\n}\n// the lines' clock, in seconds: slow as section 2's lines break up (from 0:20), full speed by 1:06. Those lines\n// and every new line run on it, so they always move at the same speeds\nfloat cv_runT(float t) {\n  float a = 20.0, b = 66.0, r0 = 0.2;\n  float u = clamp(t, a, b) - a;\n  return r0 * u + (1.0 - r0) * u * u / (2.0 * (b - a)) + max(t - b, 0.0);\n}\n\n// ---------------------------------------------------------------- glitch\n// horizontal bands shoved sideways; the pattern holds for under half a second and snaps to the next\nfloat cv_gOff(float y, float k, float amt) {\n  float rows = 14.0 + 40.0 * cv_hash(vec3(k, 3.0, 1.0));\n  float row = floor((y + 0.5) * rows);\n  float h = cv_hash(vec3(row, k, 7.0));\n  float on = step(1.0 - 0.3 * min(amt, 1.5), h);\n  return on * (cv_hash(vec3(row, k, 8.0)) - 0.5) * 0.25 * amt;\n}\nvec2 cv_glitchShift(vec2 p, float t, float amt) {\n  if (amt < 0.001) return p;\n  float per = 0.45;\n  float k = floor(t / per);\n  float f = smoothstep(0.0, 0.12, fract(t / per));\n  return p + vec2(mix(cv_gOff(p.y, k - 1.0, amt), cv_gOff(p.y, k, amt), f), 0.0);\n}\n\n// ---------------------------------------------------------------- frame\n// The clock and the arc position, in one place so every part of the picture agrees on where the section is.\nfloat cv_t()  { return TIME * timeScale; }\nfloat cv_mA() { return mix(6.0, min(cv_t() / 60.0, 17.5), arcFollow); }\nfloat cv_px() { return 1.0 / RENDERSIZE.y; }\n\n// ---------------------------------------------------------------- B. one dash row\n// One row of the tearing lines: its colour, and how much of it covers this pixel. Each row has its own speed and\n// glides to a new offset every second or two. lenK takes each piece from nearly the whole repeat to the row's own\n// length, grow scales it (rows switching on grow in from nothing). Returns the colour and the dash along x; the row's\n// height is cv_rowBand. Section 2's lines become rows 5k+2, drawn by exactly this in the opening and in the build.\nfloat cv_rowBand(float fy2, float row) { return cv_bump(fy2 - row, 0.15, 0.25, 0.75, 0.85); }\nvec4 cv_dashRow(float row, vec2 p, float t, float runT, float red, float lenK, float grow) {\n  float h = cv_hash(vec3(row, 21.0, 3.0));\n  float h2 = cv_hash(vec3(row, 22.0, 4.0));\n  float speed = 0.3 + 2.4 * h2 * h2;\n  float per = 0.9 + 1.4 * h2;\n  float ph = t / per + h * 5.0;\n  float k = floor(ph);\n  float jump = mix((cv_hash(vec3(row, k - 1.0, 6.0)) - 0.5) * 0.4 * step(0.5, cv_hash(vec3(row, k - 1.0, 9.0))),\n                   (cv_hash(vec3(row, k, 6.0)) - 0.5) * 0.4 * step(0.5, cv_hash(vec3(row, k, 9.0))),\n                   smoothstep(0.0, 0.3, fract(ph)));\n  float fx = fract((p.x - runT * speed - jump) * (1.5 + 2.0 * h) + h * 7.0);\n  float len = mix(0.94, 0.15 + 0.22 * cv_hash(vec3(row, 23.0, 5.0)), lenK) * grow;\n  float dash = cv_bump(fx, 0.96 - len - 0.02, 0.96 - len, 0.96, 0.98);\n  vec3 dc = h > 0.8 ? mix(vec3(0.5), vec3(0.92, 0.08, 0.1), red) : (h2 > 0.93 ? vec3(0.8) : vec3(0.3 + 0.12 * h2));\n  return vec4(dc, dash);\n}\n\n// ---------------------------------------------------------------- A. section 2's end, on section 2's clock\n// Section 2 (v26) as it holds from 19:00: seven glowing lobes smeared sideways, seen through thirty fine even lines on a\n// deep blue haze, drawn with section 2's own code with its arc settled. Its real time is this section's plus 1140 s and\n// its motion runs at its Speed of 4, so this section's 0:00 is section 2's 19:00 exactly.\n// Then: mono drains the colour to white, grey and red and the haze to black; narrow sharpens each line to a dash row's\n// height and evens out the lobes' light along it; brk opens gaps in it and shortens the pieces to that row's dashes,\n// taking on its colour, running on the lines' clock. Line k is dash row 5k+2: the same centre, the same row from then on.\nconst float S2_SPEED = 4.0;\nvec3 cv_s2pal(float h) {\n  vec3 a = vec3(0.45, 0.33, 0.95), b = vec3(0.20, 0.48, 1.00), c = vec3(0.95, 0.55, 0.22);\n  return h < 0.4 ? a : (h < 0.72 ? b : c);\n}\nvec3 cv_s2end(vec2 p, vec2 uv, float t3, float tm, float mono, float narrow, float brk, float runT, float red, float px) {\n  float tA = t3 + 1140.0;\n  float t = tA * S2_SPEED;\n  vec3 col = vec3(0.025, 0.035, 0.1) * 0.85 * (1.0 - mono);\n  vec2 warp = vec2(cv_fbm(vec3(p * 1.7, t * 0.004)), cv_fbm(vec3(p * 1.7 + 5.2, t * 0.004))) - 0.5;\n  float grain = cv_hash(vec3(uv * RENDERSIZE, floor(tA * 12.0)));\n  // the smear: stretched sideways and sliding at a speed that varies with height\n  vec2 pq = p;\n  float v = (cv_noise(vec3(pq.y * 5.0, 3.0, 11.0)) - 0.5) * 0.0011 + 0.00025;\n  pq.x = mod(pq.x * 0.25 + v * t + 0.95, 1.9) - 0.95;\n  vec2 q = pq + warp * 0.12 * 0.3;\n  float F = 0.0, wsum = 0.0;\n  vec3 cs = vec3(0.0);\n  for (int j = 0; j < 7; j++) {\n    float fj = float(j);\n    float h3 = cv_hash(vec3(fj, 33.0, 3.0));\n    float e = cv_noise(vec3(fj * 0.6, t * 0.001, 2.0));\n    vec3 ca = mix(cv_s2pal(fract(h3 + fj * 0.37)), mix(vec3(1.0, 0.62, 0.25), vec3(1.0, 0.42, 0.62), e), 0.85);\n    vec3 cb = mix(cv_s2pal(fract(h3 + fj * 0.37 + 0.34)), mix(vec3(1.0, 0.4, 0.55), vec3(0.75, 0.38, 0.95), e), 0.85);\n    vec3 cc = mix(cv_s2pal(fract(h3 + fj * 0.37 + 0.68)), vec3(0.3, 0.42, 1.0), 0.85);\n    float wv = cv_noise(vec3(fj * 0.33 - t * 0.0016, t * 0.0021, 5.0));\n    vec2 pos = vec2((fj - 3.0) * 0.22 + 0.03 * sin(t * 0.002 + fj * 1.3), 0.0);\n    vec2 rr = vec2(0.12 + 0.06 * cv_noise(vec3(fj * 0.5, t * 0.0013, 9.0)), 0.05 + 0.4 * pow(wv, 1.6));\n    vec2 d = (q - pos) / rr;\n    float g = exp(-dot(d, d) * 1.6);\n    float u = clamp(length(d) * 0.8, 0.0, 1.0);\n    vec3 c = mix(mix(ca, cb, smoothstep(0.0, 0.55, u)), cc, smoothstep(0.45, 1.0, u));\n    F += g;\n    float wc = pow(g, 1.7);\n    cs += c * wc;\n    wsum += wc;\n  }\n  vec3 fc = cs / max(wsum, 1e-7);\n  float A = 1.0 - exp(-F * 2.2);\n  A = clamp(A + (grain - 0.5) * 0.14 * (1.0 - abs(2.0 * A - 1.0)), 0.0, 1.0);\n  vec3 lit = (fc * (0.55 + 0.6 * A) + fc * fc * 0.25 * A) * 2.1;\n  float Ax = clamp(A * 1.8, 0.0, 1.0);\n  // drained: most lines go white and grey, about one in five red, the red rows being the dash rows that are red\n  float lum = dot(lit, vec3(0.3, 0.59, 0.11));\n  vec3 redC = mix(vec3(0.7), vec3(0.92, 0.1, 0.12), red);\n  // the thirty lines, each with its two neighbours so their glows never meet at an edge; the grain on the nearest only\n  float u30 = (p.y + 0.5) * 30.0;\n  float fy2 = (p.y + 0.5) * 150.0;\n  float lenK = smoothstep(0.0, 1.0, brk);\n  float gapK = smoothstep(0.0, 0.3, brk);\n  for (int nb = -1; nb <= 1; nb++) {\n    float ln = floor(u30) + float(nb), f = u30 - ln - 0.5;\n    float row = ln * 5.0 + 2.0;\n    vec4 dr = cv_dashRow(row, p, tm, runT, red, lenK, 1.0);\n    float soft = clamp(exp(-(f * f) / (0.075 * 0.075)) + (nb == 0 ? (grain - 0.5) * 0.25 : 0.0), 0.0, 1.0);\n    float prof = mix(soft, cv_rowBand(fy2, row), narrow);\n    float along = mix(Ax, 1.0, narrow) * mix(1.0, dr.a, gapK);\n    float isRed = step(0.8, cv_hash(vec3(row, 21.0, 3.0)));\n    vec3 lc = mix(lit, mix(vec3(min(lum * 1.5, 1.0)), redC * (0.35 + lum), isRed), mono);\n    lc = mix(lc, dr.rgb, lenK);\n    col = mix(col, lc, clamp(prof * along, 0.0, 1.0));\n  }\n  col += (grain - 0.5) * 0.012 * (0.3 + dot(col, vec3(0.33))) * (1.0 - mono);   // section 2's film grain, going\n  return col;\n}\n\n// ---------------------------------------------------------------- B. lines\n// thin red and grey lines tearing sideways on fixed rows, moving the way the sort chart does; some rows fade in and\n// out, and rows that switch on grow in from nothing. across is how many rows are running. Rows 5k+2 are section 2's\n// thirty lines: always there, drawn by the opening until it hands them over (own = 1)\nvec3 cv_dashes(vec2 p, float t, float runT, float red, float across, float own, float op, float R, float px) {\n  // the op-art circle (03, 04): inside it every row runs, its pieces grow long, and the rows sit half a row off the\n  // ones outside, so the circle is only where the lines break. op glides it in and out\n  float circ = op * (1.0 - smoothstep(R - 1.5 * px, R + 1.5 * px, length(p)));\n  vec2 q = p + vec2(0.0, circ * 0.5 / 150.0);\n  float fy2 = (q.y + 0.5) * 150.0;\n  float row = floor(fy2);\n  float h = cv_hash(vec3(row, 21.0, 3.0));\n  float lenK = 1.0 - circ;\n  if (abs(mod(row, 5.0) - 2.0) < 0.5) {\n    if (own < 0.5) return vec3(0.0);\n    vec4 dr = cv_dashRow(row, q, t, runT, red, lenK, 1.0);\n    return mix(dr.rgb, vec3(0.9), circ) * dr.a * cv_rowBand(fy2, row);\n  }\n  float appear = max(clamp((across - cv_hash(vec3(row, 24.0, 6.0))) * 6.0, 0.0, 1.0), circ);\n  if (appear <= 0.0) return vec3(0.0);\n  if (h < 0.4 && circ < 0.001) return vec3(0.0);\n  float pres = mix(1.0, smoothstep(0.3, 0.7, cv_noise(vec3(row * 0.37, t * 0.8, 11.0))), 1.0 - step(0.55, h));\n  vec4 dr = cv_dashRow(row, q, t, runT, red, lenK, appear);\n  return mix(dr.rgb, vec3(0.9), circ) * dr.a * cv_rowBand(fy2, row) * mix(pres, 1.0, circ) * mix(step(0.4, h), 1.0, circ);\n}\n\nvec3 cv_greyGround(vec2 p) {\n  return vec3(0.7, 0.77, 0.78) * (0.7 + 0.3 * exp(-length(p - vec2(0.25, 0.0)) / 0.5));\n}\n\n// the grey build: thick grey bars racing in from the right. No new bars arrive after the first; instead each bar that\n// passes is longer and thicker than the one before it (its size is set by when it came in), spilling over the rows\n// between, until they close into solid grey. rgb, coverage\nvec4 cv_greyBuild(vec2 p, float t, float thickB, float px, float aspect) {\n  float rows = 44.0;\n  float fy = (p.y + 0.5) * rows;\n  float row0 = floor(fy);\n  float W = aspect * 0.5 + 0.2;\n  float cov = 0.0;\n  for (int dr = -2; dr <= 2; dr++) {\n    float row = row0 + float(dr);\n    float hr = cv_hash(vec3(row, 11.0, 1.0));\n    if (hr < 1.0 - 0.75 * thickB) continue;\n    float h2 = cv_hash(vec3(row, 13.0, 2.0));\n    float h3 = cv_hash(vec3(row, 14.0, 3.0));\n    float freq = 0.5 + 0.6 * h2;\n    float v = 0.9 + 2.2 * h3;\n    float o = hr * 5.0;\n    float ph = (p.x + t * v) * freq + o;\n    float idx = floor(ph);\n    // when this bar's front crossed the right edge; later bars are grown more\n    float tE = ((idx - o) / freq - W) / v;\n    float g = ARC_greyGrow(tE / motion / 60.0);                     // tE is motion time; the growth runs on real time\n    float duty = mix(0.55, 1.02, g * sqrt(g));\n    float pxf = px * freq;\n    float seg = duty >= 1.0 ? 1.0 : smoothstep(0.0, pxf, fract(ph)) * (1.0 - smoothstep(duty, duty + pxf, fract(ph)));\n    float th = mix(mix(0.3, 0.7, h2), 5.2, g * g * g);                 // in rows: up to two rows either side, most of it late\n    float yRel = abs(fy - (row + 0.5));\n    float pr = px * rows;\n    float band = 1.0 - smoothstep(th * 0.5 - pr, th * 0.5 + pr, yRel);\n    cov = max(cov, seg * band);\n  }\n  vec3 c = cv_greyGround(p);                                          // one grey throughout, so the bars close into it without faint seams\n  return vec4(c, cov);\n}\n\n// vertical columns: the solid grey splits into columns, the columns drop into a sort chart (white, some red) that\n// reshuffles; then the chart thins out, shuffles fast and dips in the middle, and gathers onto the centre line with\n// the ring waveform's own spikes\nvec3 cv_columns(vec2 p, float t, float cut, float align, float split, float grow, float fall, float sparse, float toWave,\n                float R, float red, float px, float aspect) {\n  float pitch = aspect / 110.0;\n  // the grey cut into offset blocks, black and grey (24): cells five columns wide, alternate rows offset half a cell,\n  // black growing across every other cell; then the rows slide into line, leaving black and grey stripes\n  float cw = 5.0 * pitch;\n  float cellY = floor((p.y + 0.5) / cw);\n  float uc = p.x / cw + mod(cellY, 2.0) * 0.5 * (1.0 - align);\n  float blackCell = step(0.5, mod(floor(uc), 2.0)) * (1.0 - smoothstep(cut - px / cw, cut + px / cw, fract(uc)));\n  if (align < 0.999) return cv_greyGround(p) * (1.0 - blackCell);\n  float isOdd = step(0.5, mod(floor(p.x / cw), 2.0));                  // the black stripes: their columns grow from nothing\n  float cx = floor(p.x / pitch);\n  float fx = fract(p.x / pitch);\n  float h = cv_hash(vec3(cx, 31.0, 1.0));\n  float present = mix(mix(1.0, step(0.3, cv_hash(vec3(cx, 34.0, 2.0))), sparse), 1.0, toWave);\n  if (present < 0.001) return vec3(0.0);\n  float per = mix(3.7, 0.55, sparse);\n  float ph = t / per + cv_hash(vec3(cx, 36.0, 4.0)) * 3.0;\n  float k = floor(ph);\n  float hc = mix(cv_hash(vec3(cx, k - 1.0, 33.0)), cv_hash(vec3(cx, k, 33.0)), smoothstep(0.0, 0.25, fract(ph)));\n  float xc = (cx + 0.5) * pitch;\n  float dip = mix(1.0, 0.3 + 0.7 * smoothstep(0.1, 0.7, abs(xc)), sparse);\n  float Hf = (0.08 + 0.85 * mix(hc, hc * hc, sparse)) * dip;\n  float H = mix(mix(1.05, Hf, fall), Hf * grow, isOdd);\n  // the waveform at this column, as the ring scene draws it\n  float wcx = floor(xc / (3.0 * px));\n  float n = cv_noise(vec3(wcx * 0.21, t * 1.2, 1.0));\n  float n2 = cv_noise(vec3(wcx * 0.9, t * 2.0, 4.0));\n  float spike = n * n * n * n * (0.4 + 0.6 * n2) * 4.0;\n  float env = smoothstep(R, R + 0.18, abs(xc)) * (1.0 - smoothstep(aspect * 0.5 - 0.05, aspect * 0.5, abs(xc)));\n  float amp = (0.003 + 0.13 * spike) * env + px;\n  float lo = mix(-0.55, -amp, toWave);\n  float hi = mix(-0.55 + H, amp, toWave);\n  float inY = smoothstep(lo - px, lo + px, p.y) * (1.0 - smoothstep(hi - px, hi + px, p.y));\n  float w = mix(mix(0.62, 0.42, sparse), 0.3, toWave);\n  float pxf = px / pitch;\n  float inX = mix(1.0, 1.0 - smoothstep(w - pxf, w + pxf, fx), max(split, isOdd));\n  vec3 bar = mix(vec3(0.88), mix(vec3(0.88), vec3(0.9, 0.12, 0.14), red), step(0.86, h));\n  vec3 c = mix(cv_greyGround(p), bar, fall);\n  return c * inX * inY * present;\n}\n\n// ---------------------------------------------------------------- C and F. the ring\n// where the ring sits: a small restless drift. The echo follows the same path half a second late and overshoots it,\n// so the two rings are visibly one ring and its lag\nvec2 cv_ringDrift(float t) {\n  return 0.018 * vec2(sin(t * 1.1) + 0.5 * sin(t * 2.7 + 1.0), cos(t * 0.9) + 0.5 * cos(t * 2.3 + 2.0));\n}\n\n// the ring: undulating inner edge, an echo, torn arcs, a waveform through it, a spark at its heart\nvec3 cv_ringScene(vec2 p, float t, float R, float thick, float und, float ghost, float torn,\n                  float waveA, float spark, float red, float gA, float px, float aspect,\n                  float arcs, float arcOut) {\n  vec3 c = vec3(0.0);\n\n  // waveform, behind the ring: thin vertical strokes, spiky, reaching to the frame edges\n  if (waveA > 0.001) {\n    float colW = 3.0 * px;\n    float cx = floor(p.x / colW);\n    float n = cv_noise(vec3(cx * 0.21, t * 1.2, 1.0));\n    float n2 = cv_noise(vec3(cx * 0.9, t * 2.0, 4.0));\n    float spike = n * n * n * n * (0.4 + 0.6 * n2) * 4.0;\n    float env = smoothstep(R, R + thick * 0.5 + 0.12, abs(p.x)) * (1.0 - smoothstep(aspect * 0.5 - 0.05, aspect * 0.5, abs(p.x)));\n    float amp = (0.003 + 0.13 * spike) * env * waveA + px * 0.6;\n    float stroke = 1.0 - smoothstep(0.5, 0.75, fract(p.x / colW));\n    c = max(c, vec3(0.9) * stroke * (1.0 - smoothstep(amp - px, amp + px, abs(p.y))) * waveA * step(R, length(p)));\n  }\n\n  vec2 drift = cv_ringDrift(t);\n  vec2 pr = p - drift;\n  float r = length(pr);\n  float a = atan(pr.y, pr.x);\n  vec2 dir = pr / max(r, 0.0001);\n\n  // the echo: grey, trailing the ring's drift and overshooting it, breathing in size, with gaps as it tears\n  if (ghost > 0.001) {\n    vec2 q = p - cv_ringDrift(t - 0.5) * (2.4 + 1.5 * torn);\n    float rq = length(q);\n    vec2 dq = q / max(rq, 0.0001);\n    float gap = mix(1.0, smoothstep(0.4, 0.5, cv_noise(vec3(dq * 1.3 + 2.0, t * 0.3))), torn);\n    float Rg = R * (1.06 + 0.035 * sin(t * 1.4));\n    float cg = smoothstep(Rg - thick * 0.6 - px, Rg - thick * 0.6 + px, rq) * (1.0 - smoothstep(Rg + thick * 0.55 - px, Rg + thick * 0.55 + px, rq));\n    c = max(c, vec3(0.5) * cg * gap * ghost);\n  }\n\n  // the echo repeating outward as thin arcs above and below (15), white on black. arcs is how far out they have\n  // reached; arcOut sends the last of them out past the frame with no new ones behind\n  if (arcs > 0.001) {\n    float front = R * 1.08 + arcs * 1.5;\n    float back = R * 1.08 + arcOut * 1.9;\n    float side = smoothstep(0.3, 0.75, abs(dir.y));\n    float acc = 0.0;\n    for (int k = 0; k < 6; k++) {\n      float ph = fract(t * 0.05 + float(k) / 6.0);\n      float rk = R * 1.08 + ph * 1.6;\n      float gate = smoothstep(back, back + 0.04, rk) * (1.0 - smoothstep(front - 0.04, front, rk));\n      if (gate < 0.001) continue;\n      acc = max(acc, (1.0 - smoothstep(0.0035 - px, 0.0035 + px, abs(r - rk))) * gate * (1.0 - 0.6 * ph));\n    }\n    c = max(c, vec3(0.9) * acc * side);\n  }\n\n  // torn arcs thrown outward, flickering round\n  if (torn > 0.001) {\n    float Rt = R * 1.18 + 0.012 * sin(t * 1.3);\n    float gapT = smoothstep(0.55, 0.62, cv_noise(vec3(cv_rot(dir, t * 0.5) * 1.6 + 7.0, t * 0.3)));\n    float ct = smoothstep(Rt - 0.018 - px, Rt - 0.018 + px, r) * (1.0 - smoothstep(Rt + 0.018 - px, Rt + 0.018 + px, r));\n    c = max(c, vec3(0.92) * ct * gapT * torn);\n  }\n\n  // tears: angular chunks of the ring pushed in or out, a new set every half second\n  float tk = floor(t / 0.55);\n  float seg = floor((a + 3.1416) / 6.2832 * 14.0);\n  float tearOn = step(1.0 - 0.35 * min(gA, 1.5), cv_hash(vec3(seg, tk, 5.0)));\n  float rr = r + tearOn * (cv_hash(vec3(seg, tk, 6.0)) - 0.5) * 0.06 * min(gA, 1.5);\n\n  // the ring itself: lobed inner edge that rolls round and churns, gentler outer edge; a thin ring stays clean\n  float lobeOn = smoothstep(0.02, 0.08, thick);\n  vec2 dRoll = cv_rot(dir, t * 0.35 * (0.5 + und));\n  float li = (cv_noise(vec3(dRoll * 2.3 + 3.0, t * 0.5 * (0.5 + und))) - 0.5) * 2.0 * und * 0.1 * lobeOn;\n  float lo = (cv_noise(vec3(dRoll * 1.7 + 9.0, t * 0.4)) - 0.5) * 2.0 * und * 0.04 * lobeOn;\n  float outer = R + thick * 0.5 + lo;\n  float inner = min(R - thick * 0.5 + li, outer - 1.5 * px);\n  float cov = smoothstep(inner - px, inner + px, rr) * (1.0 - smoothstep(outer - px, outer + px, rr));\n  vec3 ringCol = mix(mix(vec3(0.95), vec3(0.62, 0.68, 0.7), 1.0 - lobeOn), vec3(0.9, 0.1, 0.1), red * 0.7);\n  c = mix(c, ringCol, cov);\n\n  // spark: a fountain of dots at the heart, quick and swaying\n  if (spark > 0.001) {\n    float sway = 0.5 * sin(t * 0.8);\n    for (int i = 0; i < 28; i++) {\n      float fi = float(i);\n      float h = cv_hash(vec3(fi, 51.0, 1.0));\n      float h2 = cv_hash(vec3(fi, 52.0, 2.0));\n      float age = fract(t * 0.45 + h);\n      vec2 pos = vec2((h2 - 0.5) * 0.07 * (0.3 + age) + 0.01 * sin(t * 2.5 + fi * 1.7), 0.045 - age * 0.17 * (0.6 + 0.4 * h2));\n      pos = cv_rot(pos, sway * age);\n      float s = mix(4.0, 1.0, age) * px;\n      float dot1 = 1.0 - smoothstep(s - px, s + px, length(pr - pos));\n      c = max(c, vec3(0.9) * dot1 * spark * (1.0 - age * 0.7));\n    }\n  }\n  return c;\n}\n\n// ---------------------------------------------------------------- G. the waveform into the streaks\n// the ring waveform's strokes, jogged and tilted: at jog = tilt = 0 it draws the waveform as the ring scene does. jog\n// shoves chunks of strokes sideways, gliding between offsets like the earlier lines; tilt swings each stroke onto its\n// ray from the streaks' vanishing point, stretches it to streak length, breaks it into dashes and thins it out\nvec3 cv_waveTilt(vec2 p, float t, float jog, float tilt, float R, float px, float aspect) {\n  vec2 vp = vec2(0.12 * sin(t * 0.11), 1.35 + 0.08 * sin(t * 0.07));\n  float x0 = vp.x + (p.x - vp.x) * vp.y / max(vp.y - p.y, 0.05);      // where this point's ray crosses the centre line\n  float xs = mix(p.x, x0, tilt);\n  float colW = 3.0 * px;\n  float chunk = floor(xs / (colW * 12.0));\n  float ph = t / 0.9 + cv_hash(vec3(chunk, 101.0, 1.0)) * 3.0;\n  float k = floor(ph);\n  float shove = mix(cv_hash(vec3(chunk, k - 1.0, 102.0)), cv_hash(vec3(chunk, k, 102.0)), smoothstep(0.0, 0.3, fract(ph))) - 0.5;\n  xs += shove * 0.06 * jog;\n  float cx = floor(xs / colW);\n  if (cv_hash(vec3(cx, 103.0, 1.0)) > mix(1.0, 0.3, tilt)) return vec3(0.0);\n  float n = cv_noise(vec3(cx * 0.21, t * 1.2, 1.0));\n  float n2 = cv_noise(vec3(cx * 0.9, t * 2.0, 4.0));\n  float spike = n * n * n * n * (0.4 + 0.6 * n2) * 4.0;\n  float env = smoothstep(R, R + 0.18, abs(p.x)) * (1.0 - smoothstep(aspect * 0.5 - 0.05, aspect * 0.5, abs(p.x)));\n  float amp = mix((0.003 + 0.13 * spike) * env + px * 0.6, 1.2, tilt * tilt);\n  float stroke = 1.0 - smoothstep(0.5, 0.75, fract(xs / colW));\n  float inY = 1.0 - smoothstep(amp - px, amp + px, abs(p.y));\n  float dash = mix(1.0, step(fract(length(p - vp) * 1.6 - t * 1.0 + cv_hash(vec3(cx, 104.0, 1.0)) * 7.0), 0.55), smoothstep(0.3, 1.0, tilt));\n  return mix(vec3(0.9), vec3(0.8, 0.85, 0.85), tilt) * stroke * inY * dash;\n}\n\n// ---------------------------------------------------------------- G. streaks to columns, and the colour\n// the streak field: rec sinks the vanishing point away so the streaks straighten to vertical and widen into columns;\n// colK makes every column present, solid and full width. Returns coverage; bin and xc (the column's centre) out\nfloat cv_fieldMask(vec2 p, float t, float g, float px, float rec, float colK, float shift, float inside, float keep,\n                  out float bin, out float xc) {\n  vec2 vp = vec2(0.12 * sin(t * 0.11) * (1.0 - rec), mix(1.35 + 0.08 * sin(t * 0.07), 7.0, rec));\n  vec2 d = p - vp;\n  float r = length(d);\n  float N = 260.0;\n  float fa = atan(d.x, -d.y) / 3.1416 * N + shift;                     // shift: half a line inside the circle (03, 04)\n  bin = floor(fa);\n  xc = vp.x + (vp.y - p.y) * tan((bin + 0.5) / N * 3.1416);\n  float h = cv_hash(vec3(bin, 91.0, 1.0));\n  float h2 = cv_hash(vec3(bin, 92.0, 2.0));\n  float on = smoothstep(h - 0.03, h, mix(mix(0.08, 0.7, smoothstep(0.0, 0.35, g)), 1.05, max(colK, inside)));\n  float wdt = mix(0.25 + 0.6 * h2, 0.92, colK);\n  float pxa = px / max(r * 3.1416 / N, 0.0005);\n  float across = 1.0 - smoothstep(wdt * 0.5 - pxa, wdt * 0.5 + pxa, abs(fract(fa) - 0.5));\n  float ph = fract(r * (1.2 + 1.5 * h) - t * (0.6 + 1.2 * h2) + h * 9.0);\n  float along = smoothstep(0.0, 0.02, ph) * (1.0 - smoothstep(0.35 + 0.5 * h, 0.37 + 0.5 * h, ph));\n  // keep: the share of lines left; the rest drop out one by one, each fading over a moment\n  float stay = smoothstep(0.0, 0.2, keep * 1.2 - cv_hash(vec3(bin, 93.0, 3.0)));\n  return on * across * mix(along, 1.0, max(colK, inside)) * stay;      // inside the circle every line runs unbroken\n}\n// the colours: the section's blue first, then magenta, orange, cyan, yellow, lime, one band of columns each\nvec3 cv_col(float k) {\n  if (k < 0.5) return vec3(0.25, 0.55, 1.0);\n  if (k < 1.5) return vec3(1.0, 0.25, 0.7);\n  if (k < 2.5) return vec3(1.0, 0.5, 0.08);\n  if (k < 3.5) return vec3(0.1, 0.85, 0.85);\n  if (k < 4.5) return vec3(1.0, 0.85, 0.15);\n  return vec3(0.55, 1.0, 0.25);\n}\n// a stepped gradient, dark to the colour to near white (23, 25)\nvec3 cv_ramp(float u, vec3 c) {\n  vec3 dark = vec3(0.06, 0.0, 0.04), deep = c * 0.3, top = vec3(0.97, 0.95, 0.88);\n  return u < 0.15 ? mix(dark, deep, u / 0.15) : (u < 0.5 ? mix(deep, c, (u - 0.15) / 0.35) : mix(c, top, (u - 0.5) / 0.5));\n}\n// the column's colour at this height: 23's stepped cells offset in a wave, re-forming round a chevron (25) that keeps\n// breathing and drifting, the gradients always scrolling. Grey to white, with the section's red in a few columns.\n// From 12:00 the colours arrive one at a time as accents, the way the red is: each takes its own few columns, rising\n// up them in two seconds, one every 17 s (blue, yellow, magenta, cyan, orange, lime). In the riot every column is in\n// colour; after it, back to grey with the accents\nvec3 cv_colColour(vec2 p, float t, float bin, float xc, float chev, float mA, float riot, float riotRun, float cyc) {\n  float wave = 0.12 * sin(bin * 0.45 + t * 0.27 + riotRun * 0.6);\n  float scroll = t * 0.035 + riotRun * 0.16;                         // the riot speeds it up and eases it back, never a jump\n  float u23 = fract((p.y + wave + scroll) * 1.6);\n  float apex = 0.38 + 0.05 * sin(t * 0.2);\n  float u25 = fract(abs(p.y - (apex - 0.95 * abs(xc - 0.08 * sin(t * 0.13))) + wave * 0.4) * 1.4 - scroll);\n  float u = mix(u23, u25, chev);\n  float ha = cv_hash(vec3(bin, 77.0, 1.0));\n  float k = floor(cv_hash(vec3(bin, 78.0, 2.0)) * 6.0);                  // this column's colour\n  float isRed = step(0.9, ha) * smoothstep(-0.1, 0.1, (mA - 10.75) * 30.0 - (p.y + 0.5));   // the red rises in at 10:45\n  float isAcc = step(ha, 0.16);\n  float since = (mA - 12.0) * 60.0 - k * 17.0;                          // seconds since this colour set off\n  float arr = isAcc * smoothstep(-0.1, 0.1, since / 2.0 - (p.y + 0.5));\n  vec3 mid = mix(vec3(0.55), vec3(0.86, 0.05, 0.07), isRed);\n  mid = mix(mid, cv_col(k), max(arr, riot));\n  return cv_ramp(u, mix(mid, cv_hueShift(mid, cyc), riot));\n}\n// the whole field: white streaks turning into columns, and at the end the same columns as thin running lines.\n// colK is the columns' shape (solid, every one present), colourK their colour. fringe splits red, green and blue at the\n// edges (the riot). shift and inside draw the circle in the lines (03, 04); allRed turns every line red\nvec3 cv_field(vec2 p, float t, float g, float px, float rec, float colK, float colourK, float chev, float mA, float riot,\n              float riotRun, float cyc, float fringe, float shift, float inside, float keep, float allRed) {\n  float bin, xc, b2, x2;\n  float mG = cv_fieldMask(p, t, g, px, rec, colK, shift, inside, keep, bin, xc);\n  vec3 m = vec3(mG);\n  float disp = 0.004 * fringe;\n  if (disp > 0.0001) {\n    m.r = cv_fieldMask(p + vec2(disp, 0.0), t, g, px, rec, colK, shift, inside, keep, b2, x2);\n    m.b = cv_fieldMask(p - vec2(disp, 0.0), t, g, px, rec, colK, shift, inside, keep, b2, x2);\n  }\n  vec3 W = vec3(0.8, 0.85, 0.85);\n  vec3 base = mix(W, cv_colColour(p, t, bin, xc, chev, mA, riot, riotRun, cyc), colourK);\n  base = mix(base, vec3(0.86, 0.05, 0.07) * (0.6 + 0.7 * dot(base, vec3(0.33))), allRed);\n  return base * m;\n}\n\n// ---------------------------------------------------------------- main\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  float aspect = RENDERSIZE.x / RENDERSIZE.y;\n  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);\n  float px = cv_px();\n\n  float tR = cv_t();                                                    // real time: where the arc is\n  float t = tR * motion;                                                // motion time: how fast it moves\n  float runT = cv_runT(tR) * motion;                                    // the lines' clock, ramping up from 0:20\n  // Hit: a short glitch on the beat, easing off over about a second\n  float hit = hitAge < 5.0 ? (1.0 - exp(-hitAge / 0.03)) * exp(-hitAge / 0.7) : 0.0;\n  float mA = cv_mA();\n\n  // the big moment: the first Hit between 13:00 and 13:45, or 13:45 if nobody presses (James: 54:41 in the set, 13:41)\n  float pressArc = mA - hitAge / 60.0, prevArc = mA - hitPrevAge / 60.0;\n  float W = 13.75;\n  if (prevArc >= 13.0 && prevArc <= 13.75) W = prevArc;\n  else if (pressArc >= 13.0 && pressArc <= 13.75) W = pressArc;\n  float wsec = (mA - W) * 60.0;                                         // seconds since; negative before\n  float riot = smoothstep(0.0, 3.0, wsec) * (1.0 - smoothstep(40.0, 60.0, wsec));\n  float riotRun = (cv_intSS(wsec, 0.0, 3.0) - cv_intSS(wsec, 40.0, 60.0)) * motion;   // the riot's extra run, eased both ends\n  float cyc = riotRun * 0.02;                                          // tint cycling, easing in and out with the riot\n  float allRed = smoothstep(120.0, 150.0, wsec);                        // the accents leave; the lines end all red\n  // after the riot the same columns carry on: they tip over into rows, draw together into thin lines as if the frame\n  // pulled back, and break back into running pieces; a circle shows in them, the lines outside drop out one by one\n  // around it, and the lines go red and start to undulate\n  float rotK = smoothstep(56.0, 66.0, wsec);\n  float zoomK = smoothstep(62.0, 76.0, wsec);\n  float breakK = smoothstep(72.0, 84.0, wsec);\n  float shapes = smoothstep(84.0, 96.0, wsec);\n  float gather = smoothstep(110.0, 130.0, wsec);\n  float retract = smoothstep(125.0, 155.0, wsec);\n  float settle = smoothstep(135.0, 150.0, wsec);\n  // every press punches the colour on the beat\n  float punch = hitAge < 6.0 ? (1.0 - exp(-hitAge / 0.06)) * exp(-hitAge / 1.8) : 0.0;\n\n  float gA = clamp(glitch * ARC_glitch(mA) + hit, 0.0, 2.0);\n  vec2 pg = cv_glitchShift(p, t, gA);\n\n  vec3 col = vec3(0.0);\n\n  // ------------------------------------------------ A. section 2's lines: drain, sharpen, break into dashes\n  float wS2 = ARC_s2(mA);\n  if (wS2 > 0.001) col = cv_s2end(pg, uv, tR, t, ARC_mono(mA), ARC_narrow(mA), ARC_break(mA), runT, redAmount, px);\n\n  // ------------------------------------------------ B. lines build across (a circle shows in them), grey bars build,\n  // the grey cuts into blocks, the blocks line up into stripes, the stripes into columns\n  float wDash = ARC_dashes(mA);\n  if (wDash > 0.001) col = cv_screen(col, cv_dashes(pg, t, runT, redAmount, ARC_across(mA), 1.0 - wS2, ARC_opCircle(mA), ringSize, px) * wDash);\n  float thickB = ARC_thickBars(mA);\n  if (thickB > 0.001 && mA < 2.2) {\n    vec4 gb = cv_greyBuild(pg, t, thickB, px, aspect);\n    col = mix(col, gb.rgb, gb.a);\n  }\n  float wCols = ARC_cols(mA);\n  if (wCols > 0.001) {\n    vec3 cols = cv_columns(pg, t, ARC_cut(mA), ARC_align(mA), ARC_split(mA), ARC_grow(mA), ARC_fall(mA), ARC_sparse(mA),\n                           ARC_toWave(mA), mix(ringSize * 1.55, ringSize, ARC_thicken(mA)), redAmount, px, aspect) * wCols;\n    col = mix(cols, cv_screen(col, cols), step(3.5, mA));             // replaces the grey, then shares the frame with the ring\n  }\n\n  // ------------------------------------------------ C. the ring: thickens and warps, its echo spreads into arcs and\n  // ripples, red creeps in, it tears and goes, the ripples running out past the edges\n  float wRing = ARC_ringIn(mA) * ARC_ringOut(mA);\n  float arcs = ARC_arcs(mA) * (1.0 - step(0.999, ARC_arcOut(mA)));\n  if (wRing > 0.001 || arcs > 0.001) {\n    float tk = ARC_thicken(mA);\n    float build = ARC_build(mA);\n    float tornK = ARC_tornK(mA);\n    vec3 rc = cv_ringScene(pg, t, mix(ringSize * 1.55, ringSize, tk), mix(0.012, 0.11, tk) * wRing,\n                           undulate * tk * (1.0 + build) * mix(1.0, 0.6, tornK), (0.6 * ARC_wave(mA) + 0.2 * tornK) * wRing,\n                           (0.5 * build + 0.5 * tornK) * wRing, ARC_wave(mA) * (1.0 - step(T_TEAR + 1.0, mA)), (1.0 - tk) * wRing,\n                           build * redAmount * (1.0 - tornK), gA, px, aspect, arcs, ARC_arcOut(mA));\n    col = cv_screen(col, rc);\n  }\n  // the waveform leaves the ring and jogs and tilts into the streaks\n  float wT = step(T_TEAR + 1.0, mA) * (1.0 - smoothstep(T_TEAR + 1.9, T_TEAR + 2.2, mA));\n  if (wT > 0.001) col = cv_screen(col, cv_waveTilt(pg, t, ARC_jog(mA), ARC_tilt(mA), ringSize, px, aspect) * wT);\n\n  // ------------------------------------------------ G. streaks, into columns, the colour, the riot; then the lines\n  float gS = ARC_streaks(mA);\n  if (gS > 0.001) {\n    // the circle, in screen space: it grows a little as the lines outside it drop out\n    vec2 cc = vec2(0.0, 0.02 * sin(t * 0.9) * (1.0 - gather));\n    float cr = mix(0.28, 0.33, gather) * (1.0 + 0.03 * sin(t * 1.1));\n    float cA = 1.0 - smoothstep(cr - px, cr + px, length(pg - cc));\n    vec2 pw = pg + vec2(0.0, settle * 0.012 * sin(pg.x * 18.0 + t * 1.6));   // the lines undulate at the end\n    float Z = mix(1.0, 7.6, zoomK);                                     // how far the rows have drawn together\n    vec2 pf = cv_rot(pw, rotK * 1.5708);\n    pf.x *= Z;\n    float colK = ARC_colK(mA) * (1.0 - breakK);\n    vec3 st = cv_field(pf, t, gS, px * Z, ARC_recede(mA), colK, ARC_colK(mA), ARC_chev(mA), mA, riot, riotRun, cyc,\n                       riot * 2.0, 0.5 * cA * shapes, cA * shapes, mix(1.0, 1.0 - retract, 1.0 - cA), allRed);\n    col = cv_screen(col, st * smoothstep(0.0, 0.06, gS));\n    col = mix(col, st, smoothstep(0.12, 0.18, gS));                   // after the first thin streaks, the field is the frame\n    // Hits punch the colour; the big moment lands as one\n    float surge = 0.6 * punch + 0.8 * exp(-max(wsec, 0.0) / 2.0) * step(0.0, wsec);\n    col *= 1.0 + surge * ARC_colK(mA) * (1.0 - allRed);\n  }\n\n  col = cv_hueShift(col, tint);\n  col = clamp(col, 0.0, 1.0);\n  col = pow(col, vec3(1.0 / lift));                                   // Lift: raise faint material for a weak projector\n  col += (cv_hash(vec3(uv * RENDERSIZE, 1.0)) - 0.5) / 255.0;          // dither\n  gl_FragColor = vec4(col, 1.0);\n}\n","decl":"uniform float timeScale;uniform float speed;uniform float hitAge;uniform float hitPrevAge;","def":{"timeScale":1.0,"speed":1.0,"hitAge":100000.0,"hitPrevAge":100000.0},"len":1020},{"body":"\n\n\n// ---------------------------------------------------------------- fixed for the v2 review: only Speed and Hit are live\n// Speed 1 is the designed speed, 1.0; the slider is a multiple of it, so the operator never needs the number\nconst float SPEED_DESIGN = 1.0;\n#define motion (speed * SPEED_DESIGN)\nconst float bloomTime = 15.0;\nconst float bloomSize = 1.0;\nconst float autoRate = 60.0;\nconst float D0 = 15.0;                                                  // the drop, in minutes\n\n// ---------------------------------------------------------------- helpers\nfloat cv_hash(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.yzx + 33.33);\n  return fract((p.x + p.y) * p.z);\n}\nfloat cv_noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(mix(cv_hash(i + vec3(0,0,0)), cv_hash(i + vec3(1,0,0)), f.x),\n        mix(cv_hash(i + vec3(0,1,0)), cv_hash(i + vec3(1,1,0)), f.x), f.y),\n    mix(mix(cv_hash(i + vec3(0,0,1)), cv_hash(i + vec3(1,0,1)), f.x),\n        mix(cv_hash(i + vec3(0,1,1)), cv_hash(i + vec3(1,1,1)), f.x), f.y), f.z);\n}\nfloat cv_fbm(vec3 p) {\n  return 0.5 * cv_noise(p) + 0.3 * cv_noise(p * 2.03 + 7.1) + 0.2 * cv_noise(p * 4.11 + 13.7);\n}\n// 0 outside [a,d], 1 between b and c\nfloat cv_bump(float x, float a, float b, float c, float d) {\n  return smoothstep(a, b, x) * (1.0 - smoothstep(c, d, x));\n}\nvec3 cv_screen(vec3 a, vec3 b) {\n  return vec3(1.0) - (vec3(1.0) - a) * (vec3(1.0) - b);\n}\nvec2 cv_rot(vec2 p, float a) {\n  float c = cos(a), s = sin(a);\n  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n// the integral of smoothstep(a, b, s) from a to x: a speed that eases up from a to b, as a distance travelled\nfloat cv_intSS(float x, float a, float b) {\n  float u = clamp((x - a) / (b - a), 0.0, 1.0);\n  return (b - a) * (u * u * u - 0.5 * u * u * u * u) + max(x - b, 0.0);\n}\n\n// ---------------------------------------------------------------- arc\n// Minutes, compressed from v9's thirty. W is the big moment (the return), D0 the drop.\nfloat ARC_red(float m)    { return 1.0 - smoothstep(0.3, 1.2, m); }         // A. section 3's red drains to grey\nfloat ARC_rag(float m)    { return smoothstep(0.1, 0.9, m); }               //    the outline goes irregular early\nfloat ARC_swirl(float m)  { return smoothstep(0.6, 2.0, m); }               //    the circle's lines ripple into ribbons\nfloat ARC_opening(float m) { return 1.0 - smoothstep(2.3, 3.0, m); }        //    the grey one sinks as the magenta one grows\nfloat ARC_ink(float m)    { return smoothstep(2.2, 4.0, m); }               // B. the blooms fill with ink\nfloat ARC_ground(float m) { return smoothstep(8.9, 9.9, m); }               // C. the iridescent ground rises out of the last blooms\n// amber 0, iridescent 1, pastel 2: iridescent from the start (James cut the plum and orange \"fire\"); back to the bands\n// for the interlude (10:40-13:10); iridescent again, part way to pastel by 14:10, and the plain gradient after the drop\nfloat ARC_drift(float m) {\n  return 1.0 - smoothstep(10.6, 10.9, m) + smoothstep(13.3, 13.7, m)\n       + 0.55 * smoothstep(13.7, 14.2, m) + 0.45 * smoothstep(D0 + 0.05, D0 + 0.4, m);\n}\nconst float INTERLUDE = 11.0;                                           // the interlude's first bloom lands, in minutes\nfloat ARC_inC(float b)    { return 0.0; }                                // clusters into the bands: cut with the fire\nfloat ARC_clear(float m)  { return smoothstep(D0, D0 + 0.13, m); }          // the drop: the blooms clear in eight seconds\nfloat ARC_shift(float m)  { return smoothstep(D0 + 0.1, 17.0, m); }         // the gradient alone, changing colour\nfloat ARC_return(float m, float W) { return smoothstep(W, W + 0.06, m); }  // on the Hit it goes to black behind the blooms\nfloat ARC_dark(float m, float W)   { return smoothstep(W + 0.3, W + 1.0, m); }   // E. darker, back into lines\nfloat ARC_bands(float m, float W)  { return smoothstep(W + 0.5, W + 1.5, m); }   //    bands slide across\nfloat ARC_final(float m, float W)  { return smoothstep(W + 1.0, W + 1.8, m); }   //    the dark red bloom of lines gathers\nfloat ARC_haze(float m, float W)   { return smoothstep(W + 1.7, W + 2.5, m); }   //    greys to purple, tilts and blurs into haze for 05\n// how many of the scheduled drops land, by the minute each is born: all of them through B to 8:30, none as the ground\n// rises out of the last ones or around the drop, a few after the return, then none as the final bloom takes over\nfloat ARC_drops(float b, float W) {\n  float pre = step(2.2, b) * (1.0 - step(8.5, b));\n  float post = step(W + 0.3, b) * (1.0 - smoothstep(W + 0.8, W + 1.1, b));\n  return pre + post;\n}\n\n// ---------------------------------------------------------------- palettes\n// deep, mid and hot colour of one bloom. 0-7 the B sequence, 8 magenta, 9 dark violet, 10 dark red, 11 grey, 12 red,\n// 13 grey purple\nvoid cv_pal(float k, out vec3 a, out vec3 b, out vec3 c) {\n  a = vec3(0.03, 0.06, 0.35); b = vec3(0.12, 0.32, 0.95); c = vec3(0.45, 0.8, 1.0);  // blue\n  if (k > 0.5)  { a = vec3(0.08, 0.28, 0.05); b = vec3(0.48, 0.85, 0.3);  c = vec3(0.9, 1.0, 0.8); }    // green\n  if (k > 1.5)  { a = vec3(0.22, 0.2, 0.02);  b = vec3(0.62, 0.6, 0.1);   c = vec3(0.95, 0.92, 0.45); } // gold-green\n  if (k > 2.5)  { a = vec3(0.45, 0.25, 0.0);  b = vec3(1.0, 0.82, 0.1);   c = vec3(1.0, 1.0, 0.7); }    // yellow\n  if (k > 3.5)  { a = vec3(0.02, 0.03, 0.4);  b = vec3(0.06, 0.16, 0.95); c = vec3(0.4, 0.5, 1.0); }    // deep blue\n  if (k > 4.5)  { a = vec3(0.18, 0.05, 0.35); b = vec3(0.5, 0.2, 0.85);   c = vec3(0.8, 0.62, 1.0); }   // violet\n  if (k > 5.5)  { a = vec3(0.4, 0.13, 0.1);   b = vec3(0.95, 0.35, 0.6);  c = vec3(1.0, 0.8, 0.4); }    // pink-gold\n  if (k > 6.5)  { a = vec3(0.35, 0.02, 0.05); b = vec3(0.9, 0.1, 0.15);   c = vec3(1.0, 0.6, 0.25); }   // red-orange\n  if (k > 7.5)  { a = vec3(0.3, 0.02, 0.22);  b = vec3(0.85, 0.12, 0.6);  c = vec3(1.0, 0.6, 0.92); }   // magenta\n  if (k > 8.5)  { a = vec3(0.1, 0.02, 0.2);   b = vec3(0.42, 0.1, 0.75);  c = vec3(0.8, 0.4, 1.0); }    // dark violet\n  if (k > 9.5)  { a = vec3(0.22, 0.02, 0.05); b = vec3(0.62, 0.06, 0.16); c = vec3(0.85, 0.22, 0.24); }  // dark red\n  if (k > 10.5) { a = vec3(0.12);             b = vec3(0.55);             c = vec3(0.95); }             // grey\n  if (k > 11.5) { a = vec3(0.86, 0.05, 0.07); b = a;                      c = a; }                      // section 3's red\n  if (k > 12.5) { a = vec3(0.14, 0.12, 0.19); b = vec3(0.46, 0.41, 0.56); c = vec3(0.74, 0.69, 0.84); } // grey purple\n}\n\n// ---------------------------------------------------------------- A. section 3's end, on section 3's clock\n// Section 3 (v38) holds on a disc of thin red lines, undulating, each line's brightness a stepped gradient scrolling\n// round a chevron: its streak field turned 90 degrees and drawn together 7.6x, seen from a vanishing point 7 away,\n// every line unbroken inside the circle, the colour drained to red. This is section 3's maths with its arc settled.\n// Section 3 ran at Speed 2; the motion clock cv_tL is section 3's at 17:00 on this section's first frame, easing to\n// this section's Speed over 0:20-1:20. The opening bloom keeps these lines for its whole life, so they are what\n// ripples into ribbons.\nconst float S3_RIOTRUN = 97.0;                                          // section 3's settled riot run, 48.5 s at Speed 2\nvec3 cv_s3col(float k) {\n  if (k < 0.5) return vec3(0.25, 0.55, 1.0);\n  if (k < 1.5) return vec3(1.0, 0.25, 0.7);\n  if (k < 2.5) return vec3(1.0, 0.5, 0.08);\n  if (k < 3.5) return vec3(0.1, 0.85, 0.85);\n  if (k < 4.5) return vec3(1.0, 0.85, 0.15);\n  return vec3(0.55, 1.0, 0.25);\n}\nvec3 cv_s3ramp(float u, vec3 c) {\n  vec3 dark = vec3(0.06, 0.0, 0.04), deep = c * 0.3, top = vec3(0.97, 0.95, 0.88);\n  return u < 0.15 ? mix(dark, deep, u / 0.15) : (u < 0.5 ? mix(deep, c, (u - 0.15) / 0.35) : mix(c, top, (u - 0.5) / 0.5));\n}\nfloat cv_s3bright(vec2 pf, float t, float bin, float xc) {\n  float wave = 0.12 * sin(bin * 0.45 + t * 0.27 + S3_RIOTRUN * 0.6);\n  float scroll = t * 0.035 + S3_RIOTRUN * 0.16;\n  float apex = 0.38 + 0.05 * sin(t * 0.2);\n  float u = fract(abs(pf.y - (apex - 0.95 * abs(xc - 0.08 * sin(t * 0.13))) + wave * 0.4) * 1.4 - scroll);\n  float ha = cv_hash(vec3(bin, 77.0, 1.0));\n  float k = floor(cv_hash(vec3(bin, 78.0, 2.0)) * 6.0);\n  vec3 mid = mix(vec3(0.55), vec3(0.86, 0.05, 0.07), step(0.9, ha));\n  mid = mix(mid, cv_s3col(k), step(ha, 0.16));\n  return 0.6 + 0.7 * dot(cv_s3ramp(u, mid), vec3(0.33));\n}\n// the lines at q (screen position relative to the circle's centre), brightness times coverage. cA is the circle's own\n// coverage: 1 inside, and section 3's edge terms only matter where it is fractional\nfloat cv_s3lines(vec2 q, float t, float px, float cA) {\n  vec2 pw = q + vec2(0.0, 0.012 * sin(q.x * 18.0 + t * 1.6));\n  vec2 pf = cv_rot(pw, 1.5708);\n  pf.x *= 7.6;\n  vec2 d = pf - vec2(0.0, 7.0);\n  float rd = length(d);\n  float fa = atan(d.x, -d.y) / 3.1416 * 260.0 + 0.5 * cA;\n  float bin = floor(fa);\n  float h = cv_hash(vec3(bin, 91.0, 1.0));\n  float h2 = cv_hash(vec3(bin, 92.0, 2.0));\n  float wdt = 0.25 + 0.6 * h2;\n  float pxa = (px * 7.6) / max(rd * 3.1416 / 260.0, 0.0005);\n  float across = 1.0 - smoothstep(wdt * 0.5 - pxa, wdt * 0.5 + pxa, abs(fract(fa) - 0.5));\n  float on = smoothstep(h - 0.03, h, mix(0.7, 1.05, cA));\n  float ph = fract(rd * (1.2 + 1.5 * h) - t * (0.6 + 1.2 * h2) + h * 9.0);\n  float along = smoothstep(0.0, 0.02, ph) * (1.0 - smoothstep(0.35 + 0.5 * h, 0.37 + 0.5 * h, ph));\n  float stay = smoothstep(0.0, 0.2, cA * 1.2 - cv_hash(vec3(bin, 93.0, 3.0)));\n  float xc = (7.0 - pf.y) * tan((bin + 0.5) / 260.0 * 3.1416);\n  return cv_s3bright(pf, t, bin, xc) * on * across * mix(along, 1.0, cA) * stay;\n}\nvec3 cv_s3end(vec2 p, float t, float px) {\n  float cr = 0.33 * (1.0 + 0.03 * sin(t * 1.1));\n  float cA = 1.0 - smoothstep(cr - px, cr + px, length(p));\n  if (cA <= 0.0) return vec3(0.0);\n  return vec3(0.86, 0.05, 0.07) * cv_s3lines(p, t, px, cA);\n}\n// the motion clock: section 3's at its Speed 2 for the first 20 s, easing to this section's Speed by 1:20\nfloat cv_tL(float tR) { return 2.0 * (tR + 1020.0) + (motion - 2.0) * cv_intSS(tR, 20.0, 80.0); }\n\n// ---------------------------------------------------------------- the bloom\n// section 3's line field: horizontal lines, gently undulating, scrolling slowly\nfloat cv_lineField(vec2 q, float t, float freq, float speed, float wobble, float px, float blur) {\n  float y = q.y + wobble * 0.012 * sin(q.x * 18.0 + t * 1.6 + floor(q.y * freq) * 0.7);\n  float f = fract(y * freq - t * speed);\n  float w = px * freq * 1.2 + blur * 0.3;\n  float l = smoothstep(0.1 - w, 0.1 + w, f) * (1.0 - smoothstep(0.55 - w, 0.55 + w, f));\n  return mix(l, 0.45, smoothstep(0.1, 0.35, blur));                   // blurred right out, the lines average to a haze\n}\n// how far a bloom bends its lines up or down at q: the same flowing height field cv_bloom uses, so something else can draw\n// a bloom's own ribbons (the opening sphere hands its lines over to the magenta bloom with this)\nfloat cv_bloomPush(vec2 q, float R, float seed, float swirl, float t) {\n  vec2 u = q / max(R, 0.001);\n  float tt = t * 0.035 + seed * 7.0;\n  vec2 us = u + 0.45 * min(swirl, 1.6) * (vec2(cv_fbm(vec3(u * 1.3, tt)), cv_fbm(vec3(u * 1.3 + 5.0, tt))) - 0.5);\n  float sw = 0.5 + 1.1 * (cv_fbm(vec3(us * 1.1 + seed * 3.1, tt)) - 0.5);\n  return R * 0.06 * min(swirl, 1.6) * (sw - 0.5) * 2.0;\n}\n// One bloom. q is screen position relative to where it landed, R its radius now. swirl 0 is a plain circle of lines;\n// swirl bends them up and down by a slow flowing height field into ribbons (no rotation: James cut the pinwheel).\n// ink 0 draws it in lines, ink 1 fills it with ink laid along the same ribbons and curls smoke off its edge. rag makes\n// the outline irregular; blur softens lines and edge into haze. s3 draws its lines with section 3's (the opening one).\n// Returns colour (premultiplied) and coverage.\nvec4 cv_bloom(vec2 q, float R, float seed, float swirl, float ink, vec3 cA, vec3 cB, vec3 cC, float t, float px,\n              float rag, float blur, float s3) {\n  vec2 u = q / max(R, 0.001);\n  float r = length(u);\n  if (r > 2.3) return vec4(0.0);\n  vec2 dir = u / max(r, 0.0001);\n  float tt = t * 0.035 + seed * 7.0;\n  // ragged edge, raggeder as it fills with ink\n  float ragged = max(swirl, rag);\n  float rim = 1.0 + (0.1 + 0.2 * ink) * ragged * (cv_fbm(vec3(dir * 2.2 + seed, tt * 0.9)) - 0.5) * 2.0;\n  float soft = mix(px / max(R, 0.001), 0.14, min(ragged, 1.0)) + 0.45 * blur;\n  float mask = 1.0 - smoothstep(rim - soft, rim + soft * 0.2, r);\n  // Past the rim the bloom is nothing but its smoke, which needs none of the inside\n  if (mask <= 0.0) {\n    if (ink <= 0.001) return vec4(0.0);\n    vec2 w0 = u * 1.3 + vec2(cv_fbm(vec3(u * 1.1, tt)), cv_fbm(vec3(u * 1.1 + 4.0, tt))) * 1.6;\n    float sm = smoothstep(0.52, 0.85, cv_fbm(vec3(w0, tt * 0.8 + seed)))\n             * smoothstep(0.75, 1.05, r) * exp(-max(r - 1.0, 0.0) * 2.4) * 0.75;\n    return mix(vec4(0.0), vec4(mix(cA, cB, 0.35) * sm, clamp(sm, 0.0, 1.0)), ink);\n  }\n  // the inside flows: a slow noise field drags it sideways, no turning round the centre\n  vec2 us = u + 0.45 * min(swirl, 1.6) * (vec2(cv_fbm(vec3(u * 1.3, tt)), cv_fbm(vec3(u * 1.3 + 5.0, tt))) - 0.5);\n  // a smooth height field of slow noise: the ribbons' rise and fall\n  float sw = 0.5 + 1.1 * (cv_fbm(vec3(us * 1.1 + seed * 3.1, tt)) - 0.5);\n  float ridge = 1.0 - abs(2.0 * sw - 1.0);\n\n  // lines, pushed up and down by it into ribbons\n  float push = R * 0.06 * min(swirl, 1.6) * (sw - 0.5) * 2.0;\n  float ln = s3 > 0.5 ? cv_s3lines(vec2(q.x, q.y + push), t, px, 1.0) : cv_lineField(vec2(q.x, q.y + push), t, 60.0, 0.15, 1.0, px, blur);\n  float lum = ln * mask * mix(1.0, 0.25 + 0.95 * ridge * ridge, min(swirl, 1.0));\n  vec3 lineCol = mix(cB, cC, ridge * ridge) * lum;\n\n  // ink laid along wider ribbons of the same field, in clumps, smoke curling off the edge\n  vec3 inkCol = vec3(0.0);\n  float inkA = 0.0;\n  if (ink > 0.001) {\n    float strand = cv_lineField(vec2(q.x, q.y + push), t, 64.0, 0.12, 1.0, px, blur);\n    float clump = cv_fbm(vec3(us * 1.7 - seed, tt * 1.3));\n    float dens = mask * clamp((0.35 + 0.65 * strand) * (0.45 + 0.85 * clump) * (1.05 - 0.25 * r), 0.0, 1.0);\n    vec3 c = mix(cA, cB, smoothstep(0.25, 0.75, clump + 0.25 * strand));\n    c = mix(c, cC, smoothstep(0.6, 1.0, strand * 0.7 * (1.1 - 0.6 * r) + 0.45 * ridge) * 0.8);\n    vec2 w = u * 1.3 + vec2(cv_fbm(vec3(u * 1.1, tt)), cv_fbm(vec3(u * 1.1 + 4.0, tt))) * 1.6;\n    float smoke = smoothstep(0.52, 0.85, cv_fbm(vec3(w, tt * 0.8 + seed)))\n                * smoothstep(0.75, 1.05, r) * exp(-max(r - 1.0, 0.0) * 2.4) * 0.75;\n    vec3 smokeCol = mix(cA, cB, 0.35);\n    inkA = clamp(dens + smoke, 0.0, 1.0);\n    inkCol = c * dens + smokeCol * smoke + lineCol * 0.25;\n  }\n  return mix(vec4(lineCol, lum), vec4(inkCol, inkA), ink);\n}\n// how far a bloom has unfurled after age seconds: fast out, easing to a slow creep that never quite stops\nfloat cv_unfurl(float age, float T) {\n  float x = clamp(age / T, 0.0, 1.0);\n  float g = 1.0 - (1.0 - x) * (1.0 - x) * (1.0 - x);\n  return (0.03 + 0.97 * g) * (1.0 + 0.2 * max(age - T, 0.0) / 400.0);\n}\n// a drop landing into the ground rather than on it: inside its ragged outline the ground's own contour bands take the\n// drop's colours (troughs its deep colour, bands its mid, crests its hot), so the colour runs along the bands\nvec3 cv_into(vec3 col, vec3 g0, vec2 q, float R, float seed, float t, vec3 cA, vec3 cB, vec3 cC, float a) {\n  vec2 u = q / max(R, 0.001);\n  float r = length(u);\n  if (r > 1.6 || a < 0.001) return col;\n  vec2 dir = u / max(r, 0.0001);\n  float tt = t * 0.035 + seed * 7.0;\n  float lum = dot(col, vec3(0.3, 0.59, 0.11));                         // what is there now, so it never punches a hole\n  // the colour runs further along the bright bands than across the troughs\n  float rim = 1.0 + 0.3 * (cv_fbm(vec3(dir * 2.2 + seed, tt * 0.9)) - 0.5) * 2.0 + 0.45 * (lum - 0.3);\n  float mask = 1.0 - smoothstep(rim - 0.35, rim + 0.05, r);\n  // the ground recoloured, its light and dark kept: troughs deep, bands mid, crests hot\n  vec3 tinted = mix(cA, cB, smoothstep(0.04, 0.4, lum));\n  tinted = mix(tinted, cC, smoothstep(0.55, 0.8, lum));\n  tinted *= max(lum, 0.06) * 1.15 / max(dot(tinted, vec3(0.3, 0.59, 0.11)), 0.02);\n  return mix(col, clamp(tinted, 0.0, 1.0), mask * a);\n}\n// a soft diffused sphere (James: a 3D object whose colours evolve): wrapped soft light from the upper left, a glow round\n// its rim, its surface slowly turning with a faint drift of light through it, a feathered edge and a halo. No lines, no\n// pattern. cA deep, cB mid, cC hot. Returns colour (premultiplied) and coverage\nvec4 cv_softOrb(vec2 q, float R, vec3 cA, vec3 cB, vec3 cC, float t, float feather) {\n  vec2 u = q / max(R, 0.001);\n  float r = length(u);\n  if (r > 1.0 + 4.0 * feather + 0.8) return vec4(0.0);\n  float z = sqrt(max(1.0 - r * r, 0.0));\n  vec3 n = vec3(u / max(r, 1.0), z);\n  vec3 L = normalize(vec3(-0.45, 0.5, 0.75));\n  float diff = dot(n, L) * 0.5 + 0.5;                                   // wrapped: the shadow side stays lit, softly\n  vec3 nr = n;\n  nr.xz = cv_rot(nr.xz, t * 0.02);\n  float fl = cv_fbm(nr * 1.6 + vec3(0.0, 0.0, t * 0.004));\n  vec3 c = mix(cA, cB, smoothstep(0.15, 0.75, diff));\n  c = mix(c, cC, smoothstep(0.72, 1.0, diff) * 0.6);\n  c *= 0.88 + 0.26 * fl;\n  c += cC * 0.3 * pow(1.0 - z, 3.0);                                    // light gathering at the rim\n  float a = 1.0 - smoothstep(1.0 - feather, 1.0 + feather, r);\n  float halo = exp(-max(r - 1.0, 0.0) * 3.5) * 0.35 * (1.0 - a);\n  return vec4(c * a + cB * halo, clamp(a + halo * 0.5, 0.0, 1.0));\n}\n// The sphere's strips (ref 08 as inspiration), all the way through, evenly over the whole sphere. They start as section\n// 3's lines at its spacing (bright lines, dark between), widen into soft strips shaded light to dark like 08's slices\n// (wd), then narrow back into lines that wave (rk), at the blooms' own spacing. hk: in its last seconds its lines become\n// the magenta bloom's own ribbons (qb, pushB). leave: the sphere leaves, its glow and halo draining away between the\n// lines until only the lines are left, which the bloom then takes over\nvec4 cv_slicedOrb(vec2 q, float R, vec3 cA, vec3 cB, vec3 cC, float t, float wd, float rk, vec2 qb, float pushB, float hk,\n                  float leave, float px) {\n  float lk = clamp(1.0 - wd + rk, 0.0, 1.0);                             // how line-like the strips are\n  float h = mix(mix(1.0 / 89.85, R / 7.5, wd), 1.0 / 64.0, rk);\n  float yw = q.y + rk * R * 0.035 * sin(q.x / R * 5.0 + t * 0.3) * (1.0 + 0.5 * sin(q.y / R * 3.0 - t * 0.1));\n  float fy = (yw + 1.3 * R) / h;\n  float fr = fract(fy);\n  float dx = 0.018 * R * sin(t * 0.09 + floor(fy) * 1.7) * (1.0 - lk);   // wide strips sway a hair, each on its own\n  vec4 o = cv_softOrb(q - vec2(dx, 0.0), R, cA, cB, cC, t, 0.07);\n  float prof = pow(1.0 - fr, mix(1.0, 7.0, lk));                         // a soft gradient, or a line at the lower edge\n  if (hk > 0.001) prof = mix(prof, cv_lineField(vec2(qb.x, qb.y + pushB), t, 64.0, 0.12, 1.0, px, 0.0), hk);\n  float strength = mix(0.35, 1.0, lk) * smoothstep(0.35, 0.9, o.a);     // in the body only; the glow stays unlined\n  o.rgb *= mix(1.0, mix(0.8, 0.25, lk) + mix(0.45, 1.4, lk) * prof, strength);\n  o *= mix(1.0, prof * smoothstep(0.35, 0.9, o.a), leave);\n  return o;\n}\n// lay one bloom over the frame: lines add light, ink lies over what is there\nvec3 cv_lay(vec3 col, vec4 b, float ink, float a) {\n  b *= a;\n  return mix(cv_screen(col, b.rgb), col * (1.0 - b.a) + b.rgb, ink);\n}\n\n// ---------------------------------------------------------------- C. the warm ground\n// soft orange contour bands on maroon that breathe; drift 1 turns them into an iridescent terrain, 2 a pastel gradient\nfloat cv_groundField(vec2 p, float tt) {\n  vec2 w = vec2(cv_fbm(vec3(p * 0.7, tt)), cv_fbm(vec3(p * 0.7 + 5.2, tt + 3.0)));\n  return cv_fbm(vec3(p * 0.9 + w * 0.9, tt * 1.3));\n}\n// rise 0..1: the plum comes up out of black and the orange bands grow out of their crests, never a murky wash\n// alt 1 recolours the bands for the interlude: deep navy with teal-cyan bands, so it isn't the plum and orange again\n// warm (the interlude, after refs 30 and 11, in its own material): the navy and teal drift to deep violet with coral\n// and orange bands. rip: slow soft vertical ripples pass sideways through the bands, stretching and squeezing them\n// lift 0..1: the terrain comes up out of black, its high strata first\nvec3 cv_ground(vec2 p, float t, float drift, float rise, float shift, float alt, float warm, float rip, float lift) {\n  float tt = t * 0.012;\n  p.x += rip * 0.035 * sin(p.x * 7.0 - t * 0.035) * (0.7 + 0.3 * sin(p.y * 1.3 + t * 0.01));\n  float v = cv_groundField(p, tt);\n  float band = 0.5 + 0.5 * cos(v * 6.2832 * 3.0 - tt * 2.0);\n  float lo = mix(0.97, 0.3, rise);\n  vec3 base = mix(vec3(0.2, 0.01, 0.1), mix(vec3(0.02, 0.04, 0.15), vec3(0.12, 0.04, 0.2), warm), alt);\n  vec3 bandC = mix(vec3(1.0, 0.42, 0.03), mix(vec3(0.08, 0.7, 0.78), mix(vec3(0.95, 0.42, 0.3), vec3(0.6, 0.35, 0.9), 0.3), warm), alt);\n  vec3 crest = mix(vec3(1.0, 0.6, 0.18), mix(vec3(0.55, 0.95, 0.92), vec3(1.0, 0.68, 0.45), warm), alt);\n  vec3 amber = mix(base * smoothstep(0.0, 0.6, rise), bandC, smoothstep(lo, 1.0, band) * smoothstep(0.0, 0.3, rise));\n  amber = mix(amber, crest, smoothstep(0.92, 1.0, band) * 0.45 * rise);\n  vec3 col = amber;\n  float iri = cv_bump(drift, 0.0, 0.9, 1.1, 2.0);\n  if (iri > 0.001) {\n    // the contours become strata of a lit terrain, coloured by the angle of its surface\n    float e = 0.006;\n    float h0 = v + 0.18 * cv_noise(vec3(p * vec2(5.0, 12.0), tt * 2.0));\n    float hx = cv_groundField(p + vec2(e, 0.0), tt) + 0.18 * cv_noise(vec3((p + vec2(e, 0.0)) * vec2(5.0, 12.0), tt * 2.0));\n    float hy = cv_groundField(p + vec2(0.0, e), tt) + 0.18 * cv_noise(vec3((p + vec2(0.0, e)) * vec2(5.0, 12.0), tt * 2.0));\n    vec3 n = normalize(vec3(-(hx - h0) / e * 0.08, -(hy - h0) / e * 0.08, 1.0));\n    vec3 L = normalize(vec3(-0.4, 0.5, 0.75));\n    float diff = max(dot(n, L), 0.0);\n    float spec = pow(max(dot(reflect(-L, n), vec3(0.0, 0.0, 1.0)), 0.0), 24.0);\n    vec3 rainbow = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.33, 0.67) + dot(n.xy, vec2(1.6, 1.0)) * 1.4 + h0 * 2.5 + tt));\n    vec3 terrain = mix(mix(vec3(0.85), rainbow, 0.6), vec3(0.95), smoothstep(0.5, 0.75, h0) * 0.6) * (0.35 + 0.75 * diff) + spec * 0.6;\n    terrain *= smoothstep(mix(0.85, 0.05, lift), mix(1.15, 0.35, lift), h0) * smoothstep(0.0, 0.5, lift);\n    col = mix(col, terrain, iri);\n    col = clamp(mix(vec3(dot(col, vec3(0.3, 0.59, 0.11))), col, 1.0 + 0.6 * iri * (1.0 - iri) * 4.0), 0.0, 1.0); // no grey halfway\n  }\n  float pas = smoothstep(1.0, 2.0, drift);\n  if (pas > 0.001) {\n    vec2 gd = normalize(vec2(1.0, -0.55 + 1.1 * shift));                 // alone, the gradient turns and changes colour\n    float g = clamp(dot(p, gd) * 0.5 + 0.5 + 0.18 * (v - 0.5) + 0.06 * sin(tt * 4.0), 0.0, 1.0);\n    vec3 s0 = mix(vec3(0.75, 0.55, 0.85), vec3(0.98, 0.72, 0.62), shift);  // lilac to peach\n    vec3 s1 = mix(vec3(0.38, 0.56, 0.95), vec3(0.62, 0.5, 0.92), shift);   // blue to violet\n    vec3 s2 = mix(vec3(0.45, 0.8, 0.7), vec3(0.5, 0.82, 0.88), shift);     // mint to aqua\n    vec3 s3 = mix(vec3(0.97, 0.62, 0.76), vec3(0.92, 0.55, 0.8), shift);   // pink to rose\n    vec3 pastel = mix(s0, s1, smoothstep(0.0, 0.4, g));\n    pastel = mix(pastel, s2, smoothstep(0.35, 0.65, g));\n    pastel = mix(pastel, s3, smoothstep(0.6, 1.0, g));\n    col = mix(col, pastel, pas);\n    // halfway between terrain and pastel the mix goes grey; hold the saturation up through it\n    float mid = pas * (1.0 - pas) * 4.0;\n    col = clamp(mix(vec3(dot(col, vec3(0.3, 0.59, 0.11))), col, 1.0 + 0.9 * mid), 0.0, 1.0);\n  }\n  return col;\n}\n\n// ---------------------------------------------------------------- main\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  float aspect = RENDERSIZE.x / RENDERSIZE.y;\n  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);\n  float px = 1.0 / RENDERSIZE.y;\n\n  float tR = TIME * timeScale;                                          // real time: the arc, and every bloom's age\n  float t = cv_tL(tR);                                                  // motion time: how fast everything moves\n  float m = min(tR / 60.0, 19.5);\n  float mA = m;\n\n  // the big moment: the first Hit between 16:00 and 17:00, or 17:00 if nobody presses (James: 1:17:30, 16:30).\n  // It is the return: the blooms come back all at once on the beat\n  float pressArc = m - hitAge / 60.0, prevArc = m - hitPrevAge / 60.0;\n  float W = 17.0;\n  if (prevArc >= 16.0 && prevArc <= 17.0) W = prevArc;\n  else if (pressArc >= 16.0 && pressArc <= 17.0) W = pressArc;\n  // every press swells on the beat\n  float punch = hitAge < 6.0 ? (1.0 - exp(-hitAge / 0.05)) * exp(-hitAge / 1.2) : 0.0;\n  float surge = 1.0 + 0.12 * punch;\n\n  float inkG = ARC_ink(mA) * (1.0 - 0.85 * ARC_dark(mA, W));\n\n  // E. horizontal bands: rows slide sideways in eased glides, gaps open between them, a few flare into bright bars.\n  // At the end everything tilts, greys to purple and blurs into haze, for section 5's line into depth\n  float haze = ARC_haze(mA, W);\n  float bands = ARC_bands(mA, W);\n  vec2 pr = cv_rot(p, -0.32 * haze);\n  float rows = 18.0;\n  float rowY = (pr.y + 0.5) * rows;\n  float row = floor(rowY);\n  float hr = cv_hash(vec3(row, 5.0, 9.0));\n  float ph = t / (2.5 + 2.0 * hr) + hr * 5.0;\n  float off = mix(cv_hash(vec3(row, floor(ph), 1.0)), cv_hash(vec3(row, floor(ph) + 1.0, 1.0)), smoothstep(0.0, 0.35, fract(ph))) - 0.5;\n  vec2 pb = pr + vec2(off * 0.3 * bands * (1.0 - 0.6 * haze) * step(0.3, hr), 0.0);\n\n  // ------------------------------------------------ C. the ground, gone to black at the return\n  vec3 col = vec3(0.0);\n  float rise = ARC_ground(mA);\n  float gA = rise * (1.0 - ARC_return(mA, W));\n  if (gA > 0.001) col = cv_ground(p, t, ARC_drift(mA), mix(rise, 0.42 * rise, cv_bump(mA, 10.5, 10.9, 12.9, 13.3)), ARC_shift(mA),\n                                   cv_bump(mA, 10.4, 10.7, 13.1, 13.5), smoothstep(11.0, 12.3, mA), cv_bump(mA, 11.2, 12.0, 12.8, 13.4), clamp((mA - 8.8) / 1.1, 0.0, 1.0)) * (1.0 - ARC_return(mA, W)) * (1.0 + 0.25 * punch);\n\n  vec3 g0 = col;                                                      // the ground alone, for drops that land into it\n  float intoK = smoothstep(0.3, 0.8, gA);                             // how much a drop lands into the ground, not on it\n  vec3 cA, cB, cC, dA, dB, dC;\n\n  // ------------------------------------------------ A. section 3's circle: its lines soften into a diffused sphere of light\n  // that shifts red to rose to magenta (James's 3D object), which loosens back into magenta ribbons for the first bloom\n  float wO = ARC_opening(mA);\n  if (wO > 0.001) {\n    cv_pal(12.0, cA, cB, cC);\n    cv_pal(8.0, dA, dB, dC);\n    float red = ARC_red(mA);\n    float R = 0.33 * (1.0 + 0.03 * sin(t * 1.1)) * (1.0 + 0.15 * smoothstep(1.0, 2.5, mA)) * surge;\n    vec2 c = vec2(0.0, -0.06 * smoothstep(1.8, 2.8, mA));              // and sinks as it goes\n    float sphK = smoothstep(0.35, 1.1, mA);                            // the sphere carries the opening from here to its end\n    // the magenta bloom that takes over, as it will be: its lines, for the handover\n    float ageM0 = max((mA - 2.3) * 60.0, 0.0);\n    float RM = 0.34 * bloomSize * mix(0.85, 1.0, cv_unfurl(ageM0, bloomTime * 2.0)) * surge;\n    vec2 qM = pb - vec2(0.0, -0.04);\n    float hk = smoothstep(2.05, 2.35, mA);\n    float pushM = hk > 0.001 ? cv_bloomPush(qM, RM, 1.7, 1.0 + 1.5 * (1.0 - min(ageM0 / bloomTime, 1.0)), t) : 0.0;\n    vec4 b = cv_bloom(pb - c, R, 0.0, ARC_swirl(mA), 0.0, mix(dA, cA, red), mix(dB, cB, red), mix(dC, cC, red), t, px, ARC_rag(mA), 0.0, 1.0);\n    col = cv_lay(col, b, 0.0, wO * (1.0 - sphK));\n    if (sphK > 0.001) {\n      vec3 base = mix(vec3(0.86, 0.05, 0.07), vec3(0.95, 0.25, 0.45), smoothstep(0.4, 1.2, mA));\n      base = mix(base, vec3(0.85, 0.12, 0.6), smoothstep(1.2, 1.9, mA));\n      // 08's depth: a dark saturated core, light gathering to a pale rim, grain\n      vec4 o = cv_slicedOrb(pb - c, R, base * 0.12, base, mix(base, vec3(1.0, 0.9, 0.95), 0.6), t,\n                            smoothstep(0.4, 1.2, mA), smoothstep(1.7, 2.5, mA), qM, pushM, hk, smoothstep(2.1, 2.45, mA), px);\n      o.rgb += (cv_hash(vec3(uv * RENDERSIZE, floor(t * 12.0))) - 0.5) * 0.06 * o.a;\n      o *= wO * sphK;\n      col = col * (1.0 - o.a) + o.rgb;\n    }\n  }\n  // section 3's last frame exactly, drawn with its own code on its clock; gives way to the same lines drawn as this\n  // section's first bloom within half a minute\n  float wS3 = 1.0 - smoothstep(0.05, 0.45, mA);\n  if (wS3 > 0.001) col = mix(col, cv_s3end(p, t, px), wS3);\n\n  // the magenta bloom: the sphere's rippling ribbons carry on into it where the sphere was, fading in at nearly full size\n  // rather than bursting from a point\n  float ageM = (mA - 2.3) * 60.0;\n  if (ageM > 0.0 && mA < 7.5) {\n    cv_pal(8.0, cA, cB, cC);\n    float R = 0.34 * bloomSize * mix(0.85, 1.0, cv_unfurl(ageM, bloomTime * 2.0)) * surge;\n    float a = smoothstep(0.0, 30.0, ageM) * (1.0 - smoothstep(5.0, 7.0, mA));\n    if (a > 0.001) col = cv_lay(col, cv_bloom(pb - vec2(0.0, -0.04), R, 1.7, 1.0 + 1.5 * (1.0 - min(ageM / bloomTime, 1.0)), inkG, cA, cB, cC, t, px, 1.0, 0.0, 0.0), inkG, a);\n  }\n\n  // ------------------------------------------------ B-E. blooms landing on their own, every autoRate seconds\n  float T = autoRate;\n  float jNow = floor(tR / T);\n  float skip = floor(132.0 / T);                                        // count the palette from the first ink bloom\n  for (int i = 0; i < 6; i++) {\n    float j = jNow - 5.0 + float(i);                                     // oldest first, so newer ink lies over older\n    if (j < 0.0) continue;\n    // over the ground a drop is a cluster of blooms in staggered sizes, gone before the next drop lands\n    float inC = ARC_inC(j * T / 60.0);\n    float life = mix(min(4.0 * T, 480.0), 0.95 * T, inC);\n    float h1 = cv_hash(vec3(j, 11.0, 3.0));\n    float birth = (j + 0.35 * h1 * (1.0 - inC)) * T;\n    if (tR - birth < 0.0 || tR - birth > life) continue;\n    float bA = birth / 60.0;\n    if (cv_hash(vec3(j, 12.0, 5.0)) > ARC_drops(bA, W)) continue;\n    float after = step(W, bA);\n    for (int s = 0; s < 3; s++) {\n      float fs = float(s);\n      if (fs > 0.5 && inC < 0.5) break;\n      float age = tR - birth - fs * 5.0 * inC;\n      if (age < 0.0) continue;\n      float js = j + fs * 0.31;\n      float k = mod(j - skip + fs * 3.0, 8.0);\n      k = mix(k, mix(5.0, 8.0, floor(cv_hash(vec3(js, 18.0, 2.0)) * 3.99) / 3.0), inC);   // violet, pink, red, magenta\n      k = mix(k, mix(8.0, 9.0, step(0.5, cv_hash(vec3(j, 14.0, 2.0)))), after);\n      cv_pal(k, cA, cB, cC);\n      float dk = ARC_dark(mA, W) * after;                               // E: darker\n      cA *= 1.0 - 0.5 * dk; cB *= 1.0 - 0.45 * dk; cC *= 1.0 - 0.4 * dk;\n      vec2 c = vec2((cv_hash(vec3(js, 15.0, 1.0)) - 0.5) * 1.15, (cv_hash(vec3(js, 16.0, 1.0)) - 0.5) * 0.6);\n      // over the ground, a cluster's blooms each take their own third of the screen, never on top of each other\n      float third = mod(fs + floor(cv_hash(vec3(j, 19.0, 1.0)) * 2.99), 3.0);\n      vec2 cC3 = vec2(-0.6 + 0.6 * third + (cv_hash(vec3(js, 15.0, 1.0)) - 0.5) * 0.34,\n                      (cv_hash(vec3(js, 16.0, 1.0)) - 0.5) * 0.72);\n      c = mix(c, cC3, inC);\n      // drifts about and sinks\n      c += vec2(0.06 * sin(age * 0.011 + js * 2.3), 0.04 * sin(age * 0.009 + js * 1.7) - 0.00012 * age);\n      float size = mix(1.0, mix(0.3, 0.85, cv_hash(vec3(js, 20.0, 1.0))), inC);\n      float R = mix(0.24, 0.36, cv_hash(vec3(js, 17.0, 1.0))) * size * bloomSize * cv_unfurl(age, bloomTime) * surge;\n      float a = smoothstep(0.0, 1.5, age) * (1.0 - smoothstep(life * 0.5, life - fs * 5.0 * inC, age));\n      a *= 1.0 - ARC_clear(mA) * (1.0 - after);                         // the drop clears everything born before the return\n      a *= 1.0 - smoothstep(9.7, 9.95, mA) * (1.0 - after);             // nothing left over on the iridescent ground\n      a *= 1.0 - ARC_final(mA, W);                                      // gone as the dark red bloom gathers\n      if (a < 0.001) continue;\n      if (inC > 0.5) {                                                  // the clusters land into the bands\n        col = cv_into(col, g0, pb - c, R * 1.15, js * 1.37 + 0.5, t, cA, cB, cC, a);\n        continue;\n      }\n      // the ground rises out of the last blooms: they spread and soften in their own colours, then are gone into it\n      float melt = ARC_ground(mA) * (1.0 - after);\n      R *= 1.0 + 0.8 * melt;\n      a *= 1.0 - smoothstep(0.45, 0.95, melt);\n      if (a < 0.001) continue;\n      float swirl = 1.0 + 1.5 * (1.0 - min(age / bloomTime, 1.0));\n      float inkM = inkG * (1.0 - melt);                                 // melting, it adds light and never darkens the ground\n      col = cv_lay(col, cv_bloom(pb - c, R, js * 1.37 + 0.5, swirl, inkM, cA, cB, cC, t, px, 1.0, 0.5 * melt, 0.0), inkM, a);\n    }\n  }\n\n  // ------------------------------------------------ the interlude: back on the banded ground, in navy and teal, six blooms\n  // land 20 s apart in violet, pink, red and magenta, each in its own quarter of the screen, scattered in height and size\n  float ageI = (mA - INTERLUDE) * 60.0;\n  if (ageI > 0.0 && ageI < 200.0 && mA < D0 + 0.2) {\n    for (int i = 0; i < 6; i++) {\n      float fi = float(i);\n      float age = ageI - fi * 20.0;\n      if (age < 0.0 || age > 60.0) continue;\n      cv_pal(5.0 + floor(cv_hash(vec3(fi, 21.0, 4.0)) * 3.99), cA, cB, cC);\n      float quarter = mod(fi * 3.0, 4.0);\n      vec2 c = vec2(-0.72 + 0.48 * quarter + (cv_hash(vec3(fi, 22.0, 1.0)) - 0.5) * 0.1, (cv_hash(vec3(fi, 23.0, 1.0)) - 0.5) * 0.7);\n      c += vec2(0.05 * sin(age * 0.02 + fi * 2.0), 0.04 * sin(age * 0.017 + fi) - 0.00012 * age);\n      float R = mix(0.24, 0.36, cv_hash(vec3(fi, 24.0, 1.0))) * mix(0.35, 0.8, cv_hash(vec3(fi, 25.0, 1.0))) * bloomSize\n              * cv_unfurl(age, bloomTime) * surge;\n      float a = smoothstep(0.0, 1.5, age) * (1.0 - smoothstep(35.0, 60.0, age)) * (1.0 - ARC_clear(mA));\n      if (a < 0.001) continue;\n      col = cv_into(col, g0, pb - c, R * 1.15, 50.0 + fi * 1.37, t, cA, cB, cC, a);   // into the navy and teal bands\n    }\n  }\n\n  // ------------------------------------------------ the return, the big moment: every bloom comes back at once, on the beat\n  float ageR = (mA - W) * 60.0;\n  if (ageR > 0.0) {\n    for (int i = 0; i < 4; i++) {\n      float fi = float(i);\n      float age = ageR - fi * 0.4;\n      if (age < 0.0) continue;\n      cv_pal(mod(fi, 2.0) + 8.0, cA, cB, cC);\n      float dk = ARC_dark(mA, W);\n      cA *= 1.0 - 0.5 * dk; cB *= 1.0 - 0.45 * dk; cC *= 1.0 - 0.4 * dk;\n      vec2 c = vec2(-0.58 + 0.39 * fi + 0.06 * sin(fi * 3.7), 0.2 * sin(fi * 2.4 + 0.6));\n      c += vec2(0.13 * sin(age * 0.021 + fi * 2.0), 0.09 * sin(age * 0.017 + fi * 1.3 + 1.0));   // they wander about\n      float R = mix(0.26, 0.34, fract(fi * 0.618)) * bloomSize * cv_unfurl(age, bloomTime * 0.35) * surge;\n      float a = smoothstep(0.0, 0.3, age) * (1.0 - smoothstep(100.0, 160.0, age)) * (1.0 - ARC_final(mA, W));\n      if (a < 0.001) continue;\n      col = cv_lay(col, cv_bloom(pb - c, R, 20.0 + fi, 1.0 + 1.5 * (1.0 - min(age / bloomTime, 1.0)), inkG, cA, cB, cC, t, px, 1.0, 0.0, 0.0), inkG, a);\n    }\n  }\n\n  // ------------------------------------------------ E. the dark red bloom of undulating lines, holding to the handoff\n  float fin = ARC_final(mA, W);\n  if (fin > 0.001) {\n    cv_pal(10.0, cA, cB, cC);\n    cv_pal(13.0, dA, dB, dC);\n    float gp = smoothstep(0.0, 0.5, haze);                               // greys to purple first, then blurs\n    float bl = smoothstep(0.35, 1.0, haze);\n    float R = 0.35 * bloomSize * mix(0.3, 1.0, fin) * (1.0 + 0.03 * sin(t * 0.13)) * (1.0 + 0.5 * bl) * surge;\n    col = cv_lay(col, cv_bloom(pb, R, 31.0, 0.9 + 0.2 * sin(t * 0.021), 0.0, mix(cA, dA, gp), mix(cB, dB, gp), mix(cC, dC, gp),\n                               t, px, 1.0, 0.35 * bl, 0.0), 0.0, fin);\n  }\n\n  // ------------------------------------------------ Hit: a splash of colour, one bloom landing on the beat where the\n  // press throws it, for the last two presses; they unfurl fast and hang a while. Only where blooms are the look\n  // (Janet): 2:00 to the drop, and from 16:00 until the blooms fall back into lines. Elsewhere a press only punches.\n  for (int i = 0; i < 2; i++) {\n    float age = i == 0 ? hitPrevAge : hitAge;\n    if (age > 45.0) continue;\n    float tp = tR - age;\n    float pm = tp / 60.0;                                                 // when it was pressed, in minutes\n    bool early = pm >= 2.0 && pm < D0;\n    if (!early && !(pm >= 16.0 && pm < W + 0.5)) continue;\n    // they clear with the section's own blooms: at the drop, or as the dark red bloom gathers\n    float keep = early ? 1.0 - ARC_clear(mA) : 1.0 - ARC_final(mA, W);\n    float seed = floor(tp * 4.0 + 0.5);\n    cv_pal(5.0 + floor(cv_hash(vec3(seed, 31.0, 1.0)) * 3.99), cA, cB, cC);   // violet, pink, red, magenta\n    vec2 c = vec2((cv_hash(vec3(seed, 32.0, 1.0)) - 0.5) * 1.2, (cv_hash(vec3(seed, 33.0, 1.0)) - 0.5) * 0.55);\n    c += vec2(0.05 * sin(age * 0.02 + seed), -0.00012 * age);\n    float R = mix(0.22, 0.34, cv_hash(vec3(seed, 34.0, 1.0))) * bloomSize * cv_unfurl(age, 3.0);\n    float a = smoothstep(0.0, 0.1, age) * (1.0 - smoothstep(20.0, 45.0, age)) * keep;\n    float ink = max(inkG, 0.8);\n    if (intoK < 0.999)\n      col = cv_lay(col, cv_bloom(pb - c, R, 60.0 + seed * 1.37, 1.0 + 1.5 * (1.0 - min(age / 3.0, 1.0)), ink, cA, cB, cC,\n                                 t, px, 1.0, 0.0, 0.0), ink, a * (1.0 - intoK));\n    col = cv_into(col, g0, pb - c, R * 1.15, 60.0 + seed * 1.37, t, cA, cB, cC, a * intoK);   // over the ground, into it\n  }\n\n  // the bands' gaps and bright bars\n  if (bands > 0.001) {\n    float fy = fract(rowY);\n    float gs = 0.2 + 0.3 * haze;                                         // the gaps soften as it blurs\n    float gap = 1.0 - smoothstep(0.0, gs, fy) * (1.0 - smoothstep(1.0 - gs, 1.0, fy));\n    col *= 1.0 - bands * mix(0.9, 0.45, haze) * gap;\n    // a bright bar along the top edge of a few rows, only where there is colour to light up\n    float bar = step(0.8, cv_hash(vec3(row, floor(t / (3.0 + 3.0 * hr)), 7.0))) * cv_bump(fy, 0.2, 0.26, 0.34, 0.42);\n    float there = smoothstep(0.01, 0.08, max(col.r, max(col.g, col.b)));\n    col = mix(col, clamp(col * 4.0 + mix(vec3(0.25, 0.04, 0.12), vec3(0.12, 0.1, 0.16), smoothstep(0.0, 0.5, haze)) * there, 0.0, 1.0), bands * bar * (1.0 - haze));\n  }\n  // haze: angled grey-purple cloud drifting through, brighter toward the top, for section 5's line into depth\n  if (haze > 0.001) {\n    vec2 hq = pr * vec2(1.0, 2.6) + vec2(t * 0.004, 0.0);\n    float cloud = cv_fbm(vec3(hq * 1.3 + vec2(cv_fbm(vec3(hq * 0.8, t * 0.006)), 0.0), t * 0.008));\n    vec3 hazeCol = vec3(0.42, 0.38, 0.52) * smoothstep(0.3, 0.8, cloud) * (0.6 + 0.4 * smoothstep(-0.5, 0.5, p.y));\n    col = cv_screen(col, hazeCol * haze * 0.6);\n  }\n\n  col *= 1.0 + 0.2 * punch;\n  col = clamp(col, 0.0, 1.0);\n  col += (cv_hash(vec3(uv * RENDERSIZE, 1.0)) - 0.5) / 255.0;          // dither\n  gl_FragColor = vec4(col, 1.0);\n}\n","decl":"uniform float timeScale;uniform float speed;uniform float hitAge;uniform float hitPrevAge;","def":{"timeScale":1.0,"speed":1.0,"hitAge":100000.0,"hitPrevAge":100000.0},"len":1170.0},{"body":"\n\n\n// ---------------------------------------------------------------- fixed for the v2 review: only Speed and Hit are live\n// Speed 1 is the designed speed, 3.0; the slider is a multiple of it, so the operator never needs the number\nconst float SPEED_DESIGN = 3.0;\n#define motion (speed * SPEED_DESIGN)\nconst float echo = 1.0;\nconst float bokeh = 1.0;\nconst float palette = 1.88;\nconst float close = 0.0;\nconst float H = 20.0;                                                    // the hit, in the v1 arc's minutes (see cv_warp)\n\n// ---------------------------------------------------------------- helpers (hash, noise and fbm identical to section 4's)\nfloat cv_hash(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.yzx + 33.33);\n  return fract((p.x + p.y) * p.z);\n}\nfloat cv_noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(mix(cv_hash(i + vec3(0,0,0)), cv_hash(i + vec3(1,0,0)), f.x),\n        mix(cv_hash(i + vec3(0,1,0)), cv_hash(i + vec3(1,1,0)), f.x), f.y),\n    mix(mix(cv_hash(i + vec3(0,0,1)), cv_hash(i + vec3(1,0,1)), f.x),\n        mix(cv_hash(i + vec3(0,1,1)), cv_hash(i + vec3(1,1,1)), f.x), f.y), f.z);\n}\nfloat cv_fbm(vec3 p) {\n  return 0.5 * cv_noise(p) + 0.3 * cv_noise(p * 2.03 + 7.1) + 0.2 * cv_noise(p * 4.11 + 13.7);\n}\nfloat cv_bump(float x, float a, float b, float c, float d) {\n  return smoothstep(a, b, x) * (1.0 - smoothstep(c, d, x));\n}\nvec3 cv_hueShift(vec3 c, float h) {\n  vec3 k = vec3(0.57735);\n  float a = h * 6.2832;\n  return c * cos(a) + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - cos(a));\n}\nvec3 cv_screen(vec3 a, vec3 b) {\n  return vec3(1.0) - (vec3(1.0) - a) * (vec3(1.0) - b);\n}\nvec2 cv_rot(vec2 p, float a) {\n  float c = cos(a), s = sin(a);\n  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n// the integral of smoothstep(a, b, s) from a to x: a speed that eases up from a to b, as a distance travelled\nfloat cv_intSS(float x, float a, float b) {\n  float u = clamp((x - a) / (b - a), 0.0, 1.0);\n  return (b - a) * (u * u * u - 0.5 * u * u * u * u) + max(x - b, 0.0);\n}\n// v2 timing: real minutes to the v1 arc's minutes, which every ARC_ below is written in. The run to the rays stretches\n// a little (0-19:30 plays v1's 0-18:26).\n// v2 round 2 (James): one tunnel, hitting just after 1:41 in the set. The black and the dotted tunnel are gone; from\n// 19:30 the sparkles stream into angled rays (ref 33) that become the mirror ball, which arrives at 21:05 (the v1 arc's\n// H + 1.7). Over 19:30-21:05 the arc runs through the v1 span it no longer shows (its black and dotted tunnel), its\n// rate easing up and back so the travel never jumps: the rays rush a little as they close in. From the ball on it runs\n// at v28's pace (Jen: the slower ball felt wrong), so this clock ends past 30; cv_hold takes the difference back\n// once the ball is fully open, so it holds 6.6 minutes (was 5) and shatters at ~27:40, the rest ending at 33:30\nfloat cv_warp(float M) {\n  float r0 = 20.0 / 21.15;                                              // v1 minutes per minute, up to the rays\n  float r2 = 8.3 / 10.65;                                               // v28's pace, from the ball on\n  if (M < 19.5) return M * r0;\n  if (M < 21.08) {\n    float L = 1.58, u = (M - 19.5) / L;\n    float A = ((21.7 - 19.5 * r0) / L - 0.5 * (r0 + r2)) * 1.5708;\n    return 19.5 * r0 + L * (r0 * u + (r2 - r0) * (u * u * u - 0.5 * u * u * u * u) + A * (1.0 - cos(3.14159 * u)) / 3.14159);\n  }\n  return 21.7 + r2 * (M - 21.08);\n}\n// how far the ball's hold sets everything after it back, in v1 minutes: taken up while the ball is fully open, where\n// nothing on the arc changes, so the ball keeps moving at full pace and only what follows it comes later\nfloat cv_hold(float m) {\n  return (21.7 + 8.3 / 10.65 * 12.42 - 30.0) * smoothstep(23.0, 24.6, m);\n}\n// v3 (James extended the set; the sections autopilot back to back, the whole set 2:00:00): 43.5 minutes, 1:16:30 to\n// 2:00:00 in the set. Real minutes (mN) map onto v2's real minutes (the old clock every timing below was written in):\n// 0-1:30 unchanged (section 4's seam), 1:30-24:30 plays v2's 1:30-21:05 a little slower so the mirror ball arrives at\n// 24:30 (1:41:00 in the set), the ball's arrival and hold keep their pace (James: the tunnel 5-6 minutes), then the\n// clock stands at v2's 26:05 (the ball fully open, before it would shatter) through the reprise, R0 to R1, and runs\n// v2's 28:00 to 33:30 (the bokeh rising, the landing) a little faster to the end\nconst float R0 = 29.5;                                                   // the reprise starts: the ball sinks back (1:46:00)\nconst float R1 = 40.5;                                                   // the reprise ends: the veils break into bokeh (1:57:00)\nconst float SONG2 = 6.5;                                                 // minutes into the reprise: ribbons to veils (1:52:30)\nfloat cv_old(float mN) {\n  if (mN < 1.5) return mN;\n  if (mN < 24.5) return 1.5 + (mN - 1.5) * (19.58333 / 23.0);\n  if (mN < R0) return mN - 3.41667;\n  if (mN < R1) return R0 - 3.41667;\n  return 28.0 + (mN - R1) * (5.5 / 3.0);\n}\n// the reprise's light, in the v1 arc's minutes: song 1 the soft ribbons (12.4 drifting to 13.2), song 2 they untwist into\n// curtains and the veils lean in (to 10.3), drifting on toward 9.6. The section's own transitions, played back\nfloat cv_repArc(float u) {\n  return 12.4 + 0.8 * smoothstep(0.0, SONG2, u) - 2.9 * smoothstep(SONG2, SONG2 + 2.2, u) - 0.7 * smoothstep(SONG2 + 2.2, R1 - R0, u);\n}\n// the reprise's travel, in minutes at pace 1: the ball's pace at first, easing to a slow wind-down drift\nfloat cv_repTravel(float u) { return 1.2 * u - 0.6 * cv_intSS(u, 1.0, 4.0); }\n\n// integral of a linear ramp from 0 at a to 1 at b, so speed can change along the arc without the position jumping\nfloat cv_rampInt(float x, float a, float b) {\n  if (x < a) return 0.0;\n  if (x < b) return (x - a) * (x - a) / (2.0 * (b - a));\n  return x - 0.5 * (a + b);\n}\n// distance from p to the segment a-b, and how far along it\nvec2 cv_seg(vec2 p, vec2 a, vec2 b) {\n  vec2 ab = b - a;\n  float h = clamp(dot(p - a, ab) / max(dot(ab, ab), 0.000001), 0.0, 1.0);\n  return vec2(length(p - a - ab * h), h);\n}\n\n// ---------------------------------------------------------------- arc\n// Minutes. H is the hit (Hit At). Sliders multiply on top of these.\nfloat ARC_s4(float m)      { return 1.0 - smoothstep(0.1, 0.9, m); }          // A. section 4's bands let go\nfloat ARC_recede(float m)  { return smoothstep(0.1, 1.1, m); }               //    its bloom recedes to a point\nfloat ARC_haze4(float m)   { return 1.0 - smoothstep(0.6, 1.6, m); }          //    its haze gives way to light\nfloat ARC_flare(float m)   { return cv_bump(m, 0.5, 1.0, 1.2, 1.6); }         // B. a spectral flare opens at the haze's angle, gone before the curves\nfloat ARC_core(float m)    { return cv_bump(m, 0.7, 1.5, 17.5, 19.5); }       //    the bright point everything flows into\nfloat ARC_streams(float m) { return cv_bump(m, 1.45, 1.9, 2.7, 3.3); }         //    a bundle of streams bending into it from the right\nfloat ARC_streamsL(float m){ return cv_bump(m, 1.9, 2.4, 3.0, 3.6); }         //    a second bundle from the left: wings, then the left alone\nfloat ARC_planes(float m)  { return cv_bump(m, 7.8, 8.8, 10.6, 11.5); }         //    veils of light lean in from both sides, receding to the point\nfloat ARC_open(float m)    { return mix(0.35, 0.1, smoothstep(7.8, 9.4, m)); } //   how far apart the veils still are\nfloat ARC_aurora(float m)  { return cv_bump(m, 3.4, 4.1, 11.5, 12.1); }       //    curtains of light rising through the point\nfloat ARC_ribbons(float m) { return cv_bump(m, 11.3, 12.0, 17.0, 18.8); }     //    soft ribbons of pink, cyan and violet\nfloat ARC_rings(float m, float H) { return cv_bump(m, 1.6, 2.4, H - 0.6, H - 0.1); }  //    the dub pulse in the light, all the way to the hit\nfloat ARC_halo(float m)    { return cv_bump(m, 13.4, 14.3, 16.9, 17.1); }     //    sparks of saturated colour orbit the point in the ribbons\nfloat ARC_haloGrow(float m){ return smoothstep(16.0, 17.0, m); }             //    and widens past the viewer as the sparkles build\nfloat ARC_twist(float m)   { return smoothstep(11.1, 11.9, m); }              //    the curtains twist round the point into them\nfloat ARC_lower(float m)   { return cv_bump(m, 3.4, 4.4, 5.4, 6.4); }       //    the point sinks so the curtains fill the frame, then comes back\nfloat ARC_both(float m)    { return smoothstep(5.4, 6.4, m); }             //    and curtains hang below it too, a full field of columns\nfloat ARC_glint(float m, float H) { return 0.4 * cv_bump(m, 3.6, 5.5, H - 3.5, H - 2.5) + cv_bump(m, H - 4.0, H - 2.5, H + 1.2, H + 2.2) * (1.0 + 0.5 * cv_bump(m, H - 1.0, H - 0.3, H + 0.5, H + 1.2)); } // C. sparkles build to the hit\nfloat ARC_discoGlint(float m, float H) { return 0.8 * cv_bump(m, H + 1.8, H + 2.6, H + 5.4, H + 6.0); } // sparkles inside the mirror ball\nfloat ARC_sparks(float m, float H) { return 0.18 + 0.5 * smoothstep(H - 3.5, H, m); }  //    more and more of them\n// the camera banks as it goes in: from the haze's angle, swinging slowly the other way\nfloat ARC_roll(float m, float t) { return 0.32 * (1.0 - smoothstep(1.6, 2.4, m)); } // the haze's angle through the flare, then level\n// after the hit: back into the sparkles, which turn to the dotted tunnel and then the mirror ball; it shatters into bokeh\nfloat ARC_tunnel(float m, float H) { return smoothstep(H + 0.25, H + 1.0, m) * (1.0 - smoothstep(H + 6.0, H + 6.8, m)); }\nfloat ARC_echo(float m)    { return smoothstep(1.5, 3.0, m) * (1.0 - 0.5 * smoothstep(26.0, 30.0, m)); } // dub echoes\nfloat ARC_disco(float m, float H) { return smoothstep(H + 1.7, H + 2.7, m); } // D. the mirror ball\nfloat ARC_shatter(float m, float H) { return smoothstep(H + 5.5, H + 6.15, m); } //    breaks apart and drifts\nfloat ARC_bokeh(float m, float H) { return smoothstep(H + 5.9, H + 6.8, m) * (1.0 - 0.45 * smoothstep(27.5, 30.0, m)); } // E. into bokeh\nfloat ARC_bright(float m, float H) { return 1.0 + 0.25 * cv_bump(m, H + 0.3, H + 0.8, H + 3.0, H + 6.0); }\nfloat ARC_end(float m)     { return 1.0 - smoothstep(29.0, 30.0, m); }        //    the last minute fades to black, and stays there\nfloat ARC_dim(float m)     { return 1.0 - 0.3 * smoothstep(27.0, 30.0, m); }  //    winding down\n// palette key: 0 the haze, 1 the light, 2 sparkles and disco, 3 the shatter and bokeh, 4 the landing\n// warm is the Hit's warmth (James): the light turning hot pink and orange on the beat, in place of a slow drift\nfloat ARC_key(float m, float H, float warm) {\n  return smoothstep(0.6, 2.0, m) + warm + smoothstep(H + 6.0, H + 8.0, m) + smoothstep(H + 8.0, 29.5, m);\n}\n// travel, in minutes at pace 1: still on the haze, flowing inward through the light, a little faster in the disco,\n// slower as it shatters, nearly still at the landing\nfloat ARC_travel(float m, float H) {\n  return 0.05 * m + 0.95 * cv_rampInt(m, 0.4, 1.8) + 0.2 * cv_rampInt(m, H + 0.5, H + 2.0)\n       - 0.4 * cv_rampInt(m, H + 6.0, H + 8.0) - 0.55 * cv_rampInt(m, H + 8.0, 29.5);\n}\n\n// ---------------------------------------------------------------- palettes\n// deep (ground, fog, cloud), light 1 (main), light 2 (accent), per set and key.\n// set 0 late disco: gold, rose, violet, blue. set 1 dub: jade, brass, teal, sea blue. set 2 dawn: peach, lilac, pink, powder blue\nvoid cv_key(float s, float k, out vec3 d, out vec3 a, out vec3 b) {\n  d = vec3(0.14, 0.12, 0.19); a = vec3(0.95, 0.9, 1.0); b = vec3(0.74, 0.69, 0.84);     // key 0 shared: section 4's grey purple\n  if (s < 0.5) {\n    if (k > 0.5) { d = vec3(0.01, 0.015, 0.04); a = vec3(1.0, 0.5, 0.18); b = vec3(0.2, 0.55, 1.0); }  // amber, sky blue\n    if (k > 1.5) { d = vec3(0.08, 0.04, 0.12); a = vec3(1.0, 0.52, 0.62); b = vec3(0.45, 0.85, 1.0); }  // rose, cyan\n    if (k > 2.5) { d = vec3(0.07, 0.03, 0.17); a = vec3(0.72, 0.5, 1.0);  b = vec3(1.0, 0.6, 0.85); }   // violet, pink\n    if (k > 3.5) { d = vec3(0.02, 0.03, 0.12); a = vec3(0.38, 0.52, 1.0); b = vec3(1.0, 0.76, 0.52); }  // blue, warm peach\n  } else if (s < 1.5) {\n    if (k > 0.5) { d = vec3(0.01, 0.03, 0.03); a = vec3(1.0, 0.72, 0.3); b = vec3(0.2, 0.9, 0.75); }   // brass, jade\n    if (k > 1.5) { d = vec3(0.02, 0.06, 0.08); a = vec3(0.2, 0.9, 0.85);  b = vec3(1.0, 0.5, 0.3); }   // teal, orange\n    if (k > 2.5) { d = vec3(0.04, 0.03, 0.1);  a = vec3(0.55, 0.6, 1.0);  b = vec3(0.4, 1.0, 0.75); }  // periwinkle, mint\n    if (k > 3.5) { d = vec3(0.01, 0.03, 0.07); a = vec3(0.25, 0.55, 0.85); b = vec3(0.9, 0.85, 0.55); } // sea blue, pale gold\n  } else {\n    if (k > 0.5) { d = vec3(0.03, 0.02, 0.06); a = vec3(1.0, 0.5, 0.65); b = vec3(0.55, 0.6, 1.0); }  // pink, periwinkle\n    if (k > 1.5) { d = vec3(0.1, 0.03, 0.13);  a = vec3(1.0, 0.3, 0.62);  b = vec3(1.0, 0.55, 0.15); }  // hot pink, hot orange\n    if (k > 2.5) { d = vec3(0.06, 0.04, 0.16); a = vec3(1.0, 0.45, 0.35); b = vec3(0.7, 0.4, 1.0); }   // coral, violet\n    if (k > 3.5) { d = vec3(0.05, 0.06, 0.14); a = vec3(0.7, 0.75, 1.0);  b = vec3(1.0, 0.82, 0.7); }  // pale blue, dawn\n  }\n}\nvoid cv_palette(float s, float k, out vec3 d, out vec3 a, out vec3 b) {\n  vec3 d0, a0, b0, d1, a1, b1, d2, a2, b2, d3, a3, b3;\n  float s0 = floor(s), k0 = floor(k);\n  float fs = s - s0, fk = k - k0;\n  cv_key(s0, k0, d0, a0, b0);\n  cv_key(s0, k0 + 1.0, d1, a1, b1);\n  cv_key(s0 + 1.0, k0, d2, a2, b2);\n  cv_key(s0 + 1.0, k0 + 1.0, d3, a3, b3);\n  d = mix(mix(d0, d1, fk), mix(d2, d3, fk), fs);\n  a = mix(mix(a0, a1, fk), mix(a2, a3, fk), fs);\n  b = mix(mix(b0, b1, fk), mix(b2, b3, fk), fs);\n}\n\n// ---------------------------------------------------------------- section 4's end, on section 4's clock\n// Section 4's line field and bloom as they draw its closing bloom (no ink, ragged), copied unchanged\nfloat cv_s4LineField(vec2 q, float t, float freq, float speed, float wobble, float px, float blur) {\n  float y = q.y + wobble * 0.012 * sin(q.x * 18.0 + t * 1.6 + floor(q.y * freq) * 0.7);\n  float f = fract(y * freq - t * speed);\n  float w = px * freq * 1.2 + blur * 0.3;\n  float l = smoothstep(0.1 - w, 0.1 + w, f) * (1.0 - smoothstep(0.55 - w, 0.55 + w, f));\n  return mix(l, 0.45, smoothstep(0.1, 0.35, blur));\n}\n// section 4 v2's closing bloom of lines (its cv_bloom with no ink): the lines bent by a slow flowing height field\nvec4 cv_s4Bloom(vec2 q, float R, float seed, float swirl, vec3 cB, vec3 cC, float t, float px, float blur) {\n  vec2 u = q / max(R, 0.001);\n  float r = length(u);\n  if (r > 2.3) return vec4(0.0);\n  vec2 dir = u / max(r, 0.0001);\n  float tt = t * 0.035 + seed * 7.0;\n  float ragged = max(swirl, 1.0);\n  float rim = 1.0 + 0.1 * ragged * (cv_fbm(vec3(dir * 2.2 + seed, tt * 0.9)) - 0.5) * 2.0;\n  float soft = mix(px / max(R, 0.001), 0.14, min(ragged, 1.0)) + 0.45 * blur;\n  float mask = 1.0 - smoothstep(rim - soft, rim + soft * 0.2, r);\n  if (mask <= 0.0) return vec4(0.0);\n  vec2 us = u + 0.45 * min(swirl, 1.6) * (vec2(cv_fbm(vec3(u * 1.3, tt)), cv_fbm(vec3(u * 1.3 + 5.0, tt))) - 0.5);\n  float sw = 0.5 + 1.1 * (cv_fbm(vec3(us * 1.1 + seed * 3.1, tt)) - 0.5);\n  float ridge = 1.0 - abs(2.0 * sw - 1.0);\n  float push = R * 0.06 * min(swirl, 1.6) * (sw - 0.5) * 2.0;\n  float ln = cv_s4LineField(vec2(q.x, q.y + push), t, 60.0, 0.15, 1.0, px, blur);\n  float lum = ln * mask * mix(1.0, 0.25 + 0.95 * ridge * ridge, min(swirl, 1.0));\n  return vec4(mix(cB, cC, ridge * ridge) * lum, lum);\n}\n\n// ---------------------------------------------------------------- B. the dots along the lines (v28's dotted tunnel, only its sparkling end)\n// Jen: what worked in the old arrival was the sparkles riding the rays, echoing the ball's tiles. On the ball's own\n// forty spokes now, so they sit on the lines\n// Dots along spokes that recede to the vanishing point. q is screen position from it, z the travel, fill 0 lights\n// every fourth spoke and steps the dots, fill 1 lights them all. Returns light.\nvec3 cv_dots(vec2 q, float r, float angS, float z, float fill, vec3 cA, vec3 cB, float px, float t, float shapes, float spark) {\n  float N = 40.0;\n  float s = angS / 6.2832 * N;\n  float zz = z * 10.0;\n  float idS = floor(s), idZ = floor(zz);\n  vec2 cell = vec2(fract(s) - 0.5, fract(zz) - 0.5);\n  float wS = r * 6.2832 / N;                                           // screen size of one step round\n  float wZ = r * r / 0.18 * 0.1;                                       // and one step in depth\n  float rad = 0.22 * min(wS, wZ);\n  float soft = max(px * 1.2, rad * 0.9 * smoothstep(0.35, 0.95, r));   // nearer is out of focus\n  vec2 lp = vec2(cell.x * wS, cell.y * wZ);\n  float dist = length(lp);\n  if (shapes > 0.001) {\n    // each spoke repeats one shape down its length: four-point stars, diamonds, moons, and some stay dots\n    float kind = floor(cv_hash(vec3(idS, 12.0, 4.0)) * 4.0);\n    float R2 = rad * 1.9;\n    vec2 al = abs(lp);\n    float sd = dist;\n    if (kind < 0.5) sd = pow(pow(al.x, 0.55) + pow(al.y, 0.55), 1.0 / 0.55) * 0.5;\n    else if (kind < 1.5) sd = (al.x * 1.25 + al.y * 0.8) * 0.72;          // diamonds\n    else if (kind < 2.5) sd = max(dist, R2 * 1.05 - length(lp - vec2(R2 * 0.45, 0.0)) * 1.15);\n    dist = mix(dist, sd * rad / R2, shapes);\n  }\n  rad *= 1.0 - 0.65 * spark;                                           // turning to sparkles as the mirror ball comes\n  float dotL = 1.0 - smoothstep(rad - soft, rad + soft, dist);\n  float line = 0.18 * (1.0 - smoothstep(0.0, px * 1.2 + soft * 0.4, abs(cell.x * wS) - 0.1 * rad));\n  // too small to draw: the average brightness\n  float avg = 3.1416 * rad * rad / max(wS * wZ, 0.000001) + 0.18 * 0.2 * rad / max(wS, 0.000001);\n  float lum = mix(avg, dotL + line, smoothstep(2.0 * px, 5.0 * px, wS));\n  float on = mix(step(mod(idS, 4.0), 0.5), 1.0, fill);\n  float seq = mix(0.3 + 0.7 * step(mod(idZ, 4.0), 0.5), 1.0, fill);\n  float h = cv_hash(vec3(idS, idZ, 3.0));\n  float tw = 0.65 + 0.35 * sin(t * 0.2 + h * 40.0);\n  tw = mix(tw, 2.2 * pow(smoothstep(0.5, 1.0, 0.5 + 0.5 * sin(t * 0.9 + h * 50.0)), 2.0), spark);\n  line *= 1.0 - spark;\n  vec3 c = mix(cA, cB, step(0.72, h));\n  return c * lum * on * seq * tw;\n}\n\n// ---------------------------------------------------------------- C. the inside of a mirror ball\n// sh 0 is the whole ball; sh 1 its lit tiles broken free, drifting and turning, softening toward bokeh\nvec3 cv_tiles(vec2 q, float r, float angS, float z, vec3 cD, vec3 cA, vec3 cB, float px, float t, float sh) {\n  float N = 40.0;\n  float s = angS / 6.2832 * N;\n  float zz = (z - 0.18 / r) * 1.2 - log(r) * N / 6.2832;                 // log depth: tiles stay square all the way in\n  float idS = floor(s), idZ = floor(zz);\n  vec2 cell = vec2(fract(s) - 0.5, fract(zz) - 0.5);\n  float wS = r * 6.2832 / N;\n  float wZ = wS;\n  float edge = min((0.5 - abs(cell.x)) * wS, (0.5 - abs(cell.y)) * wZ); // distance to the tile's edge on screen\n  float soft = px * 1.2 + 0.008 * smoothstep(0.4, 1.0, r);\n  float grout = smoothstep(0.1 * min(wS, wZ), 0.1 * min(wS, wZ) + soft, edge);\n  float h = cv_hash(vec3(idS, idZ, 9.0));\n  // the dim mirror surface, catching the colour of the room\n  float sheen = cv_noise(vec3(idS * 0.23, idZ * 0.23, t * 0.02)) * (0.5 + 0.5 * h);\n  vec3 surf = cD * (0.3 + 1.2 * sheen * sheen) + mix(cA, cB, cv_noise(vec3(idS * 0.1, idZ * 0.1 + 5.0, t * 0.015))) * 0.05;\n  // lit patches drift round the walls like light off a mirror ball\n  float drift = cv_noise(vec3(idS * 0.22 + t * 0.03, idZ * 0.22, t * 0.02));\n  float lit = smoothstep(0.5, 0.75, drift) * step(0.7, h) * (0.5 + 0.5 * cv_hash(vec3(idS, idZ, 5.0)));\n  float glow = smoothstep(0.1 * min(wS, wZ), 0.35 * min(wS, wZ), edge);\n  vec3 lc = mix(cA, cB, step(0.5, cv_hash(vec3(idS, idZ, 4.0))));\n  vec3 spill = mix(cA, cB, 0.5) * 0.12 * smoothstep(0.35, 0.8, drift);    // light off the lit tiles on their neighbours\n  lc = mix(lc, vec3(0.15, 0.3, 1.0), 0.8 * smoothstep(0.24 * wS, 0.46 * wS, edge));   // airbrushed: a blue heart inside a hot rim\n  vec3 c = (surf + spill) * grout * (1.0 - sh) + lc * lit * mix(0.35, 1.5, glow) * grout * (1.0 - smoothstep(0.0, 0.25, sh));\n  if (sh > 0.001) {\n    // the pieces: each lit tile and its neighbours, pushed off their places, turned, shrinking and blurring\n    for (int i = -1; i < 2; i++) {\n      for (int j = -1; j < 2; j++) {\n        vec2 id = vec2(idS + float(i), idZ + float(j));\n        float hh = cv_hash(vec3(id, 9.0));\n        if (hh < 0.7 - 0.25 * sh) continue;\n        float dr = cv_noise(vec3(id.x * 0.22 + t * 0.03, id.y * 0.22, t * 0.02));\n        float on = smoothstep(0.4, 0.7, dr) * (0.5 + 0.5 * cv_hash(vec3(id, 5.0)));\n        if (on < 0.01) continue;\n        vec2 push = (vec2(cv_hash(vec3(id, 31.0)), cv_hash(vec3(id, 32.0))) - 0.5) * 1.9 * sh;\n        vec2 lp = vec2(s, zz) - (id + 0.5 + push);\n        lp = cv_rot(lp * vec2(wS, wZ), sh * (cv_hash(vec3(id, 33.0)) - 0.5) * 4.0);\n        float hs = 0.4 * wS * (1.0 - 0.35 * sh);\n        float blur = soft + 0.35 * hs * sh;\n        float sq = max(abs(lp.x), abs(lp.y));\n        float disc = length(lp);\n        float shape = 1.0 - smoothstep(hs - blur, hs + blur, mix(sq, disc * 1.15, smoothstep(0.4, 1.0, sh)));\n        // each piece catches the light like a cut stone: one facet bright, one deep, until it blurs to bokeh\n        vec3 pc = mix(cA, cB, step(0.5, cv_hash(vec3(id, 4.0))));\n        float facet = smoothstep(-0.1 * hs, 0.1 * hs, lp.x * 0.8 + lp.y * 0.6);\n        vec3 gem = mix(mix(cD * 3.0, vec3(0.2, 0.25, 1.0), 0.6), mix(pc, vec3(1.0), 0.25), facet);\n        pc = mix(pc, gem, cv_bump(sh, 0.05, 0.3, 0.6, 0.95));\n        c += pc * on * shape * smoothstep(0.0, 0.25, sh) * 1.2;\n      }\n    }\n  }\n  // the near tiles blur toward the edge of frame\n  return c * smoothstep(1.5 * px, 5.0 * px, min(wS, wZ));\n}\n\n// ---------------------------------------------------------------- D. bokeh\n// five layers of soft discs moving toward the viewer, small and many far away, large and soft close up\nvec3 cv_bokeh(vec2 p, float trav, vec3 cA, vec3 cB, vec3 cD, float dens, float px, float t) {\n  vec3 acc = vec3(0.0);\n  for (int i = 0; i < 5; i++) {\n    float fi = float(i);\n    float ph = fract(trav + fi / 5.0);\n    float zoom = pow(9.0, ph);\n    float cs = 0.09 * zoom;                                             // cell size on screen\n    vec2 uvB = p / cs + vec2(fi * 13.1, fi * 7.7) + vec2(0.3 * sin(t * 0.013 + fi), 0.2 * sin(t * 0.011 + fi * 2.0));\n    vec2 id = floor(uvB);\n    vec2 f = fract(uvB) - 0.5;\n    float h = cv_hash(vec3(id, fi + 20.0));\n    if (h > dens) continue;\n    vec2 off = vec2(cv_hash(vec3(id, fi + 30.0)), cv_hash(vec3(id, fi + 40.0))) - 0.5;\n    float rad = 0.12 + 0.14 * cv_hash(vec3(id, fi + 50.0));\n    float dist = length(f - off * 0.45);\n    float soft = px / cs * 1.5 + mix(0.015, 0.09, ph);\n    float disc = 1.0 - smoothstep(rad - soft, rad + soft, dist);\n    float rim = smoothstep(rad - 3.0 * soft, rad, dist) * disc;\n    float a = smoothstep(0.0, 0.3, ph) * (1.0 - smoothstep(0.7, 1.0, ph));\n    float breathe = 0.6 + 0.4 * sin(t * 0.08 + h * 60.0);\n    float hc = cv_hash(vec3(id, fi + 60.0));\n    vec3 c = mix(cA, cB, step(0.55, hc));\n    c = mix(c, cD * 4.0 + 0.1, step(0.9, hc));\n    vec3 heart = mix(c, vec3(0.25, 0.45, 1.0), 0.7 * (1.0 - smoothstep(0.0, rad * 0.75, dist)));   // blue at heart, the colour at the rim\n    acc += (heart * 0.5 * disc + c * 0.3 * rim) * a * breathe;\n  }\n  return acc;\n}\n\n// ---------------------------------------------------------------- B. the light\n// q is screen position from the vanishing point, turned so the horizon runs along x. cA warm, cB blue.\n// a spectral flare: a horizontal band, warm to the left, white at the point, blue to the right, with soft\n// chromatic columns standing through it\nvec3 cv_flare(vec2 q, float t, vec3 cA, vec3 cB) {\n  float band = exp(-abs(q.y) / (0.01 + 0.06 * abs(q.x))) * exp(-abs(q.x) / 0.8);\n  // the domes' colours: hot orange and pink to the left, their blue to the right\n  vec3 c = mix(mix(vec3(1.0, 0.5, 0.12), vec3(1.0, 0.4, 0.6), smoothstep(-0.7, -0.1, q.x)), vec3(0.15, 0.35, 1.0), smoothstep(-0.3, 0.35, q.x));\n  c = mix(c, vec3(1.0), exp(-abs(q.x) / 0.07));\n  vec3 acc = c * band * 0.9;\n  for (int k = 0; k < 6; k++) {\n    float fk = float(k);\n    float xk = (cv_hash(vec3(fk, 80.0, 1.0)) - 0.5) * 0.9 + 0.03 * sin(t * 0.02 + fk * 1.7);\n    float w = 0.008 + 0.03 * cv_hash(vec3(fk, 81.0, 1.0));\n    float hk = cv_hash(vec3(fk, 82.0, 1.0));\n    vec3 hue = hk < 0.25 ? vec3(1.0, 0.5, 0.78) : (hk < 0.5 ? vec3(1.0, 0.5, 0.12) : (hk < 0.75 ? vec3(1.0, 0.33, 0.22) : vec3(0.15, 0.35, 1.0)));\n    float h = 0.2 + 0.35 * cv_hash(vec3(fk, 83.0, 1.0));\n    acc += mix(hue, c, 0.3) * exp(-abs(q.x - xk) / w) * exp(-abs(q.y) / h) * 0.18;\n  }\n  return acc;\n}\n// a bundle of streams bending into the point from the right: far apart at the edge of frame, drawing together and\n// running into the point along one direction, the whole bundle swaying. Warm low, blue high, pulses flowing in.\n// No horizon and no floor: only the light\nvec3 cv_streams(vec2 q, float t, float fly, vec3 cA, vec3 cB, float sweep) {\n  float ax = max(q.x, 0.0001);\n  float curl = -0.05 + 0.2 * sin(t * 0.05 + sweep);                        // the bundle sways up and down\n  float c = (q.y - curl * ax) / (ax * ax + 0.02 * ax) * 0.8;              // which stream: y = curl x + c x^2, all arriving along one line\n  float s1 = cv_noise(vec3(c * 8.0, 0.0, t * 0.07));\n  float s2 = cv_noise(vec3(c * 26.0, 5.0, t * 0.09));\n  float s3 = cv_noise(vec3(c * 2.5, 9.0, t * 0.04));\n  float fine = smoothstep(0.03, 0.2, ax);                                // too close to the point to draw the fine ones\n  float s4 = cv_noise(vec3(c * 70.0, 2.0, t * 0.11));\n  // wisps: mostly fine strands over a faint breath of colour, each fading in and out along its length\n  float along = log(ax) * 1.6 + fly * 0.5;\n  float wisp = smoothstep(0.25, 0.75, cv_noise(vec3(c * 5.0, along, t * 0.05)));\n  float lines = (pow(s1, 4.0) * 0.55 + pow(s2, 5.0) * 1.0 * fine + pow(s4, 7.0) * 1.2 * fine) * (0.25 + 0.75 * wisp) + s3 * s3 * 0.14;\n  float wedge = smoothstep(-0.9, 0.0, c) * (1.0 - smoothstep(0.9, 2.4, c));\n  float flow = 0.6 + 0.4 * sin(log(ax) * 6.0 + fly * 3.5 + s1 * 6.0);    // pulses of light run in along them\n  float fade = smoothstep(0.0, 0.06, q.x) * (0.45 + 0.75 * exp(-ax / 0.4));\n  vec3 col = mix(cA, cB, smoothstep(0.0, 0.8, c + 0.9 * sin(t * 0.04)));\n  float vio = cv_bump(fract(c * 0.5 - t * 0.02), 0.0, 0.2, 0.35, 0.55);   // a band of violet travels across them\n  col = mix(col, vec3(0.62, 0.35, 1.0), 0.6 * vio);\n  // the colours keep changing while they are on screen: cyan and gold pass through, the warm and blue trade places\n  col = mix(col, vec3(0.35, 0.95, 0.9), 0.55 * cv_bump(fract(c * 0.35 + t * 0.017 + 0.5), 0.0, 0.2, 0.35, 0.55));\n  col = mix(col, vec3(1.0, 0.8, 0.4), 0.5 * cv_bump(fract(c * 0.3 - t * 0.013 + 0.2), 0.0, 0.15, 0.3, 0.45));\n  col = mix(col, vec3(1.0), 0.4 * exp(-ax / 0.1));\n  // where they arrive, a soft glow carries a little way on past the point\n  float past = exp(-length(q * vec2(1.0, 4.0)) / 0.16) * 0.3;\n  return col * lines * wedge * flow * fade * 1.35 + mix(cA, vec3(1.0), 0.5) * past;\n}\n// a horizon of light with curtains rising from it, warm in the middle and blue at the sides, shimmering upward,\n// and a faint reflection below\nvec3 cv_aurora(vec2 q, float t, vec3 cA, vec3 cB, float twist, float both) {\n  float rq = length(q);\n  q = cv_rot(q, twist * 2.2 * exp(-rq * 1.5));                          // twisting round the point as they go\n  float y = q.y;                                                        // rising through the point itself, no second line\n  float x = q.x;\n  float n1 = cv_noise(vec3(x * 16.0 - t * 0.03, t * 0.06, 1.0));\n  float n2 = cv_noise(vec3(x * 50.0, t * 0.09, 3.0));\n  float n3 = cv_noise(vec3(x * 3.5 - t * 0.02, t * 0.025, 7.0));\n  float streak = pow(n1, 3.0) * 0.8 + pow(n2, 6.0) * 0.7;\n  float Hh = 0.08 + 0.7 * n3 * n3;\n  float shimmer = 0.55 + 0.45 * cv_noise(vec3(x * 30.0, y * 3.0 - t * 0.12, 2.0));\n  float up = smoothstep(-0.06, 0.04, y) * exp(-max(y, 0.0) / Hh) * shimmer;\n  float base = exp(-abs(y) / 0.05) * (0.1 + 0.25 * n3) * streak;          // a soft glow at their foot, not a line\n  float refl = (1.0 - smoothstep(-0.06, 0.04, y)) * exp(min(y, 0.0) / 0.08) * 0.12 * streak;\n  if (both > 0.001) {                                                   // the same columns carry on down below: no seam\n    float Hd = 0.08 + 0.7 * pow(cv_noise(vec3(x * 3.0 + t * 0.02, t * 0.025, 11.0)), 2.0);\n    float sh2 = 0.55 + 0.45 * cv_noise(vec3(x * 30.0, y * 3.0 + t * 0.12, 2.0));\n    refl = mix(refl, streak * (1.0 - smoothstep(-0.06, 0.04, y)) * exp(min(y, 0.0) / Hd) * sh2, both);\n    base *= 1.0 - both;\n  }\n  float xs = x - 0.45 * sin(t * 0.01);                                  // the warm middle wanders\n  vec3 c = mix(cB, cA, cv_bump(xs, -0.7, -0.15, 0.25, 0.8));\n  c = mix(c, vec3(0.62, 0.35, 1.0), 0.55 * cv_bump(fract(x * 0.6 + t * 0.008), 0.0, 0.2, 0.3, 0.5));\n  c = mix(c, vec3(1.0), exp(-abs(y) / 0.05) * 0.3);\n  return c * (streak * up + base + refl) * smoothstep(1.3, 0.6, abs(x)) * (1.0 + 0.7 * both);\n}\n\n// veils: two walls of light lean in from the sides and recede to the point, like flying between curtains of aurora.\n// Their feet run away below the point, their tops are ragged, streaks pass toward the viewer. open is how far apart\nvec3 cv_planes(vec2 q, float t, float fly, vec3 cA, vec3 cB, vec3 cD, float open) {\n  float side = q.x < 0.0 ? -1.0 : 1.0;\n  float a = abs(q.x) - open;\n  // where they meet: a wide soft bloom along the level of the point, pale at the heart, pink rising above it and\n  // blue-violet pooling below, breathing. All glow, no edges\n  float br = 0.85 + 0.15 * sin(t * 0.11);\n  float bloom = exp(-abs(q.x) / 0.55) * br;\n  vec3 c = mix(cA, vec3(1.0, 0.92, 0.9), 0.55) * exp(-length(q * vec2(1.0, 2.2)) / 0.2) * 0.4 * br;\n  c += mix(cA, vec3(1.0, 0.55, 0.78), 0.5) * (max(q.y, 0.0) / 0.13) * exp(-max(q.y, 0.0) / 0.13) * bloom * 0.9;   // zero at the level of the point: no line\n  c += mix(mix(cA, vec3(1.0, 0.55, 0.78), 0.5), mix(cB, vec3(0.45, 0.4, 1.0), 0.5), smoothstep(-0.1, 0.1, -q.y)) * exp(-q.y * q.y / 0.012) * bloom * 0.3;  // and the two meet softly\n  c += mix(cB, vec3(0.45, 0.4, 1.0), 0.5) * (max(-q.y, 0.0) / 0.16) * exp(-max(-q.y, 0.0) / 0.16) * bloom * 0.8;\n  // moving inward: light runs out from the point along a floor and a ceiling and past the viewer\n  float ay = abs(q.y);\n  float pu = q.x / (ay + 0.02), pv = 0.35 / (ay + 0.02) + fly * 0.22;\n  float run = pow(cv_noise(vec3(pu * 2.2, pv * 0.35, q.y > 0.0 ? 3.0 : 8.0)), 3.0) * 1.6\n            + pow(cv_noise(vec3(pu * 6.0, pv * 0.6, q.y > 0.0 ? 5.0 : 9.0)), 5.0) * 1.4;\n  float beat = 0.6 + 0.4 * sin(pv * 1.3);                                // bands of brightness coming toward the viewer\n  vec3 rc = q.y > 0.0 ? mix(cA, vec3(1.0, 0.55, 0.78), 0.5) : mix(cB, vec3(0.45, 0.4, 1.0), 0.5);\n  c += rc * run * beat * smoothstep(0.015, 0.1, ay) * exp(-ay / 0.45) * exp(-abs(q.x) / 0.9) * 0.8;\n  if (a <= 0.0) return c;\n  float w = 1.0 / (a + 0.1) + fly * 0.45;                               // along the wall, coming toward the viewer\n  float hgt = (q.y + 0.45 * a) / (a + 0.03);                            // up the wall from its foot\n  float n1 = cv_noise(vec3(w * 0.9, side * 7.0, t * 0.05));\n  float n2 = cv_noise(vec3(w * 7.0, side * 3.0 + 5.0, t * 0.07));\n  float n3 = cv_noise(vec3(w * 0.8, side * 11.0, t * 0.03));\n  float streak = n1 * 0.9 + pow(n2, 4.0) * 0.35 + 0.25;\n  float topH = 0.7 + 0.5 * n3;\n  float shimmer = 0.6 + 0.4 * cv_noise(vec3(w * 5.0, hgt * 2.5 - t * 0.2, side));\n  float body = (hgt > 0.0 ? 1.0 - smoothstep(0.2 * topH, 1.5 * topH, hgt) : exp(hgt / 0.7)) * shimmer;   // no hard foot: they fade on down below\n  vec3 wc = mix(cA, cB, smoothstep(0.1, 1.1, hgt + 0.5 * (n3 - 0.5)));\n  wc = mix(wc, vec3(0.62, 0.35, 1.0), 0.55 * cv_bump(fract(w * 0.12), 0.0, 0.2, 0.35, 0.55));\n  float fade = smoothstep(0.0, 0.12, a) * (0.5 + 0.5 * exp(-a / 0.5));\n  return c + wc * streak * body * fade * 0.95;\n}\n// soft ribbons of colour swirling in toward the point: broad and blurred, pink, cyan and violet, with a pale heart\nvec3 cv_ribbons(vec2 q, float t, float fly, vec3 cA, vec3 cB, float spin) {\n  float rr = max(length(q), 0.0001);\n  float ang = atan(q.y, q.x);\n  float a2 = ang + 0.6 * rr - t * 0.02 + spin * 2.2 * exp(-rr * 1.5);  // arriving with the curtains' twist\n  float lr = log(rr);\n  float s1 = cv_noise(vec3(cos(a2) * 2.5, sin(a2) * 2.5, lr * 1.5 - fly * 0.2));\n  float s2 = cv_noise(vec3(cos(a2) * 6.0 + 4.0, sin(a2) * 6.0, lr * 3.0 - fly * 0.3));\n  float bands = smoothstep(0.45, 0.9, s1) * 0.8 + smoothstep(0.6, 1.0, s2) * 0.5;\n  float hue = cv_noise(vec3(cos(a2) * 1.5, sin(a2) * 1.5 + 9.0, rr * 2.0 + t * 0.01));\n  vec3 c = mix(cA, cB, smoothstep(0.3, 0.7, hue));\n  c = mix(c, vec3(0.6, 0.32, 1.0), smoothstep(0.55, 0.85, cv_noise(vec3(cos(a2) * 2.0, sin(a2) * 2.0 + 20.0, lr + t * 0.008))) * 0.6);\n  float wash = (0.2 + 0.8 * bands) * (0.3 + 0.7 * exp(-rr / 0.5));\n  return c * wash * 0.75 + vec3(1.0, 0.92, 0.97) * exp(-rr / 0.15) * 0.4;\n}\n\n// the echo: a soft airbrushed orb at the point, blue at heart, pink, a hot orange rim, and its delay taps: every\n// 2.4 s a half-dome of the same gradient leaves it along the horizon, flat edge behind, growing and softening as\n// it comes, pink to violet to blue, until it passes the viewer. Dub delay as a picture\nvec3 cv_echoOrb(vec2 q, float t, float dir) {\n  vec3 acc = vec3(0.0);\n  float R0 = 0.085 * (1.0 + 0.06 * sin(t * 0.8));\n  float Tp = 2.4;\n  float ph = fract(t / Tp);\n  for (int k = 6; k >= 0; k--) {\n    float s = (ph + float(k)) / 7.0;                                     // 0 just born, 1 gone past\n    float cx = dir * (R0 * 0.5 + 1.5 * pow(s, 1.6));\n    float Rk = R0 * (0.9 + 7.0 * s);\n    float blur = 0.006 + 0.05 * s;\n    vec2 dq = q - vec2(cx, 0.0);\n    float dist = length(dq);\n    float a = (1.0 - smoothstep(Rk - blur, Rk + blur, dist)) * smoothstep(-blur * 0.3, blur * 0.7, dq.x * dir);\n    float rimG = smoothstep(0.5, 1.0, dist / Rk);\n    vec3 inner = mix(mix(vec3(1.0, 0.35, 0.55), vec3(0.6, 0.25, 1.0), smoothstep(0.1, 0.5, s)), vec3(0.2, 0.3, 1.0), smoothstep(0.45, 0.9, s));\n    vec3 rim = mix(vec3(1.0, 0.55, 0.2), vec3(1.0, 0.4, 0.75), smoothstep(0.2, 0.7, s));\n    vec3 c = mix(inner * (0.6 + 0.4 * dist / Rk), rim, rimG * rimG);\n    float fade = pow(1.0 - s, 1.3) * smoothstep(0.0, 0.06, s);\n    acc = mix(acc, c, a * fade);\n    acc += rim * exp(-max(dist - Rk, 0.0) / (0.02 + 0.05 * s)) * step(0.0, dq.x * dir) * fade * 0.18;   // the rim glows a little\n  }\n  float r = length(q);\n  float x = r / R0;\n  vec3 oc = mix(vec3(0.15, 0.3, 1.0), vec3(1.0, 0.3, 0.6), smoothstep(0.25, 0.7, x));\n  oc = mix(oc, vec3(1.0, 0.58, 0.15), smoothstep(0.7, 1.0, x));\n  acc = mix(acc, oc, 1.0 - smoothstep(0.92, 1.12, x));\n  acc += vec3(0.5, 0.25, 0.95) * exp(-max(r - R0, 0.0) / 0.16) * 0.35;      // violet air round it\n  return acc;\n}\n// the domes: two great airbrushed domes, one above the point and one below, thin glowing rims, a pale band between.\n// Blue over a hot red edge above, pink and orange going to brown below. They come out of the point in pairs and open\n// past the viewer, each new pair nested inside the last: moving inward between them\nvec3 cv_domes(vec2 q, float t, float fly, float sMax, float sMin) {\n  vec3 acc = vec3(0.0);\n  float ph = fract(fly * 0.06);\n  float top = q.y > 0.0 ? 1.0 : 0.0;\n  vec3 hot = mix(vec3(1.0, 0.5, 0.78), vec3(1.0, 0.33, 0.22), top);\n  vec3 deep = mix(vec3(1.0, 0.5, 0.12), vec3(0.15, 0.35, 1.0), top);\n  vec3 far = mix(vec3(0.3, 0.12, 0.05), vec3(0.05, 0.05, 0.3), top);\n  for (int k = 3; k >= 0; k--) {\n    float s = ph + float(k);                                             // 0 kissing at the point, 4 opened past the frame\n    float g = 0.012 * exp(s * 1.15) - 0.012;                             // half the opening between this pair\n    float R = 1.25 + 0.1 * sin(t * 0.13 + float(k) * 1.7);\n    float d = length(q - vec2(0.0, (q.y > 0.0 ? 1.0 : -1.0) * (R + g)));\n    float thick = 1.6 * g + 0.035;                                       // each dome is a band of colour behind its rim, clear beyond\n    float u = (R - d) / thick;\n    float soft = 0.022 + 0.09 * g;                                       // airbrushed: no hard edge anywhere\n    float inside = smoothstep(-soft, soft * 0.6, R - d);\n    vec3 c = mix(hot, deep, smoothstep(0.0, 0.5, u));\n    c = mix(c, far, smoothstep(0.4, 1.1, u));\n    float alpha = inside * (1.0 - smoothstep(0.35, 1.4, u));\n    float a = smoothstep(0.0, 0.5, s) * (1.0 - smoothstep(3.3, 4.0, s));\n    a *= (1.0 - smoothstep(sMax - 0.6, sMax, s)) * smoothstep(sMin - 0.6, sMin, s);   // they arrive from the point and the last ones leave past the viewer\n    acc = mix(acc, c, alpha * a);\n    acc += mix(hot, vec3(1.0, 0.85, 0.9), 0.45) * exp(-(d - R) * (d - R) / (soft * soft * 1.5)) * 0.4 * a;   // the rim is a soft glow, not a line\n    acc += vec3(0.78, 0.68, 1.0) * (1.0 - inside) * exp(-max(d - R, 0.0) / (0.5 * g + 0.04)) * 0.16 * a;   // pale air in the opening\n  }\n  return acc;\n}\n// the dub pulse in the light: nothing drawn of its own. A wave leaves the point on the pulse and widens past the\n// viewer, and whatever light it crosses flares and turns a saturated colour for a moment: violet, gold, pink, cyan\n// in turn. Returns the colour in rgb and the strength in a\nvec4 cv_pulse(vec2 q, float t) {\n  float rr = max(length(q), 0.0001);\n  float P = 7.2;\n  float e0 = floor(t / P) * P;\n  vec4 acc = vec4(0.0);\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float age = t - (e0 - fk * P);\n    float id = mod(e0 / P - fk, 4.0);\n    float R = 0.04 * exp(age * 0.26);\n    float dR = (rr - R) / (0.28 * R + 0.02);\n    float wv = exp(-dR * dR) * smoothstep(0.0, 1.5, age) * (1.0 - smoothstep(1.2, 2.2, R));\n    vec3 sc = id < 0.5 ? vec3(0.6, 0.2, 1.0) : (id < 1.5 ? vec3(1.0, 0.68, 0.1) : (id < 2.5 ? vec3(1.0, 0.22, 0.6) : vec3(0.1, 0.85, 1.0)));\n    acc += vec4(sc * wv, wv);\n  }\n  return acc;\n}\n// sparks of saturated colour gather in the ribbons and orbit the point: arcs of violet, gold and pink at different\n// depths, each its own speed, comet-like; at the end they widen and pass the viewer\nvec3 cv_halo(vec2 q, float t, vec3 cA, vec3 cB, float grow) {\n  float rr = max(length(q), 0.0001);\n  float ang = atan(q.y, q.x);\n  vec3 acc = vec3(0.0);\n  for (int k = 0; k < 5; k++) {\n    float fk = float(k);\n    float R = (0.16 + 0.085 * fk + 0.02 * sin(t * 0.3 + fk * 2.0)) * (1.0 + 5.0 * grow * grow);\n    float dir = mod(fk, 2.0) < 0.5 ? 1.0 : -1.0;\n    float a = ang * dir + t * (0.22 + 0.06 * fk) + fk * 1.9 + 1.2 * log(rr);   // trailing back along the ribbons' swirl\n    float head = pow(0.5 + 0.5 * sin(a), 6.0);                          // a bright head\n    float tail = pow(0.5 + 0.5 * sin(a - 0.9), 3.0) * 0.2;             // and a softer tail behind it\n    float w = R * (0.012 + 0.06 * head);\n    float dr = rr - R;\n    vec3 lc = k == 0 ? vec3(0.62, 0.25, 1.0) : (k == 1 ? vec3(1.0, 0.7, 0.15) : (k == 2 ? vec3(1.0, 0.3, 0.65) : (k == 3 ? vec3(0.2, 0.85, 1.0) : vec3(0.62, 0.25, 1.0))));\n    acc += (lc * (head + tail) + vec3(1.0) * pow(head, 4.0) * 0.6) * exp(-dr * dr / (w * w));\n  }\n  return acc * 0.85 * (1.0 - smoothstep(0.6, 1.0, grow));\n}\n\n// the sparkle field: glints streaming past through the same angled space, streaking as they come close.\n// q is screen position from the vanishing point, fly the distance flown, roll the space's angle, dens how many\n// fat swells each glint, for the rays it stretches into (0 as always)\nvec3 cv_glints(vec2 q, float fly, float roll, float dens, vec3 cA, vec3 cB, float px, float t, float fat) {\n  vec3 acc = vec3(0.0);\n  for (int i = 0; i < 4; i++) {\n    float fi = float(i);\n    float ph = fract(fly * 0.14 + fi / 4.0);\n    float zoom = pow(8.0, ph);\n    float cs = 0.035 * zoom;\n    vec2 uvG = q / cs + vec2(fi * 17.0, fi * 5.3);\n    vec2 id = floor(uvG);\n    float h = cv_hash(vec3(id, fi + 70.0));\n    if (h > dens) continue;\n    vec2 off = vec2(cv_hash(vec3(id, fi + 71.0)), cv_hash(vec3(id, fi + 72.0))) - 0.5;\n    vec2 pc = (id + 0.5 + off * 0.6) * cs - vec2(fi * 17.0, fi * 5.3) * cs;   // where this glint sits on screen\n    // only inside the slab between the cloud floor and ceiling\n    float wy = cv_rot(pc, -roll).y * 14.0 / zoom;\n    float slab = smoothstep(-2.4, -1.6, wy) * (1.0 - smoothstep(1.8, 2.6, wy));\n    if (slab < 0.001) continue;\n    vec2 dd = q - pc;\n    vec2 dirR = pc / max(length(pc), 0.0001);\n    float along = dot(dd, dirR) / (1.0 + 2.5 * ph * ph);\n    float across = dot(dd, vec2(-dirR.y, dirR.x));\n    float dist = length(vec2(along, across));\n    float rad = px * (0.8 + 2.5 * ph) * (1.0 + fat);\n    float core = 1.0 - smoothstep(rad * 0.5, rad * 1.5, dist);\n    float star = exp(-dist / (rad * 2.5)) * 0.4;\n    float tw = pow(smoothstep(0.55, 1.0, 0.5 + 0.5 * sin(t * 0.6 + h * 50.0 / max(dens, 0.01))), 2.0);   // only while it sparkles\n    tw = mix(tw, 0.75, min(fat / 3.0, 1.0));                            // stretched into a ray, it holds steady\n    float a = smoothstep(0.0, 0.3, ph) * (1.0 - smoothstep(0.8, 1.0, ph));\n    acc += mix(cA, cB, step(0.5, cv_hash(vec3(id, fi + 73.0)))) * (core + star) * tw * a * slab;\n  }\n  return acc;\n}\n// The sparkles stretching into rays: the sparkle field smeared along lines to the vanishing point, so each sparkle\n// draws a ray back toward the point (sparse, some thin and sharp, the bigger soft ones wide and blurred), with a grain\n// from the scattered samples. L is how far each ray reaches in, as a multiple of its distance out; fat swells them.\n// spread blurs each ray sideways, softly, up to about a spoke's width, so the rays widen into soft fans that the\n// blades then take shape in (no snapping: nothing jumps between neighbouring spokes). jit is a fixed per-pixel\n// scatter. At L 0 and spread 0 it is exactly the sparkle field\n// align gathers each spoke's streaks into a narrow band along its centre line, the ball's own spokes (twistA their\n// twist), dark between: each spoke's content is squeezed toward its centre rather than moved, so nothing crosses from\n// one spoke to the next and nothing is cut off\nvec3 cv_streaks(vec2 q, float r, float fly, float roll, float dens, vec3 cA, vec3 cB, float px, float t, float L, float fat,\n                float spread, float jit, float align, float twistA) {\n  float ang = atan(q.y, q.x);\n  float band = 1.0;\n  if (align > 0.001) {\n    float sN = (ang + twistA) / 6.2832 * 40.0;\n    float c = floor(sN) + 0.5;\n    float ds = (sN - c) / (1.0 - min(align, 0.82));                                 // where in the spoke this point's light comes from\n    float sg = mix(1.2, 0.12, min(align / 0.82, 1.0));                   // a smooth falloff from each centre line: no edges\n    sg *= 1.0 - 0.55 * clamp((align - 0.82) / 0.18, 0.0, 1.0);           // past 0.82: the soft light behind the lines fades\n    band = exp(-(sN - c) * (sN - c) / (2.0 * sg * sg)) / exp(-0.0);\n    ang = (c + clamp(ds, -0.5, 0.5)) / 40.0 * 6.2832 - twistA;\n  }\n  if (L < 0.001) return cv_glints(vec2(cos(ang), sin(ang)) * r, fly, roll, dens, cA, cB, px, t, fat) * band;\n  vec3 acc = vec3(0.0);\n  float wsum = 0.0;\n  for (int i = 0; i < 24; i++) {\n    float u = (float(i) + jit) / 24.0;\n    float w = 1.0 - 0.7 * u;                                             // brightest at the sparkle, fading toward the point\n    float a2 = ang + (fract(jit * 7.31 + float(i) * 0.618) - 0.5) * spread * 0.19;   // 0.19: a little over a spoke\n    acc += cv_glints(vec2(cos(a2), sin(a2)) * r * (1.0 + L * u), fly, roll, dens, cA, cB, px, t, fat) * w;\n    wsum += w;\n  }\n  return acc / wsum * (1.0 + 0.8 * min(L, 1.0)) * band * (1.0 + 1.5 * align);   // the gathered light is brighter\n}\n\n// ---------------------------------------------------------------- main\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  float aspect = RENDERSIZE.x / RENDERSIZE.y;\n  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);\n  float px = 1.0 / RENDERSIZE.y;\n\n  float tR = TIME * timeScale;                                          // real time\n  float t = tR + (motion - 1.0) * cv_intSS(tR, 20.0, 80.0);            // motion time: section 4's pace, easing to Speed by 1:20\n  float mN = min(tR / 60.0, 43.5);                                      // real minutes, 0-43.5\n  float mR = cv_old(mN);                                                // v2's real minutes: every mR timing below\n  float mRaw = cv_warp(min(mR, 33.5));\n  float hold = cv_hold(mRaw);\n  float mA = mRaw - hold;                                               // the v1 arc's minutes, 0-30\n  float uRep = clamp(mN - R0, 0.0, R1 - R0);                            // minutes into the reprise\n  float sink = smoothstep(0.0, 1.5, uRep);                              // the ball sinks back into the depth\n  float xr = cv_repTravel(uRep);\n  float mL = uRep > 0.0 ? cv_repArc(uRep) : mA;                         // the light's arc: the reprise replays ribbons and veils\n  float brk = smoothstep(R1, R1 + 1.2, mN);                             // after it, the veils' light breaks up into bokeh\n  float lightK = 1.0 - smoothstep(R1 + 0.6, R1 + 2.0, mN);\n  float spd = mix(1.0, motion, smoothstep(0.3, 1.5, tR / 60.0));\n  float trav = (ARC_travel(mA, H) + 1.2 * hold + xr) * spd;           // the ball's travel keeps its pace through the hold\n  float kClose = close;\n  // Hit: a punch on the beat that flares the light and the sparkles\n  float punch = hitAge < 6.0 ? (1.0 - exp(-hitAge / 0.05)) * exp(-hitAge / 1.2) : 0.0;\n  // the warmth (James: \"the warmth of the colors might be a good hit transition\"): the first Hit between 17:00 and\n  // 20:00 turns the light hot pink and orange over six seconds, with a swell on the beat; unpressed, at 20:00\n  float pressM = cv_old(max(mN - hitAge / 60.0, 0.0)), prevM = cv_old(max(mN - hitPrevAge / 60.0, 0.0));\n  float WW = 20.0;\n  if (prevM >= 17.0 && prevM <= 20.0) WW = prevM;\n  else if (pressM >= 17.0 && pressM <= 20.0) WW = pressM;\n  float wsec = (mR - WW) * 60.0;\n  float warm = smoothstep(0.0, 3.0, wsec);\n  float warmSwell = 0.8 * exp(-max(wsec, 0.0) / 1.8) * step(0.0, wsec);\n\n  vec3 cD, cA, cB;\n  // in the reprise the light cools back toward the ribbons' own pink, cyan and violet, warming again into the bokeh\n  cv_palette(palette, ARC_key(mA, H, warm) - 0.7 * smoothstep(0.5, 3.0, uRep) * (1.0 - smoothstep(25.9, 29.5, mA)), cD, cA, cB);\n  float bright = ARC_bright(mA, H) * ARC_dim(mA) * (1.0 + 0.3 * punch + warmSwell);\n\n  vec3 col = vec3(0.0);\n\n  // ------------------------------------------------ A. section 4's end: its bands, its bloom receding, its haze\n  float t4 = tR + 3260.0;                                               // section 4 v2's clock: its 19:30 at Speed 1\n  float s4 = ARC_s4(mA);\n  vec2 pr = cv_rot(p, -0.32);\n  float rowY = (pr.y + 0.5) * 18.0;\n  float row = floor(rowY);\n  float hr = cv_hash(vec3(row, 5.0, 9.0));\n  float ph4 = t4 / (2.5 + 2.0 * hr) + hr * 5.0;\n  float off4 = mix(cv_hash(vec3(row, floor(ph4), 1.0)), cv_hash(vec3(row, floor(ph4) + 1.0, 1.0)), smoothstep(0.0, 0.35, fract(ph4))) - 0.5;\n  vec2 pb = pr + vec2(off4 * 0.3 * s4 * 0.4 * step(0.3, hr), 0.0);\n  float rec = ARC_recede(mA);\n  if (rec < 0.999) {\n    float R = 0.35 * (1.0 + 0.03 * sin(t4 * 0.13)) * 1.5 * mix(1.0, 0.0, rec);\n    vec4 b = cv_s4Bloom(pb, R, 31.0, 0.9 + 0.2 * sin(t4 * 0.021), vec3(0.46, 0.41, 0.56), vec3(0.74, 0.69, 0.84), t4, px, 0.35);\n    col = cv_screen(col, b.rgb * (1.0 - rec * rec));\n  }\n  if (s4 > 0.001) {\n    float fy = fract(rowY);\n    float gap = 1.0 - smoothstep(0.0, 0.5, fy) * (1.0 - smoothstep(0.5, 1.0, fy));\n    col *= 1.0 - s4 * 0.45 * gap;\n  }\n  float h4 = ARC_haze4(mA);\n  if (h4 > 0.001) {\n    vec2 hq = pr * vec2(1.0, 2.6) + vec2(t4 * 0.004, 0.0);\n    float cloud = cv_fbm(vec3(hq * 1.3 + vec2(cv_fbm(vec3(hq * 0.8, t4 * 0.006)), 0.0), t4 * 0.008));\n    vec3 hazeCol = vec3(0.42, 0.38, 0.52) * smoothstep(0.3, 0.8, cloud) * (0.6 + 0.4 * smoothstep(-0.5, 0.5, p.y));\n    col = cv_screen(col, hazeCol * 0.6 * h4);\n  }\n\n  // ------------------------------------------------ the frame: a vanishing point that drifts, and a horizon that banks\n  float fly = trav * 36.0;\n  float roll = ARC_roll(mA, t);\n  // Jen: the ball should come up where the old one did. It arrives 106 s earlier, so over the rays the drift eases\n  // ahead to where it was at the old arrival, and eases back onto its own path through the ball's hold\n  float tv = t + 106.0 * motion * cv_bump(mR, 19.3, 20.9, 23.3, 26.3);\n  vec2 vp = smoothstep(3.4, 5.0, mA) * vec2(0.22 * sin(tv * 0.014 + 0.4), 0.08 * sin(tv * 0.019)) - vec2(0.0, 0.3 * ARC_lower(mA));\n  vec2 q = p - vp;\n  float r = max(length(q), 0.0001);\n  float d = 0.18 / r;                                                   // depth\n  float twistA = 0.005 * t + 0.25 * d;                                 // a few degrees a minute, spiralling with depth\n  vec2 qt = cv_rot(q, twistA);\n  float angS = atan(qt.y, qt.x);\n  float z = d + trav * 4.0;\n  // in the mirror ball the travel is felt: the tiles stream past, easing off as it shatters\n  float zb = 20.0 * (cv_rampInt(mA, H + 0.3, H + 1.2) + hold + xr - cv_rampInt(mA, H + 5.4, H + 6.4) * 0.85) * spd;\n  float fog = smoothstep(0.02, 0.2, r);\n  float thin = 1.0 - smoothstep(0.0, 1.0, kClose);                     // Close: thins it all to black\n\n  // ------------------------------------------------ dub echoes in the light: a swell, then fainter repeats\n  float ea = ARC_echo(mA) * echo;\n  float echoT = 0.0;\n  if (ea > 0.001) {\n    float P = 14.0;\n    float e0 = floor(t / P) * P;\n    for (int c = 0; c < 2; c++) {\n      for (int k = 0; k < 4; k++) {\n        float age = t - (e0 - float(c) * P) - float(k) * 1.8;\n        if (age < 0.0) continue;\n        echoT += pow(0.6, float(k)) * (1.0 - exp(-age * 2.0)) * exp(-age * 0.7);\n      }\n    }\n    echoT *= ea;\n  }\n\n  // the mirror ball's extent (used by the light behind it and by the tiles): it opens out of the depth from 20:58 (v2's\n  // clock), and in the reprise sinks back into it, the ribbons opening round it\n  float uD = clamp((mR - 20.97) / 1.33, 0.0, 1.0);\n  float disco = 1.0 - (1.0 - uD) * (1.0 - uD);\n  float rayK = smoothstep(19.25, 19.5, mR) * (1.0 - smoothstep(21.8, 22.2, mR)) * thin;\n  float wr = 1.7 * disco * (1.0 - sink * sink * (3.0 - 2.0 * sink));\n  float mT = (1.0 - smoothstep(wr - 0.18 - 0.17 * rayK, wr + 0.04, r)) * step(0.001, disco) * step(0.001, wr);   // the mirror ball, from the centre out; a softer rim where the rays run into it\n\n  // the bokeh, worked out here so the veils' light can break up into it\n  float bk = ARC_bokeh(mA, H) * bokeh * thin;\n  vec3 bc = vec3(0.0);\n  if (bk > 0.001 || brk > 0.001) {\n    float dens = mix(0.25, 0.42, smoothstep(0.0, 0.6, bk)) * (1.0 - 0.45 * smoothstep(27.5, 30.0, mA));\n    bc = cv_bokeh(q, trav * 0.5, cA, cB, cD, dens, px, t);\n  }\n\n  // ------------------------------------------------ B. flying through the cloud toward the light\n  vec2 qh = cv_rot(q, -roll);                                           // along the horizon\n  float swell = 1.0 + 0.6 * echoT;\n  vec3 light = vec3(0.0);\n  float fl = ARC_flare(mL);\n  if (fl > 0.001) light += cv_flare(qh, t, cA, cB) * fl;\n  float co = ARC_core(mL);\n  if (co > 0.001) light += mix(vec3(1.0), cB, 0.25) * (0.9 * exp(-length(q) / 0.012) + 0.3 * exp(-length(q) / 0.08)) * co;\n  float stm = ARC_streams(mL);\n  float stl = ARC_streamsL(mL);\n  float dm = cv_bump(mL, 1.55, 1.65, 3.7, 3.8);                          // only once the flare has gone\n  if (dm > 0.001) light += cv_domes(q, t, fly, 0.9 + 3.7 * smoothstep(1.6, 2.6, mL), 4.6 * smoothstep(2.8, 3.7, mL)) * dm;                    // the domes open from the point, pair after pair\n  float pl = ARC_planes(mL);\n  if (pl > 0.001) light += cv_planes(qh, t, fly, cA, cB, cD, ARC_open(mL)) * pl;\n  float au = ARC_aurora(mL);\n  if (au > 0.001) light += cv_aurora(qh, t, cA, cB, ARC_twist(mL), ARC_both(mL)) * au * (1.0 - 0.55 * pl);\n  float rb = ARC_ribbons(mL);\n  if (rb > 0.001) light += cv_ribbons(qh, t, fly, cA, cB, 1.0 - smoothstep(11.8, 12.8, mL)) * rb;\n  float hl = ARC_halo(mL);\n  if (hl > 0.001) light = light * (1.0 - 0.3 * hl) + cv_halo(q, t, cA, cB, ARC_haloGrow(mL)) * hl;\n  float rg = ARC_rings(mL, H) * echo;\n  if (rg > 0.001) {\n    vec4 pw = cv_pulse(q, t) * rg;\n    float lum = dot(light, vec3(0.3, 0.5, 0.2));\n    light = mix(light, pw.rgb / max(pw.a, 0.001) * lum * 2.0, min(0.55 * pw.a, 0.6)) * (1.0 + 0.7 * pw.a);\n  }\n  // in the reprise the light is behind the sinking ball; after it, its light gathers into the bokeh's points and goes\n  light *= (1.0 - mT * step(0.001, uRep)) * mix(1.0, clamp(dot(bc, vec3(0.3, 0.5, 0.2)) * 4.0, 0.0, 1.5), brk) * lightK;\n  col = cv_screen(col, light * swell * thin);\n\n  // ------------------------------------------------ Hit: a warm burst from the point on the beat, a glow and a ring of hot\n  // pink and orange rushing outward through the light; the press that brings the warmth is the bigger one\n  for (int i = 0; i < 2; i++) {\n    float age = i == 0 ? hitPrevAge : hitAge;\n    if (age > 4.0) continue;\n    float big = abs(cv_old(max(mN - age / 60.0, 0.0)) - WW) < 0.002 ? 1.8 : 1.0;\n    float rr = age * 0.75;\n    float wdt = 0.05 + age * 0.06;\n    float ring = exp(-(r - rr) * (r - rr) / (wdt * wdt)) * exp(-age / 1.1);\n    float glow = exp(-r / 0.18) * exp(-age / 0.5);\n    vec3 hc = mix(vec3(1.0, 0.3, 0.62), vec3(1.0, 0.55, 0.15), 0.5 + 0.5 * sin(atan(q.y, q.x) * 3.0 + age));\n    col = cv_screen(col, hc * (0.55 * ring + 0.9 * glow) * big * smoothstep(0.0, 0.04, age) * thin);\n  }\n\n  // the rays, in real minutes (Jen: the sparkles become the rays, like refs 33 and the burst, then into the tunnel the\n  // way the old one went): from 19:15 the sparkles stretch back toward the point into rays, which reach further in,\n  // swell and widen softly, streaming the whole time. At 21:05 the mirror ball comes up out of the depth as in v28,\n  // and the rays still ahead of it shrink back into streaming sparkles, as the old dots did\n  // Jen: the disco comes in from 21:10, as the soft rays behind the lines fade: it opens out of the depth from 20:58,\n  // quickly at first and easing as it comes up round the viewer, fully open at 22:18 as before\n  float stretch = smoothstep(19.25, 20.4, mR) * (1.0 - smoothstep(21.3, 22.2, mR));      // streaks until the ball is up\n  float rayFat = smoothstep(19.25, 20.4, mR) * (1.0 - 0.8 * smoothstep(20.8, 21.15, mR));  // soft until 20:50, then sharpening as they break\n  // Jen: the pulse over the slow rays felt incongruous, but the old ball had pulses going in as it emerged. The dub\n  // echoes hold off while the sparkles stretch into rays, and come back as the ball comes up (21:05-21:20)\n  float calm = 1.0 - cv_bump(mR, 19.8, 20.3, 21.05, 21.33);\n  float snap = 0.35 * smoothstep(19.95, 20.6, mR) * (1.0 - smoothstep(20.8, 21.15, mR));   // how far the rays have spread sideways\n  float gl = (max(ARC_glint(mL, H) * lightK, rayK) * (1.0 - mT * rayK * mix(1.0, 0.5, smoothstep(0.35, 1.0, r / max(wr, 0.001)))) + ARC_discoGlint(mA, H) * (1.0 - sink)) * thin;   // the lines run on into the ball along its columns, fading inward\n  if (gl > 0.001) {\n    // Janet: the floating specks before the hit barely showed on the projector; brighter and more saturated there\n    float boost = max(cv_bump(mA, 14.5, 16.0, H + 0.5, H + 1.5), rayK * (1.0 - mT));   // and the rays keep it\n    vec3 g = (rayK > 0.001 ? cv_streaks(q, r, fly, roll, ARC_sparks(mL, H), cA, cB, px, t, 3.0 * stretch, 1.5 * rayFat * stretch, snap,\n                                        cv_hash(vec3(uv * RENDERSIZE, 7.0)), (0.82 * smoothstep(20.8, 21.15, mR) + 0.18 * smoothstep(21.15, 21.45, mR)) * rayK, twistA)\n                           : cv_glints(q, fly, roll, ARC_sparks(mL, H), cA, cB, px, t, 0.0))\n           * gl * (1.0 + 0.5 * echoT * calm) * (1.0 + 0.7 * boost + 1.2 * punch);\n    // Jen: soft rays, then they break up, sharpening as they break, and the twinkles come. From 20:50 each line splits\n    // into pieces along its spoke that stream with the tunnel's travel, staggered spoke to spoke\n    float brk = smoothstep(21.0, 21.25, mR) * rayK;                 // once they are thin lines, so no seams show\n    if (brk > 0.001) {\n      float sId = floor((angS) / 6.2832 * 40.0);\n      float zzL = (z + zb - 0.18 / r) * 1.2 - log(r) * 40.0 / 6.2832;   // the tiles' depth, so the pieces move with them\n      float fb = fract(zzL * 0.5 + cv_hash(vec3(sId, 44.0, 1.0)));\n      g *= mix(1.0, smoothstep(0.0, 0.06, fb) * (1.0 - smoothstep(0.45, 0.6, fb)), brk);\n    }\n    g = max(mix(vec3(dot(g, vec3(0.3, 0.59, 0.11))), g, 1.0 + 0.45 * boost), 0.0);\n    col = cv_screen(col, g);\n  }\n\n  // ------------------------------------------------ dub echoes: rings of light travel into the tunnel, each with fainter repeats\n  float echoL = 0.0;\n  if (ea > 0.001 && ARC_tunnel(mA, H) + ARC_bokeh(mA, H) > 0.001) {\n    float P = 7.2;                                                      // a steady pulse travelling in\n    float e0 = floor(t / P) * P;\n    for (int c = 0; c < 2; c++) {\n      for (int k = 0; k < 4; k++) {\n        float age = t - (e0 - float(c) * P) - float(k) * 1.8;\n        if (age < 0.0) continue;\n        float dp = 0.2 + age * 0.3;\n        float sg = 0.12 * (1.0 + dp * 0.5);\n        echoL += pow(0.6, float(k)) * exp(-(d - dp) * (d - dp) / (sg * sg)) * smoothstep(0.0, 1.0, age);\n      }\n    }\n    echoL *= ea * calm;\n  }\n\n  // ------------------------------------------------ C. mirror-ball tiles\n  float tun = ARC_tunnel(mA, H) * thin * (1.0 - sink);\n  // the dots along the lines, twinkling like the ball's tiles, as the lines break and the ball comes up through them\n  float dotK = smoothstep(20.95, 21.25, mR) * (1.0 - smoothstep(21.6, 22.0, mR)) * thin;   // the twinkles, only as it comes\n  if (dotK > 0.001 && mT < 0.999)\n    col += cv_dots(q, r, angS, z + zb * 0.2, 1.0, cA, cB, px, t, 0.0, 0.7) * dotK * (1.0 - mT) * fog * 1.1;\n  if (tun > 0.001) {\n    vec3 tl = vec3(0.0);\n    if (mT > 0.001) tl += cv_tiles(q, r, angS, z + zb, cD, cA, cB, px, t, ARC_shatter(mA, H)) * mT;\n    tl *= 1.0 + 1.3 * echoL;\n    tl += (cA * 0.5 + cD) * 0.25 * echoL * smoothstep(0.1, 0.4, r) * (1.0 - smoothstep(0.6, 1.0, r));  // the ring itself, faint\n    col += tl * fog * tun * 1.1;\n    col += cD * 1.5 * exp(-r * 5.0) * tun;                            // the glow down the tunnel\n  }\n\n  // ------------------------------------------------ D. bokeh\n  if (bk > 0.001) {\n    bc *= 1.0 + 0.6 * punch;\n    col = cv_screen(col, bc * min(bk, 1.2));\n    col += cD * 0.6 * smoothstep(H + 5.9, H + 6.8, mA) * (1.0 - tun) * thin; // the room behind the lights\n  }\n\n  // ------------------------------------------------ brightness, the hit's black, Blackout\n  float ramp = smoothstep(0.0, 2.0, mA);                                 // section 4's frame is left exactly as it was\n  col *= mix(1.0, bright, ramp);\n  col *= ARC_end(mA);                                                   // the end of the night\n\n  col = clamp(col, 0.0, 1.0);\n  col += (cv_hash(vec3(uv * RENDERSIZE, 1.0)) - 0.5) / 255.0 * step(0.0005, max(col.r, max(col.g, col.b)));   // dither, but black stays black\n  gl_FragColor = vec4(col, 1.0);\n}\n","decl":"uniform float timeScale;uniform float speed;uniform float hitAge;uniform float hitPrevAge;","def":{"timeScale":1.0,"speed":1.0,"hitAge":100000.0,"hitPrevAge":100000.0},"len":2610.0}];
